window.__D("text/zohar/c008",{"p":[[9520011342,"<p>וַיְצַו אֹתָם לֵאמֹר כֹּה תֹאמְרוּן לַאדֹנִי לְעֵשָׂו כֹּה אָמַר עַבְדְּךָ יַעֲקֹב עִם לָבָן גַּרְתִּי וָאֵחַר עַד עָתָּה. מִיָּד פָּתַח יַעֲקֹב לְאִתְהַפָּכָא לֵיהּ לְעַבְדָּא, בְּגִין דְּלָא יִסְתַּכַּל עֵשָׂו בְּאִינוּן בִּרְכָאן דְּבָרְכֵיהּ אֲבוֹי, דְּהָא יַעֲקֹב סָלִיק לוֹן לְבָתַר כְּדְקָא אֲמָרָן.</p>\n<p>אָמַר רִבִּי יְהוּדָה מַאי חָמָא יַעֲקֹב דְּשַׁדַּר לֵיהּ לְעֵשָׂו וְאָמַר עִם לָבָן גַּרְתִּי, וְכִי מַה עָבִיד בִּשְׁלִיחוּתֵיהּ דְּעֵשָׂו (דאמר) מִלָּה דָא. אֶלָּא לָבָן הָאֲרַמִּי קָלֵיהּ אָזִיל בְּעַלְמָא דְלָא הֲוָה בַר נָשׁ דְּיִשְׁתְּזִיב מִנֵּיהּ, דְּהוּא הֲוָה חָרָשׁ בֶּחֳרָשִׁין וְרַב בְּקוֹסְמִין, וַאֲבוֹי דִבְעוֹר הֲוָה, וּבְעוֹר אֲבוֹי דְבִלְעָם, דִּכְתִיב (יהושע י״ג:כ״ב) בִּלְעָם בֶּן בְּעוֹר הַקּוֹסֵם, וְלָבָן חָכָם בֶּחֳרָשִׁין וְקוֹסְמִין יַתִּיר מִכֻּלְּהוּ, וְעִם כָּל דָּא לָא יָכִיל בְּיַעֲקֹב. וּבָעָא לְאוֹבָדָא לְיַעֲקֹב בְּכַמָּה זַיְינִין הֲדָא הוּא דִכְתִיב, (דברים כ״ו:ה׳) אֲרַמִּי אוֹבֵד אָבִי.</p>\n<p>אָמַר רִבִּי אַבָּא כּוּלֵי עַלְמָא הֲוֵי יָדְעֵי דְּלָבָן הֲוָה רַב חַכִּימִין וָחֳרָשִׁין וְקוֹסְמִין, וּמַאן דְּבָעֵי לְאוֹבָדָא בֶּחֳרָשׁוֹי לָא אִשְׁתְּזִיב מִנֵּיהּ, וְכָל מַה דְּיָדַע בִּלְעָם מִנֵּיהּ הֲוָה. וּכְתִיב בֵּיהּ בְּבִלְעָם (במדבר כ״ב:ו׳) כִּי יָדַעְתִּי אֵת אֲשֶׁר תְּבָרֵךְ מְבֹרָךְ וַאֲשֶׁר תָּאֹר יוּאָר. וְכוּלֵי עַלְמָא הֲווּ מִסְתָּפֵי מִלָּבָן וּמֵחֳרָשׁוֹי, וּמִלָּה קַדְמָאָה דְּשַׁדַּר יַעֲקֹב לְעֵשָׂו אָמַר עִם לָבָן גַּרְתִּי. וְאִי תֵימָא דִּזְעֵיר הֲוָה יֶרַח אוֹ שַׁתָּא. לָאו הָכִי, אֶלָּא וָאֵחַר עַד עָתָּה, עֶשְׂרִין שְׁנִין אִתְאֲחָרִית עִמֵּיהּ.</p>\n<p>וְאִי תֵימָא דְּלָא סָלִיק בְּיָדִי כְּלוּם. וַיְהִי לִי שׁוֹר וַחֲמוֹר, אִינוּן תְּרֵין גִּזְרֵי דִינִין, דְּכַד מִתְחַבְּרָן תַּרְוַויְיהוּ כְּחֲדָא, לָא מִתְחַבְּרָן אֶלָא לְאַבְאָשָׁא עַלְמָא. וּבְגִין כָּךְ כְּתִיב, (דברים כ״ב:י׳) לֹא תַחֲרשׁ בְּשׁוֹר וּבַחֲמוֹר יַחְדָּו.</p>\n<p>צֹאן וְעֶבֶד וְשִׁפְחָה, אִלֵין אִינוּן כִּתְרֵי תַּתָּאֵי דְּקָטַל קוּדְשָׁא בְּרִיךְ הוּא בְּמִצְרַיִם (שמות י״ב:כ״ט) בְּכוֹר בְּהֵמָה (שמות י״ב:כ״ט) בְּכוֹר הַשְּׁבִי (שמות י״א:ה׳) בְּכוֹר הַשִּׁפְחָה, הֲדָא הוּא דִכְתִיב צֹאן וְעֶבֶד וְשִׁפְחָה. מִיָּד מִסְתָּפֵי הֲוָה עֵשָׂו וְנָפַק לָקֳדָמוּתֵיהּ, וּדְחִילוּ הֲוָה לֵיהּ מִיַּעֲקֹב כְּמָה דְּהֲוָה לֵיהּ לְיַעֲקֹב מֵעֵשָׂו.</p>\n<p>לְבַר נָשׁ דְּהֲוָה אָזִיל בְּאָרְחָא, עַד דְּהֲוָה אָזִיל שָׁמַע עַל חַד לִסְטִים דְּהֲוָה כָּמַן בְּאָרְחָא, פָּגַע בֵּיהּ בַר נָשׁ אָחֳרָא. אָמַר לֵיהּ מִמָּאן אַנְתְּ, אָמַר לֵיהּ מִפְּלוֹנִי לִגְיוֹן אֲנָא, אָמַר לֵיהּ סְטֵי לָךְ מִגַּבָּאי דְּכָל מַאן דְּקָרִיב בַּהֲדָאי חַד חִוְיָא אֲנָא מַיְיתֵי וְקָטִיל לֵיהּ. אֲזַל הַהוּא בַר נָשׁ לְהַהוּא לִגְיוֹן, אָמַר לֵיהּ חַד בַר נָשׁ אָתֵי וְכָל מַאן דִּי קָרִיב בַּהֲדֵיהּ נָשְׁכֵיהּ חַד חִוְיָא דְּהוּא מַיְיתֵי <Nonei></i>וּמַיֵית.</p>\n<p>שָׁמַע הַהוּא לִגְיוֹן וְדָחִיל, אָמַר יָאוֹת דְּאֵזִיל לְקֳבְלֵיהּ וְאִתְפַּיֵיס בַּהֲדֵיהּ. עַד דְּחָמָא לֵיהּ הַהוּא בַר נָשׁ, אָמַר, וַוי דְּהַשְׁתָּא יִקְטְלֵינֵיהּ הַהוּא לִגְיוֹן. שָׁארֵי סָגִיד וְכָרַע לְקֳבְלֵיהּ. אָמַר הַהוּא לִגְיוֹן, אִלְמָלֵא הֲוָה לֵיהּ בִּידֵיהּ חִוְיָא לְקָטְלָא, לָא סְגִיד כּוּלַי הַאי לְקֳבְלִי. שָׁארֵי לִגְיוֹנָאָה לְאִתְגָּאָה, אָמַר, הוֹאִיל וְכָל כָּךְ כָּרַע לְקִבְלִי לָא אֶקְטְלִינֵיהּ.</p>\n<p>כָּךָ אָמַר יַעֲקֹב עִם לָבָן גַּרְתִּי וָאֵחַר עַד עָתָּה, עֶשְׂרִין שְׁנִין אִתְאֲחָרִית עִמֵּיהּ וְאֲנָא מַיְיתֵי חִוְיָא לְקָטְלָא בְּנִי נָשָׁא. שְׁמַע עֵשָׂו, אָמַר, וַוי מַאן יָקוּם קַמֵּיהּ. דְּהַשְׁתָּא יִקְטְלִינֵיהּ יַעֲקֹב בְּפוּמֵיהּ, שָׁארֵי נָפִיק לָקֳדָמוּתֵיהּ לְאִתְפַּיְיסָא עִמֵּיהּ.</p>\n<p>כֵּיוָן דְּחָמָא לֵיהּ מַה כְּתִיב וַיִּירָא יַעֲקֹב מְאֹד וַיֵּצֶר לוֹ, כֵּיוָן דְּקָרִיב בַּהֲדֵיהּ שָׁארֵי כָּרַע וְסָגִיד לְקֳבְלֵיהּ. הֲדָא הוּא דִּכְתִיב וַיִּשְׁתַּחוּ אַרְצָה שֶׁבַע פְּעָמִים עַד גִּשְׁתּוֹ עַד אָחִיו. אָמַר עֵשָׂו אִלְמָלֵא כָּל כָּךְ הֲוָה עִמֵּיהּ, לָא סְגִיד לְקִבְלִי, שָׁארֵי לְאִתְגָּאָה.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב בְּבִלְעָם (במדבר כ״ב:כ׳) וַיָּבֹא אֱלֹהִים אֶל בִּלְעָם לַיְלָה. בְּלָבָן כְּתִיב (בראשית ל״א:כ״ד) וַיָּבֹא אֱלהִים אֶל לָבָן הָאֲרַמִּי בַּחֲלוֹם הַלַּיְלָה וַיֹּאמֶר לוֹ הִשָּׁמֶר לְךָ פֶּן תְּדַבֵּר עִם יַעֲקֹב מִטּוֹב וְגו'. פֶּן תְּדַבֵּר, פֶּן תַּעֲשֶׂה לְיַעֲקֹב רָעָה מִבָּעֵי לֵיהּ. אֶלָּא לָבָן לָא רָדַף אֲבַתְרֵיהּ דְּיַעֲקֹב בְּחֵילָא דְגוּבְרִין לַאֲגָחָא בֵּיהּ קְרָבָא. דְּהָא חֵילָא דְּיַעֲקֹב וּבְנוֹי רַב מִנֵּיהּ, אֶלָּא לְמִקְטְלֵיהּ בְּפוּמֵיהּ וּלְשֵׁיצָאָה כֹּלָּא. הֲדָא הוּא דִּכְתִיב אֲרַמִּי אוֹבֵד אָבִי. וּבְגִין כָּךְ פֶּן תְּדַבֵּר, וְלָא כְּתִיב פֶּן תַּעֲשֶׂה. וּכְתִיב יֵשׁ לְאֵל יָדִי לַעֲשׂוֹת. מִנַּיִן הֲוָה יָדַע דִּיְכֹלְתָּא הֲוָה בִּידֵיהּ. אֶלָּא כְּמָה דְאִתְּמָר אֱלֹהֵי אֲבִיכֶם אֱמֶשׁ אָמַר אֵלַי וְגו'.</p>\n<p>וְדָא הוּא סַהֲדוּתָא, דְּפָּקִּיד קוּדְשָׁא בְּרִיךְ הוּא לְאַסְהָדָא. דִּכְתִיב (דברים כ״ו:ה׳) וְעָנִיתָ וְאָמַרְתָּ לִפְנֵי יְיָ אֱלֹהֶיךָ אֲרַמִּי אוֹבֵד אָבִי וְגו'. וְעָנִיתָ, כְּמָה דְאַתְּ אָמֵר, (שמות כ׳:י״ג) לֹא תַעֲנֶה בְרֵעֲךָ. (דברים י״ט:י״ח) עָנָה בְאָחִיו.</p>\n<p>כְּתִיב בֵּיהּ בְּבִלְעָם (במדבר כ״ד:א׳) וְלא הָלַךְ כְפַעַם בְּפַעַם לִקְרַאת נְחָשִׁים, דְּהָכִי הוּא אָרְחֵיהּ דְּאִיהוּ הֲוָה מְנַחֵשׁ. בְּלָבָן כְּתִיב, (בראשית ל) נִחַשְׁתִּי, דְּאַשְׁגַּח בַּחֲרָשׁוֹי וּבִקְסָמוֹי בְּעִסְקָא דְיַעֲקֹב, וְכַד בָּעָא לְאוֹבָדָא לְיַעֲקֹב בִּנְחָשָׁא וּבַחֲרָשָׁא דִּילֵיהּ בָּעָא לְאוֹבָדֵיהּ, וְלָא שַׁבְקֵיהּ קוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>וְהַיְינוּ דְּאָמַר בִּלְעָם בַּר בְּרֵיהּ (במדבר כ״ג:כ״ג) כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל, מַאן יָכִיל לְהוֹן, דְּהָא סָבָאי בָּעָא לְאוֹבָדָא לַאֲבוּהוֹן בִּנְחָשִׁים וּבִקְסָמִים דִּילֵיהּ וְלָא סְלִיקָא בִּידוֹי. דְּלָא שַׁבְקֵיהּ לְלַטְיָא. הֲדָא הוּא דִכְתִיב כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְלֹא קֶסֶם בְּיִשְׂרָאֵל.</p>\n<p>וּבְכֻלְּהוּ עֲשָׂרָה זִינֵי חֳרָשִׁין וְקוֹסְמִין דְּקוּזְטְפֵי דְּכִתְרִין תַּתָּאִין עֲבַד לָבָן לְקֳבְלֵיהּ דְּיַעֲקֹב וְלָא יָכִיל. הֲדָא הוּא דִכְתִיב, (בראשית ל״א:מ״א) וַתַּחְלֵף אֶת מַשְׂכֻּרְתִּי עֲשֶׂרֶת מוֹנִים. דְּכֻלְּהוּ עֲבַד לָבָן לְקֳבְלֵיהּ וְלָא סְלִיקוּ בִּידוֹי לְאַבְאָשָׁא לֵיהּ, דִּכְתִיב, (בראשית ל״א:ז׳) וְהֶחלִיף אֶת מַשְׂכֻּרְתִּי עֲשֶׂרֶת מוֹנִים וְלֹא נְתָנוֹ אֱלהִים לְהָרַע עִמָּדִי. מַאי מוֹנִים, כְּתַרְגּוּם זִינִין, וּכְתִיב (ויקרא י״ז:ז׳) לַשְּׂעִירִים אֲשֶׁר הֵם זוֹנִים אַחֲרֵיהֶם. מוֹנִים, מִינִים כְּמַשְׁמָעוֹ. וַעֲשָׂרָה זִינִין אִינוּן דְּחֲרָשִׁין וְקוֹסְמִין בְּכִתְרִין תַּתָּאִין וְכֻלְּהוּ עֲבַד לְקֳבְלֵיהּ.</p>\n<p>עֲשָׂרָה זִינִין אִינוּן, דִּכְתִיב, (דברים י״ח:י׳-י״א) קוֹסֵם קְסָמִים מְעוֹנִן וּמְנַחֵשׁ וּמְכַשֵּׁף וְחוֹבֵר חָבֶר וְשׁוֹאֵל אוֹב וְיִדְעוֹנִי וְדוִֹרִשׁ אֶל הַמֵּתִים, הָא עֲשָׂרָה אִינוּן.</p>\n<p>אָמַר רִבִּי יוֹסֵי נַחַשׁ וְקֶסֶם, תְּרֵי זִינֵי אִינוּן, וּבְדַרְגָּא חַד סָלְקִין. וְכַד אֲתָא בִּלְעָם בְּקֶסֶם עֲבַד לְקִבְלֵיהוֹן דְּיִשְׂרָאֵל. וְהַיְינוּ דִכְתִיב, (במדבר כ״ב:ז׳) וּקְסָמִים בְּיָדָם. וּלְקֳבְלֵיהּ דְּיַעֲקֹב אֲתָא לָבָן בְּנַחַשׁ, הַאי וְהַאי לָא סְלִיקוּ בִּידַיְיהוּ הֲדָא הוּא דִּכְתִיב, (שם כג) כִּי לא נַחַשׁ בְּיַעֲקֹב וְלא קֶסֶם בְּיִשְׂרָאֵל. כִּי לא נַחַשׁ בְּיַעֲקֹב בְּקַדְמִיתָא בְּיוֹמוֹי דְלָבָן. וְלא קֶסֶם בְּיִשְׂרָאֵל לְבָתַר בְּיוֹמוֹי דְבִלְעָם.</p>\n<p>אָמַר בִּלְעָם לְבָלָק, תָּא חֲזֵי, מַאן יָכִיל לְהוֹן. דְּכָל קְסָמִין וַחֲרָשִׁין דִּבְכִתְרִין דִּילָן, מִקִּיזְפָא דְמַלְכוּתָא דִּלְעֵילָא (ותתא) מִתְעַטְּרָן (דהא), וְהוּא אִתְקַשַּׁר בְּהוּ, דִּכְתִיב יְיָ אֱלהָיו עִמּוֹ וּתְרוּעַת מֶלֶךְ בּוֹ.</p>\n<p>אָמַר רִבִּי יְהוּדָה חַס וְשָׁלוֹם דְהֲוָה יָדַע בִּלְעָם בִּקְדוּשָׁה דִלְעֵילָא <Nonei></i>כְּלָל. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא לָא אִתְרָעֵי בְּעַם וְלִישָׁן אָחֳרָא דְּיִשְׁתַּמֵּשׁ בִּיקָרֵיהּ, אֶלָּא בְּנוֹי קַדִּישִׁין. וְאָמַר (ויקרא י״א:מ״ד) וְהִתְקַדִּשְׁתֶּם וִהְיִיתֶם קְדוֹשִׁים, מַאן דְּאִינוּן קַדִּישִׁין יִשְׁתַּמְשׁוּן בִּקְדוּשָּׁה, יִשְׂרָאֵל אִינוּן קַדִּישִׁין דִּכְתִיב, (דברים י״ד:ב׳) כִּי עַם קָדוֹשׁ אַתָּה. אַתָּה קָדוֹשׁ וְלָא עַם אָחֳרָא.</p>\n<p>מַאן דְּאִינוּן מְסָאֲבִין, מְסָאֲבוּ אִזְדַּמַּן לוֹן לְאִסְתָּאֲבָא עֲלֵיהּ. כְּתִיב, (ויקרא י״ג:מ״ו) טָמֵא הוּא בָּדָד יֵשֵׁב מִחוּץ לַמַּחֲנֶה מוֹשָׁבוֹ. וּמְסָאֲבָא לִמְסָאֲבָא קָרֵי דִּכְתִיב, (שם) וְטָמֵא טָמֵא יִקְרָא, מַאן דְּאִיהוּ טָמֵא, לְטָמֵא יִקְרָא, כֹּלָא אָזִיל בָּתַר זִינֵיהּ.</p>\n<p>אָמַר רִבִּי יִצְחָק, יָאוֹת הוּא לְיַעֲקֹב דְּהֲוָה קַדִּישָׁא לוֹמַר דְּאִסְתָּאַב בְּלָבָן וּבַחֲרָשׁוֹי, אוֹ שְׁבָחָא הוּא דִילֵיהּ. אָמַר לֵיהּ רִבִּי יוֹסֵי, אַף עַל גַּב דְּקָאֲמַר רַבִּי יְהוּדָה, אֲנָא מְסַיֵּיעַ לָךְ. דְּהָא כְּתִיב, (בראשית כ״ז:י״ט) אָנֹכִי עֵשָׂו בְּכוֹרֶךָ. וְכִי יָאוֹת הוּא לְצַדִּיקָא כְּיַעֲקֹב לְמִחְלַף שְׁמֵיהּ בִּשְׁמָא דִּמְסָאֲבָא, אֶלָּא אָנֹכִי, פָּסְקָא טַעְמָא. וְאָמַר אָנֹכִי מַאן דְּאֲנָא, אֲבָל עֵשָׂו בְּכוֹרֶךָ וְהָא אוּקְמוּהָ.</p>\n<p>אוּף הָכָא, וַיְהִי לִי שׁוֹר וַחֲמוֹר, לוֹמַר לָא תְשַׁוֵּי לִבָּךְ וּרְעוּתָךְ לְהַהִיא בִּרְכָתָא דְּבָרִיךְ לִי אַבָּא דְּאִתְקְיַּים בִּי. הוּא בָּרִיךְ לִי הֱוִה גְבִיר לְאַחֶיךָ וְיִשְׁתַּחֲווּ לְךָ בְּנֵי אִמֶּךָ, בְּגִין כָּךְ עַבְדְּךָ יַעֲקֹב. לַאדֹנִי לְעֵשָׂו. הוּא בָּרִיךְ לִי בְּרוֹב דָּגָן וְתִירוֹשׁ. הָא לָא אִתְקְיַּים בִּי, דְלָא אוֹצַרְנָא לוֹן. אֶלָּא, וַיְהִי לִי שׁוֹר וַחֲמוֹר צֹאן וְעֶבֶד, רָעֵי עָנָא בְּחַקְלָא. הוּא בָּרִיךְ לִי, מִטַּל הַשָּׁמַיִם וּמִשְׁמַנֵּי הָאָרֶץ. הָא לָא אִתְקְיַּים בִּי, בְּגִין דְּהָא עִם לָבָן גַּרְתִּי, כְּגִיּוֹרָא. דְּלָא הֲוָה לִי בֵּיתָא חָדָא כָּל שֶׁכֵּן מִשְׁמַנֵּי הָאָרֶץ. וְכָל דָּא בְּגִין דְּלָא יִסְתַּכַּל בֵּיהּ בְּיַעֲקֹב עַל אִינוּן בִּרְכָאן וִיקַטְרֵג עִמֵּיהּ.</p>\n<p>רִבִּי אַבָּא אָמַר כְּתִיב בֵּיהּ בְּיַעֲקֹב (בראשית כ״ה:כ״ז) אִישׁ תָּם יוֹשֵׁב אֹהָלִים, גְּבַר שְׁלִים. בְּגִין דְּאִיהוּ יְתִיב בִּתְרֵין מִשְׁכָּנִין עִלָּאִין. וְאַשְׁלִים לְהַאי גִיסָא וּלְהַאי גִיסָא, וְאִיהוּ לָא אָמַר דְּאִסְתָּאַב בַּחֲרָשׁוֹי. אֲבָל עַל מַה דְּקָאֲמַר רִבִּי יְהוּדָה, בְּגִין דְּלִבּוֹי שְׁלִים עַל טִיבוּ וּקְשׁוֹט דְּעֲבִיד לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא. דְּכָל עַלְמָא יָדְעֵי עוֹבָדוֹי דְלָבָן מַאן אִינוּן, וּמַאן יָכִיל לְאִשְׁתְּזָבָא (ס\"א מניה, כל עשרין שנין דהויתי עמיה) מִקִּטְרוּגָא דִילֵיהּ דְּבָעֵי לְאוֹבָדָא לִי. (ס\"א ואנא יתיבנא ועבדנא עמיה עשרין שנין) וְקוּדְשָׁא בְּרִיךְ הוּא שֵׁזְבַנִי מִנֵּיהּ. וְכֹלָּא הֲוָה בְּגִין דְּלָא יִסְתַּכַּל בֵּיהּ עֵשָׂו דְּאִתְקַיְּימוּ בֵּיהּ אִינוּן בִּרְכָאן, וְלָא יִנְטַר לֵיהּ דְּבָבוּ. וְעַל דָּא כְּתִיב, (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי יְיָ וְגו', וּכְתִיב, (דברים י״ח:י״ג) תָּמִים תִּהְיֶה עִם יְיָ אֱלֹהֶיךָ:</p>"],[9520011343,"<p>וַיָּשׁוּבוּ הַמַּלְאָכִים אֶל יַעֲקֹב לֵאמֹר בָּאנוּ אֶל אָחִיךָ אֶל עֵשָׂו וְגַם הוֹלֵךְ לִקְרָאתְךָ וְאַרְבַּע מֵאוֹת אִישׁ עִמּוֹ. כֵּיוָן דְּאָמַר בָּאנוּ אֶל אָחִיךָ, לָא יְדַעְנָא דְּאִיהוּ עֵשָׂו, וְכִי אַחִין אָחֳרָנִין הֲווּ לְיַעֲקֹב. אֶלָּא בָּאנוּ אֶל אָחִיךָ, וְאִי תֵימָא דְּהֲדַר בִּתְשׁוּבָה וְאָזִיל בְּאֹרַח מְתַקְּנָא, לָאו הָכִי, אֶלָּא עֵשָׂו הָרָשָׁע כִּדְמְעִיקָּרָא. וְגַם הוֹלֵךְ לִקְרָאתְךָ, וְאִי תֵימָא דְּאִיהוּ בִּלְחוֹדוֹי אָזִיל. לָאו, אֶלָא אַרְבַּע מֵאוֹת אִישׁ עִמּוֹ.</p>\n<p>וְכָל כָּךְ לָמָּה, (אלא אינון) אָמְרוּ לֵיהּ, בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי תָּדִיר בִּצְלוֹתְהוֹן דְּצַדִּיקַיָא וּמִתְעַטֵּר בִּצְלוֹתְהוֹן. כִּדְאַמְרִינָן, דְּהַהוּא מַלְאָכָא דִּמְמַנָּא עַל צְלוֹתְהוֹן דְּיִשְׂרָאֵל, סַנְדַּ\"לְפוֹן שְׁמֵיהּ, נָטִיל כָּל אִינוּן צְלוֹתִין וְעָבִיד מִנַּיְיהוּ עֲטָרָה לְחֲיֵי הָעוֹלָמִים וְאוּקְמוּהָ. וְכָל שֶׁכֵּן צְלוֹתְהוֹן דְּצַדִּיקַיָּא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוּ וְאִתְעַבְדָן עֲטָרָה לְאִתְעַטְּרָא בְּאִינוּן צְלוֹתִין לְקוּדְשָׁא בְּרִיךְ הוּא. וְאִי תֵימָא מַשִּׁרְיָין קַדִּישִׁין הֲווּ אַתְיָין עִמֵּיהּ, אַמַּאי דָּחִיל. אֶלָּא צַדִּיקַיָיא לָא סַמְכִין עַל זְכוּתַיְיהוּ, אֶלָּא עַל צְלוֹתְהוֹן וּבָעוּתְהוֹן לְגַבֵּי מָארֵיהוֹן.</p>\n<p>וְתָּא חֲזֵי, דְּאָמַר רִבִּי שִׁמְעוֹן, צְלוֹתָא דְסַגִּיאִין סָלִיק קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וּמִתְעַטֵּר בְּהַהוּא צְלוֹתָא. בְּגִין דְּסַלְקָא בִּגְוָונִין סַגִּיאִין וְאִתְכְּלִילַת מִכַּמָּה סִטְרִין. וּבְגִין דְּאִתְכְּלִילַת מִכַּמָּה גְוָונִין אִתְעֲבִידַת עֲטָרָה וּמַנְחָא עַל רֵישָׁא דְצַדִּיק חַי הָעוֹלָמִים. וּצְלוֹתָא דְיָחִיד לָאו אִיהִי כְּלִילָא, וְלָאו אִיהִי אֶלָּא בְּגַוָּון חַד. וְעַל דָּא צְלוֹתָא דְיָחִיד לָאו אִיהוּ מִתְתַּקְנָא לְאִתְקַבְּלָא (אלא בצלותא) כִּצְלוֹתָא דְסַגִּיאִין. וְתָּא חֲזֵי, יַעֲקֹב כָּלִיל הֲוָה, וְעַל דָּא צְלוֹתֵיהּ תָּאִיב לָהּ קוּדְשָׁא בְּרִיךְ הוּא. מַה כְּתִיב וַיִּירָא יַעֲקֹב מְאֹד וַיֵּצֶר לוֹ.</p>\n<p>רִבִּי יְהוּדָה פָּתַח וְאָמַר (משלי כ״ח:י״ד) אַשְׁרֵי אָדָם מְפַחֵד תָּמִיד וּמַקְשֶׁה לִבּוֹ יִפּוֹל בְּרָעָה. <Nonei></i>זַכָּאִין אִינוּן יִשְׂרָאֵל דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוּ, וְיָהַב לוֹן אוֹרַיְיתָא דִקְשׁוֹט בְּגִין לְמִזְכֵּי בָהּ לְחַיֵּי עַלְמָא, דְּכָל מַאן דְּאִשְׁתָּדַּל בְּאוֹרַיְיתָא קוּדְשָׁא בְּרִיךְ הוּא מָשִׁיךְ עֲלֵיהּ חַיִּין עִלָּאִין, וְאָעִיל לֵיהּ לְחַיֵּי עַלְמָא דְאָתֵי, דִּכְתִיב, (דברים ל׳:כ׳) כִּי הִיא חַיֶּיךָ וְאֹרֶךְ יָמֶיךָ. וּכְתִיב, (שם לב) וּבַדָּבָר הַזֶּה תַּאֲרִיכוּ יָמִים. חַיִּין בְּהַאי עַלְמָא וְחַיִין בְּעַלְמָא דְאָתֵי.</p>\n<p>רִבִּי אֶלְעָזָר אָמַר כָּל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא לִשְׁמָהּ, לָאו מִיתָתֵיהּ עַל יְדָא דְיֵצֶר הָרָע, בְּגִין (גליון דהוא נחש והוא מלאכא דמותא. אלא מיתתהון בנשיקה דכתיב (שיר השירים א׳:ב׳) ישקני מנשיקות פיהו, כלומר על פי יי, והיא הנשיקה דהיא דביקותא דנפשא בעיקרא, וההיא דאשתדל באורייתא) דְּאִתְתַּקִּיף בְּאִילָנָא דְחַיֵּי וְלָא אַרְפֵּי מִנֵּיהּ, וּבְגִין כָּךְ צַדִּיקַיָא דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא לָא מִסְתָּאֲבֵי גוּפָא דִלְהוֹן (גליון אלא הוא דכי, כגון אליהו בבי קברי דאשכחוהו רבנן, ושאילו ליה ולאו כהן הוא מר, אמר לון צדיקיא לא מסאבי במיתתהון, כמה דתנינן ביום שמת רבי בטלה כהונה, כלומר דאתעסקו ביה) דְּלָא שָׁרָא עֲלַיְיהוּ רוּחַ מְסָאֲבָא.</p>\n<p>יַעֲקֹב אִילָנָא דְחַיֵּי הֲוָה, אַמַּאי דָּחִיל, דְּהָא לָא יָכוֹל לְשַׁלְטָאָה עֲלוֹי. וְעוֹד דְּהָא כְּתִיב וְהִנֵּה אָנֹכִי עִמָּךְ וְגו', אַמַּאי הֲוָה דָחִיל. וְתוּ דְּהָא כְּתִיב וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלהִים. אִי מַשִּׁרְיָין קַדִּישִׁין הֲווּ עִמֵּיהּ אַמַּאי הֲוָה דָחִיל.</p>\n<p>אֶלָּא כֹּלָּא יָאוֹת הֲוָה, וְיַעֲקֹב לָא הֲוָה בָּעֵי לְמִסְמַךְ עַל נִיסָּא דְקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּחָשִׁיב דְּלָאו אִיהוּ כְּדַאי דְּקוּדְשָׁא בְּרִיךְ הוּא יַעֲבִיד לֵיהּ נִיסָּא. מַאי טַעְמָא, בְּגִין דְּלָא פָלַח לְאֲבוֹי וּלְאִמֵּיהּ כְּדְקָא יְאוּת, וְלָא אִשְׁתַּדַּל בְּאוֹרַיְיתָא וְנָטַל תְּרֵי אֲחָיוֹת. וְאַף עַל גַּב דְּכֹלָּא אִתְּמָר, וְעִם כָּל דָא בָּעֵי לֵיהּ לְבַר נָשׁ לְמִדְחַל תָּדִיר וּלְצַלָּאָה קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא בִּצְלוֹתָא. דִּכְתִיב אַשְׁרֵי אָדָם מְפַחֵד תָּמִיד (ולמדחל תדיר קמי קודשא בריך הוא) וְהָא אוּקְמוּהָ.</p>\n<p>תָּא חֲזֵי, צְלוֹתָא דְּאֲבָהָן קָיְימוּ עָלְמָא, וְכָל בְּנֵי עָלְמָא עֲלַיְיהוּ קָיְימֵי וְסָמְכִין. לְעָלַם וּלְעָלְמֵי עָלְמִין, לָא אִתְנְשֵׁי זְכוּתָא דְּאֲבָהָן, בְּגִין דִּזְכוּתָא דְּאֲבָהָן אִיהוּ קִיּוּמָא דְעֵילָא וְתַתָּא, וְקִיּוּמָא דְיַעֲקֹב אִיהוּ קִיּוּמָא שְׁלִים יַתִּיר מִכֻּלְּהוּ. וּבְגִין כָּךְ בְּשַׁעְתָּא דְעָאקוּ לִבְנוֹי דְיַעֲקֹב, קוּדְשָׁא בְּרִיךְ הוּא אַחְמֵי קַמֵּיהּ דִּיוּקְנָא דְיַעֲקֹב וְחָיִיס עַל עַלְמָא כְּמָה דְאַתְּ אָמֵר, (ויקרא כ״ו:מ״ב) וְזָכַרְתִּי אֶת בְּרִיתִי יַעֲקוֹב. יַעֲקוֹ\"ב בְּוא\"ו, אַמַּאי בְּוא\"ו, בְּגִין דְּאִיהוּ דִיוּקְנָא דְיַעֲקֹב מַמָּשׁ.</p>\n<p>תָּא חֲזֵי, כָּל מַאן דְּחָמֵי לֵיהּ לְיַעֲקֹב כְּמַאן דְּאִסְתַּכֵּל בְּאַסְפַּקְלַרְיָא דְּנַהֲרָא, וְהָא אִתְּמָר דְּשׁוּפְרֵיהּ דְּיַעֲקֹב כְּשׁוּפְרֵיהּ דְּאָדָם קַדְמָאָה. אָמַר רִבִּי יֵיסָא, אֲנָא שְׁמַעְנָא דְּכָל מַאן דְּאִסְתַּכַּל בְּחֶלְמֵיהּ וְחָמָא לֵיהּ לְיַעֲקֹב מְקֻסְטָר בְּקוּסְפוֹי, חַיִּין אִתּוֹסְפָן לֵיהּ.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, הָא אִתְּמָר דְּדָוִד מַלְכָּא עַד לָא הֲוָה, לָא הֲווּ לֵיהּ חַיִּים כְּלַל. בַּר דְּאָדָם קַדְמָאָה יָהַב לֵיהּ שִׁבְעִין שְׁנִין מִדִּילֵיהּ, וְכָךְ הֲוָה קִיּוּמֵיהּ דְּדָוִד מַלְכָּא שִׁבְעִין שְׁנִין הֲווּ. וְקִיּוּמָא דְאָדָם קַדְמָאָה אֶלֶף שְׁנִין חֲסַר שִׁבְעִין. אִשְׁתַּכָּחוּ בְּהַנֵּי אֶלֶף שְׁנִין קַדְמָאֵי, אָדָם הָרִאשׁוֹן וְדָוִד מַלְכָּא.</p>\n<p>פָּתַח וְאָמַר (תהילים כ״א:ה׳) חַיִּים שָׁאַל מִמְךָ נָתַתָּה לוֹ אֹרֶךְ יָמִים עוֹלָם וָעֶד. חַיִּים שָׁאַל מִמְךָ, דָּא דָּוִד מַלְכָּא. דְהָא כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא גִּנְתָא דְעֵדֶן אַטִּיל בֵּיהּ נִשְׁמָתָא דְדָוִד מַלְכָּא, וְאִסְתַּכַּל בֵּיהּ וְחָמֵי דְּלֵית לֵיהּ חַיִּים מִדִּילֵיהּ כְּלוּם. וְקָיְימָא קַמֵּיהּ כָּל יוֹמָא. כֵּיוָן דְּבָרָא אָדָם הָרִאשׁוֹן אָמַר הָא וַדַּאי קִיּוּמֵיהּ, וּמֵאָדָם קַדְמָאָה הֲווּ שִׁבְעִין שְׁנִין דְּאִתְקְיַּים דָּוִד מַלְכָּא בְּעַלְמָא.</p>\n<p>תוּ אֲבָהָן שָׁבְקוּ לֵיהּ מֵחַיֵּיהוֹן כָּל חַד וְחַד, אַבְרָהָם שָׁבַק לֵיהּ, וְכֵן יַעֲקֹב וְיוֹסֵף. יִצְחָק לָא שָׁבַק לֵיהּ כְּלוּם, בְּגִין דְּדָוִד מַלְכָּא מִסִּטְרֵיהּ קָא אֲתָא.</p>\n<p>וַדַּאי אַבְרָהָם שָׁבַק לֵיהּ חָמֵשׁ שְׁנִין, דְּהֲוָה לֵיהּ לְאִתְקַיְּימָא מֵאָה וּתְמָנִין שְׁנִין, וְאִתְקְיַּים מֵאָה וְשִׁבְעִין וְחָמֵשׁ שְׁנִין, חֲסֵרִין חָמֵשׁ. יַעֲקֹב הֲוָה לֵיהּ לְאִתְקָיְימָא בְּעַלְמָא כְּיוֹמֵי דְאַבְרָהָם, וְלָא אִתְקְיַּים <Nonei></i>אֶלָּא מֵאָה וְאַרְבָּעִין וְשֶׁבַע שְׁנִין, חֲסֵרִים תְּמַנְיָא וְעֶשְׂרִין. אִשְׁתַּכָּחוּ דְּאַבְרָהָם וְיַעֲקֹב שְׁבָקוּ לֵיהּ מֵחַיֵּיהוֹן תְּלָתִין וּתְלַת שְׁנִין. יוֹסֵף דְּאִתְקְיַּים מְאָה וְעֶשֶׂר שְׁנִין, הֲוָה לֵיהּ לְאִתְקַיָּימָא מְאָה וְאַרְבָּעִין וְשֶׁבַע שְׁנִין כְּיוֹמֵי דְיַעֲקֹב, וְחָסֵר מִנְּהוֹן תְּלָתִין וְשֶׁבַע שְׁנִין. הָא שִׁבְעִין שְׁנִין דִּשְׁבָקוּ לֵיהּ לְדָוִד מַלְכָּא לְאִתְקָיְימָא בְּהוֹן, וּבְהוּ אִתְקַיַים דָּוִד בְּכָל אִינוּן שְׁנִין דִּשְׁבָקוּ לֵיהּ אֲבָהָן.</p>\n<p>וְאִי תֵימָא יִצְחָק אַמַּאי לָא שָׁבַק לֵיהּ כְּלוּם כְּהַנֵּי, בְּגִין דְּאִיהוּ חשֶׁךְ וְדָוִד מִסִּטְרָא דְחשֶׁךְ קָא אֲתָא, וּמַאן דְּאִיהוּ בַּחשֶׁךְ לֵית לֵיהּ נְהוֹרָא כְּלַל וְלֵית לֵיהּ חַיִּים. וּבְגִין כָּךְ לָא הֲווּ לְדָוִד חַיִּים כְּלַל. אֲבָל אִלֵּין דְּהֲווּ לְהוֹן נְהוֹרָא, נְהִירוּ לֵיהּ לְדָוִד מַלְכָּא, וּמִנַּיְיהוּ אִצְטְרִיךְ לְאַנְהָרָא וּלְמֶהוֵי לֵיהּ חַיִּים, דְּהָא מִסִּטְרָא דְחשֶׁךְ לֵית לֵיהּ חַיִּים כְּלַל, וְעַל דָּא לָא אֲתָא יִצְחָק בְּחוּשְׁבְּנָא.</p>\n<p>וְאִי תֵימָא יוֹסֵף אַמַּאי יַתִּיר מִכֻּלְּהוּ. אֶלָּא וַדַּאי יוֹסֵף בִּלְחוֹדוֹי, כְּכֻלְּהוּ בְּגִין דְּאִקְרֵי צַדִּיק, וְדָא הוּא דְאַנְהִיר לְסִיהֲרָא יַתִּיר מִכֻּלְּהוּ. וּבְגִין כָּךְ הַאי שָׁבַק לֵיהּ לְדָוִד מַלְכָּא יַתִיר מִכֻּלְּהוּ חַיִּין, דִּכְתִיב, (בראשית א׳:י״ז) וַיִּתֵּן אֹתָם אֱלהִים בִּרְקִיעַ הַשָּׁמַיִם לְהָאִיר עַל הָאָרֶץ.</p>\n<p>תָּא חֲזֵי יַעֲקֹב צְלוֹתֵיהּ אָגִין לֵיהּ מֵעֵשָׂו, בְּגִין דְּבָעָא לְסַלְקָא זְכוּתֵיהּ לִבְנוֹי אֲבַתְרֵיהּ וְלָא לְאֲפָקָא לֵיהּ הַשְׁתָּא לְגַבֵּיהּ דְּעֵשָׂו. וְעַל דָּא צַלֵי צְלוֹתֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, וְלָא אִסְתְּמִיךְ עַל זְכוּתֵיהּ, לְשֵׁיזָבָא לֵיהּ בְּגִינִיהּ:</p>\n<p>וַיֹּאמֶר אִם יָבֹא עֵשָׂו אֶל הַמַּחֲנְה הָאַחַת וְהִכָּהוּ וְהָיָה הַמַּחֲנְה הַנִּשְׁאָר לִפְלֵיטָה. תָּא חֲזֵי, מַה כְּתִיב וַיַּחַץ אֶת הָעָם אֲשֶׁר אִתּוֹ וְאֶת הַצֹּאן וְאֶת הַבָּקָר וְהַגְּמַלִּים לִשְׁנֵי מַחֲנוֹת. אַמַּאי לִשְׁנֵי מַחֲנוֹת. בְּגִין דְּאָמַר אִם יָבֹא עֵשָׂו אֶל הַמַּחֲנְה הָאַחַת וְהִכָּהוּ וְהָיָה הַמַּחֲנֶה הַנִּשְׁאָר לִפְלֵיטָה.</p>\n<p>תָּא חֲזֵי, שְׁכִינְתָּא לָא עֲדִיאַת מֵאֹהֶל לֵאָה וּמֵאֹהֶל רָחֵל. אָמַר יַעֲקֹב יָדַעְנָא דְּהָא נְטִירוּ לוֹן לְאִלֵּין מִן קוּדְשָׁא בְּרִיךְ הוּא. מָה עֲבַד וַיָּשֶׂם אֶת הַשְּׁפָחוֹת וְאֶת יַלְדֵיהֶן רִאשׁוֹנָה, אָמַר אִם יַקְטִיל עֵשָׂו, לְאִלֵּין יַקְטֵיל. אֲבָל אִלֵּין לָא מִסְתָּפִינָא מִנַּיְיהוּ, בְּגִין דִּשְׁכִינְתָּא עִמְּהוֹן. וְעַל דָּא וְהָיָה הַמַּחֲנֶה הַנִּשְׁאָר לִפְלֵיטָה. כֵּיוָן דְּעָבִיד הַאי אַתְקִין צְלוֹתֵיהּ עֲלַיְיהוּ, מָה כְּתִיב וַיֹּאמֶר יַעֲקֹב אֱלהֵי אָבִי אַבְרָהָם וִאלֹהֵי אָבִי יִצְחָק יְיָ הָאוֹמֵר אֵלַי שׁוּב לְאַרְצְךָ וּלְמוֹלַדְתְּךָ וְאֵטִיבָה עִמָּךְ.</p>\n<p>רִבִּי יוֹסֵי פָּתַח וְאָמַר (תהילים ק״ב:א׳) תְּפִלָּה לֶעָנִי כִי יַעֲטֹף וְלִפְנִי יְיָ יִשְׁפֹּךְ שִׂיחוֹ. הַאי קְרָא אוּקְמוּהָ בְּכַמָּה אֲתַר. אֶלָּא דָּוִד מַלְכָּא אָמַר דָּא כַּד אִסְתַּכַּל וְחָמָא בְּמִלֵּי דְמִסְכְּנָא, וְאִסְתַּכַּל בֵּיהּ כַּד הֲוָה אָזִיל וְעָרַק מִקַּמֵּי חָמוֹי אָמַר דָּא. תְּפִלָּה לֶעָנִי, דָּא הוּא צְלוֹתָא דְּבָעֵי מִסְכְּנָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְדָא צְלוֹתָא דְּאַקְדִימַת לְכָל צְלוֹתְהוֹן דְּעַלְמָא.</p>\n<p>כְּתִיב הָכָא תְּפִלָּה לֶעָנִי וּכְתִיב הָתָם (תהילים צ׳:א׳) תְּפִלָּה לְמשֶׁה אִישׁ הָאֱלֹהִים, מַה בֵּין הַאי לְהַאי. אֶלָּא דָּא תְּפִלָּה שֶׁל יַד וְדָא תְּפִלָּה שֶׁל רֹאשׁ, וְלֵית לְאַפְרָשָׁא בֵּין הַאי תְּפִלָּה לְעָנִי וּבֵין תְּפִלָּה לְמשֶׁה אִישׁ הָאֱלֹהִים, וְתַרְוַויְיהוּ שְׁקִילִין כְּחַד.</p>\n<p>וְעַל דָּא צְלוֹתָא דְעָנִי אַקְדִימַת קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא מִכָּל צְלוֹתִין דְּעַלְמָא, בְּגִין דִּכְתִיב, (תהילים כ״ב:כ״ה) כִּי לא בָזָה וְלֹא שִׁקַּץ עֱנוּת עָנִי וְגו'. תָּא חֲזֵי, תְּפִלָּה לְעָנִי, דָּא תְּפִלָּה שֶׁל יַד. דְּעָנִי אִתְדָּבַּק בְּמִסְכְּנוּתֵיהּ, כְּמַאן דְּלֵית לֵיהּ מִגַּרְמֵיהּ כְּלוּם.</p>\n<p>דָּבָר אַחֵר תְּפִלָּה דָּא משֶׁה. לְעָנִי דָּא דָוִד. כִּי יַעֲטֹף, כַּד אִתְכַּסְּיָא סִיהֲרָא וְאִתְכַּסֵּי שִׁמְשָׁא מִינָהּ. וְלִפְנֵי יְיָ יִשְׁפֹּךְ שִׂיחוֹ, בְּגִין לְאִתְחַבְּרָא בַּהֲדֵי שִׁמְשָׁא.</p>\n<p>תָּא חֲזֵי, צְלוֹתָא דְכָל בְּנֵי נָשָׁא צְלוֹתָא. וּצְלוֹתָא דְמִסְכְּנָא אִיהִי צְלוֹתָא דְקָיְימָא קַמֵּיהּ דְקוּדְשָׁא בְּרִיךְ הוּא וְתָבַר תַּרְעִין וּפִתְחִין וְעָאלַת לְאִתְקַבָּלָא קַמֵּיהּ הֲדָא הוּא דִכְתִיב, (שמות כ״ב:כ״ו) וְהָיָה כִי יִצְעַק אֵלַי וְשָׁמַעְתִּי כִּי חַנּוּן אָנִי, וּכְתִיב שָׁמֹעַ אֶשְׁמַע צַעֲקָתוֹ. וְלִפְנֵי יְיָ יִשְׁפֹּךְ שִׂיחוֹ, כְּמַאן דְּמִתְרַעֵם עַל דִּינוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר צְלוֹתְהוֹן דְּצַדִּיקַיָיא חֶדְוָותָא לִכְנְסֶת יִשְׂרָאֵל <Nonei></i>לְאִתְעַטָּרָא קַמֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, בְגִין כָּךְ חֲבִיבָא הוּא יַתִּיר קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא. וּבְגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא תָּאִיב לִצְלוֹתְהוֹן דְּצַדִּיקַיָּיא בְּשַׁעְתָּא דְּאִצְטְרִיךְ לוֹן, בְּגִין דְּיָדְעֵי לְרַצּוּיֵי לְמָארֵיהוֹן.</p>\n<p>מַה כְּתִיב בֵּיהּ בְּיַעֲקֹב אֱלֹהֵי אָבִי אַבְרָהָם וֵאלֹהֵי אָבִי יִצְחָק יְיָ הָאוֹמֵר אֵלַי שׁוּב וְגו', אִעֲטַר וְאִקְשַׁר קִשּׁוּרָא בְּקִשּׁוּרָא חַד כְּדְקָא חָזֵי. אֱלֹהֵי אָבִי אַבְרָהָם לִימִינָא, וִאלהֵי אָבִי יִצְחָק לִשְׂמָאלָא. הָאוֹמֵר אֵלַי, הָכָא תָּלֵי מִלָּה לְאִתְעַטְּרָא לְאַתְרֵיהּ בֵּינַיְיהוּ. שׁוּב לְאַרְצְךָ וּלְמוֹלַדְתְּךָ וְאֵיטִיבָה עִמָּךְ:</p>\n<p>קָטֹנְתִּי מִכֹּל הַחֲסָדִים, אַמַּאי הֲוָה אִצְטְרִיךְ הַאי עִם הַאי. אֶלָּא אָמַר יַעֲקֹב אַתְּ אַבְטַחְתְּ לִי לְאוֹטָבָא עִמִּי, וְאֲנָא יְדַעְנָא דְּכָל עוֹבָדָךְ כֻּלְּהוּ עַל תְּנַאי. הָא אֲנָא לֵית בִּי זְכוּתָא דְּהָא קָטֹנְתִּי מִכֹּל הַחֲסָדִים וּמִכָּל הָאֱמֶת אֲשֶׁר עָשִׂיתָ אֶת עַבְדֶּךָ, וְכָל מַה דַּעֲבָדַת לִי עַד יוֹמָא לָאו בְּגִין זְכוּתָאי הֲוָה אֶלָּא בְּגִינָךְ הוּא דַּעֲבָדַת לִי, וְהַהוּא טִיבוּ וּקְשׁוֹט בְּגִינָךְ הֲוָה. דְּהָא כַּד עָבַרְנָא בְּקַדְמִיתָא דְּהֲוֵינָא אָזִיל מִקַּמֵּי דְעֵשָׂו, יְחִידָאי עֲבַרְנָא לֵיהּ לְהַהוּא נַהֲרָא, וְאַנְתְּ עָבְדִית עִמִּי טִיבוּ וּקְשׁוֹט. וְהָא אֲנָא הַשְׁתָּא מַעֲבַר לֵיהּ בִּתְרֵי מַשִּׁירְיָין, אִינוּן תְּרֵין מַשִּׁירְיָין דְּפָלִיג.</p>\n<p>עַד הָכָא סִדּוּרָא דְּשִׁבְחָא דְמָארֵיהּ, מִכָּאן וּלְהָלְאָה בָּעָא מַה דְּאִצְטְרִיךְ לֵיהּ. לְאַחֲזָאָה לְכָל בְּנִי עַלְמָא, דְּאִצְטְרִיךְ לֵיהּ לְבַר נָשׁ לְסַדְּרָא שְׁבָחָא דְמָארֵיהּ בְּקַדְמִיתָא, וּלְבָתַר יִבָּעֵי בָּעוּתֵיהּ. דְּהָכִי עֲבַד יַעֲקֹב, בְּקַדְמִיתָא סִדֵּר שְׁבָחָא דְמָרֵיהּ, וּלְבָתַר דְּסִדֵּר שְׁבָחָא אָמַר בָּעוּתֵיהּ דְּאִצְטְרִיךְ לֵיהּ.</p>\n<p>הֲדָא הוּא דִכְתִיב הַצִּילֵנִי נָא מִיָּד אָחִי מִיַּד עֵשָׂו כִּי יָרֵא אָנֹכִי אֹתוֹ פֶּן יָבֹא וְהִכַּנִּי אֵם עַל בָּנִים. מִכָּאן, מַאן דְּצַלֵּי צְלוֹתֵיהּ דְּבָעֵי לְפָרְשָׁא מִלּוֹי כְּדְקָא יְאוּת. הַצִּילֵנִי נָא, וְאִי תֵימָא דְהָא שֵׁזַבְתְּ לִי מִלָּבָן. מִיַּד אָחִי. וְאִי תֵימָא קְרִיבִין אוֹחֲרָנִין סְתָם, אַחִין אִקְרוּן. מִיַּד עֵשָׂו. מַאי טַעֲמָא, בְּגִין לְפָרְשָׁא מִלָּה כְּדְקָא יְאוּת. וְאִי תֵימָא אֲנָא אַמַּאי אִצְטְרִיךְ, כִּי יָרֵא אָנֹכִי אֹתוֹ פֶּן יָבֹא וְהִכַּנִי. בְּגִין לְאִשְׁתְּמוֹדְעָא מִלָּה לְעֵילָא וּלְפָרְשָׁא לָהּ כְּדְקָא יְאוּת, וְלָא יַסְתִּים מִלָּה:</p>\n<p>וְאַתָּה אָמַרְתָּ הֵיטֵב אֵיטִיב עִמָּךְ וְגו'. וְאַתָּה אָמַרְתָּ הֵיטֵב אֵיטִיב, מַאי וְאַתָּה. כְּמָה דְאַתְּ אָמֵר (נחמיה ט׳:ו׳) וְאַתָּה מְחַיֶּה אֶת כֻּלָּם, אוּף הָכָא וְאַתָּה אָמַרְתָּ.</p>\n<p>תָּא חֲזֵי, דָּוִד מַלְכָּא אָמַר (תהילים י״ט:ט״ו) יִהְיוּ לְרָצוֹן אִמְרֵי פִי, אִלֵּין מִלִּין דְּאִתְפָּרְשָׁן. וְהֶגְיוֹן לִבִּי, אִלֵּין מִלִּין דִּסְתִימָן דְּלָא יָכִיל בַּר נָשׁ לְפָרְשָׁא לוֹן בְּפוּמֵיהּ, דָּא הוּא הֶגְיוֹן דְּאִיהוּ בְּלִבָּא דְּלָא יָכִיל לְאִתְפָּרְשָׁא.</p>\n<p>וְעַל דָּא אִצְטְרִיךְ מִלָּה לְאִתְפָּרְשָׁא בְּפוּמָא, וּמִלָּה דְתַלְיָא בְּלִבָּא, וְכֹלָּא רָזָא אִיהוּ. חַד לָקֳבֵל דַּרְגָּא תַּתָּאָה, וְחַד לָקֳבֵל דַּרְגָּא עִלָּאָה. מִלָּה דְאִתְפָּרְשָׁא לָקֳבֵל דַּרְגָּא תַּתָּאָה דְּאִצְטְרִיךְ לְאִתְפָּרְשָׁא. הַהוּא דְתַלְיָא בְּלִבָּא אִיהוּ לָקֳבֵל דַּרְגָּא פְּנִימָאָה יַתִּיר, וְכֹלָּא כְּחֲדָא אִיהוּ. וְעַל דָּא אָמַר יִהְיוּ לְרָצוֹן אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ וְגו'.</p>\n<p>כְּגַוְונָא דָא אָמַר יַעֲקֹב, בְּקַדְמִיתָא פָּרִישׁ מִלָּה כְּדְקָא יְאוּת, וּלְבָתַר סָתִים מִלָּה דְּאִיהִי תַּלְיָא בְּהֶגְיוֹנָא דְלִבָּא דְּלָא אִצְטְרִיךְ לְפָרְשָׁא. דִּכְתִיב, (בראשית ל״ב:י״ג) וְשַׂמְתִּי אֶת זַרְעֲךָ כְּחוֹל הַיָּם אֲשֶׁר לא יִסָּפֵר מֵרֹב. הָכָא אִיהוּ מִלָּה דְּתַלְיָא בְּלִבָּא דְּלָא אִצְטְרִיךְ לְפָרְשָׁא. וְכֵן אִצְטְרִיךְ כִּדְקָאֲמָרָן, בְּגִין לְיַחֲדָא יִחוּדָא שְׁלִים כְּדְקָא יְאוּת. זַכָּאִין אִינוּן צַדִּיקַיָא דְּיָדְעֵי לְסַדְּרָא שְׁבָחָא דְמָארֵיהוֹן כְּדְקָא יְאוּת וּלְמִבְעֵי בָּעוּתְהוֹן, וּבְגִין כָּךְ כְּתִיב (ישעיהו מ״ט:ג׳) וַיֹּאמֶר לִי עַבְדִּי אָתָּה יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאָר. (ס\"א כתיב גם את השני גם את השלישי וגו', השלש פעמים גם, רמז (גליון, ג\"ם ראשי תיבות גואל משרז גואל מרדכי גואל משיח) לשלש גאולות על ידי שלשה צדיקים משה מרדכי משיח שעתיד לגאלנו בקרוב):</p>"],[9520011344,"<p>וַיִּוָּתֵר יַעֲקֹב לְבַדּוֹ וְגו'. רִבִּי חִיָיא פָּתַח וְאָמַר, (תהילים צ״א:י׳) לֹא תְאֻנְּה אֵלֶיךָ רָעָה וְנֶגַע לֹא יִקְרַב בְּאָהֳלֶךָ. תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא עֲבַד בְּכָל יוֹמָא וְיוֹמָא <Nonei></i>עֲבִידְתֵּיהּ דְּאִתְחֲזֵי לֵיהּ וְהָא אוּקְמוּהָ. וְאִתְּמָר, (ד\"א ל\"ג ואי תימא) בְּיוֹמָא רְבִיעָאָה עֲבַד נְהוֹרִין. וּכְדֵין אִתְבְּרֵי סִיהֲרָא חָסֵר, נְהוֹרָא דְּאַזְעִירַת גַּרְמָהּ, וּבְגִין דְּאִיהִי מְאֹרֹת חָסֵר וא\"ו, אִתְיְהִיב דּוּכְתָּא לְשַׁלְּטָאָה כָּל רוּחִין וְשֵׁדִין וְעִלְעוּלִין וּמַזִּיקִין וְכָל רוּחֵי מְסָאֲבֵי.</p>\n<p>כֻּלְּהוּ סָלְקִין וְשָׁאטִין בְּעַלְמָא לְאַסְטָאָה, וְאִתְמַנּוּן בְּדוּכְתֵּי דְּאִתְחֲרִיבוּ, וּבְחַקְלִין תַּקִּיפִין וּבְמַדְבְּרִין חֲרִיבִין. וְכֻלְּהוּ מִסִּטְרֵי רוּחַ מְסָאֲבָא. וְהָא אִתְּמָר דְּהָא רוּחַ מְסָאֲבָא דְאַתְיָא מִנָּחָשׁ עֲקִימָאָה אִיהוּ רוּחַ מְסָאֲבָא מַמָּשׁ. וְאִיהוּ אִתְמַנָּא בְּעַלְמָא לְאַסְטָאָה בַּר נָשׁ לְגַבֵּיהּ, וְעַל דָּא יֵצֶר הָרָע שַׁלִּיט בְּעַלְמָא.</p>\n<p>וְאִיהוּ אִתְמַנֵּי לְגַבַּיְיהוּ דִבְנִי נָשָׁא וְאִשְׁתַּכַּח עִמְּהוֹן. וּבַעֲקִימוּ וּבְתַסְקוּפִין אָתֵי לְגַבַּיְיהוּ לְאַסְטָאָה לוֹן מֵאָרְחוֹי קוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְאַסְטֵי לְאָדָם קַדְמָאָה וְגָרִים מוֹתָא לְכָל עַלְמָא, הָכִי נָמֵי אַסְטֵי לְהוּ לִבְנֵי נָשָׁא וְגָרִים לוֹן לְאִסְתָּאֲבָא.</p>\n<p>וּמַאן דְּאָתֵי לְאִסְתָּאֲבָא אִיהוּ מָשִׁיךְ עֲלֵיהּ הַהוּא רוּחַ מְסָאֲבָא וְאִתְדַּבֵּיק בַּהֲדֵיהּ, וְכַמָּה אִינוּן דִּזְמִינִין לְסָאֲבָא לֵיהּ וּמְסָאֲבִין לֵיהּ, וְאִיהוּ מְסָאָב, וְסָאֳבִין לֵיהּ בְּהַאי עַלְמָא וּבְהַהוּא עַלְמָא וְהָא אִתְּמָר.</p>\n<p>וּבְשַׁעֲתָא דְּאָתֵי בַּר נָשׁ לְאִתְדַּכָאָה, הַהוּא רוּחַ מְסָאֲבָא אִתְכַּפְיָיא קַמֵּיהּ וְלָא יָכִיל לְשַׁלְטָאָה עֲלוֹי, וּכְדֵין כְּתִיב, (תהילים צ״א:י׳) לא תְאֻנֶּה אֵלֶיךָ רָעָה וְנֶגַע לא יִקְרַב בְּאָהֳלֶךָ. אָמַר (ס\"א כדאמר) רַבִּי יוֹסֵי לא תְאֻנֶּה אֵלֶיךָ רָעָה, דָּא לִילִית, וְנְגַע לֹא יִקְרַב בְאָהֳלֶךָ, אִלֵּין שְׁאָר מַזִּיקִין, וְהָא אוּקְמוּהָ וְאִתְּמָר.</p>\n<p>רִבִּי אֶלְעָזָר אָמַר הָא אֲמָרָן דְּלָא יִפּוּק בַּר נָשׁ יְחִידָאָה בְּלֵילְיָא, וְכָל שֶׁכֵּן בְּזִמְנָא דְסִיהֲרָא אִתְבְּרִיאַת וְהֲוָה (והיא) חֲסֵרָה, וְאוּקְמוּהָ. דְּהָא כְּדֵין רוּחָא מְסָאֲבָא שָׁלְטָא, וְדָא הוּא רוּחַ רָעָה, מַאן רָעָה, דָּא חִוְיָא בִישָׁא. וְנְגַע, דָּא הוּא מַאן דְּרָכִיב עַל חִוְיָא. רָעָה וְנֶגַע כְּחֲדָא אִינוּן.</p>\n<p>וְאַף עַל גַּב דְּתָנִינָן, דְּנְגַע, אִלֵּין נִגְעֵי בְּנֵי אָדָם דְּנַפְקוּ מֵאָדָם. דְּהָא כָּל אִינוּן שְׁנִין דְּלָא קָרִיב אָדָם עִם אִתְּתֵיהּ, רוּחֵי מְסָאֲבֵי הֲווּ קָא אַתְיָין וּמִתְחַמְמָן מִנֵּיהּ וְאוֹלִידָן מִנֵּיהּ וְהַנֵּי אִקְרוּן נִגְעֵי בְּנֵי אָדָם.</p>\n<p>וְהָא אִתְּמָר, דְּכַד בַּר נָשׁ בְּחֶלְמֵיהּ וְלָא שַׁלִּיט בְּגוּפֵיהּ וְגוּפָא אִשְׁתַּכַּךְ, רוּחַ מְסָאֲבָא אַתְיָיא וְשַׁרְיָא עֲלֵיהּ. וְאִית זִמְנִין דְּרוּחֵי נוּקְבִין מְסָאֲבִין אַתְיָין וְקָרְבָן בַּהֲדֵיהּ, וּמָשְׁכִין לֵיהּ בַּהֲדַיְיהוּ וּמִתְחַמְמָן מִנֵּיהּ, וְאוֹלִידוּ לְבָתַר רוּחִין וּמַזִּיקִין (נגעי בני אדם נ\"א כגוונא בני נשא). וּלְזִמְנִין אִתְחַזְיָין כְּחֵיזוּ בְּנֵי נָשָׁא בַּר דְּלֵית לוֹן שַׂעֲרֵי בְּרֵישָׁא.</p>\n<p>וּבְכֹלָּא אִית לֵיהּ לְבַר נָשׁ לְאִסְתַּמְּרָא מִקַּמַּיְיהוּ, בְּגִין דִּיהַךְ בְּאָרְחֵי דְאוֹרַיְיתָא וְלָא יִסְתָּאַב בַּהֲדַיְיהוּ. דְּהָא לֵית לָךְ מַאן דְּנָאִים בְּלֵילְיָא בְּעַרְסֵיהּ, דְּלָא טָעִים טַעְמָא דְמוֹתָא וְנָפְקַת נִשְׁמָתֵיהּ מִנֵּיהּ. וְכֵיוָן דְּאִשְׁתָּאַר גּוּפָא בְּלָא נִשְׁמָתָא קַדִּישָׁא, רוּחַ מְסָאֲבָא זַמִּין וְשַׁרְיָא עֲלֵיהּ וְאִסְתָּאַב. וְהָא אוֹקִימְנָא מִלָּה, דְּלֵית לֵיהּ לְבַר נָשׁ לְאַעֲבָרָא יְדוֹי עַל עֵינוֹי בְּצַפְרָא. בְּגִין דְּהָא רוּחָא מְסָאֲבָא שַׁרְיָא עֲלַיְיהוּ וְכוּ' וְהָא אִתְּמָר.</p>\n<p>תָּא חֲזֵי, דְּהָא יַעֲקֹב אַף עַל גַּב דְּאִתְרָחִים קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּאִשְׁתָּאַר בִּלְחוֹדוֹי, רוּחָא אָחֳרָא הֲוָה זַמִין לְאִזְדַּוְּוגָא בַּהֲדֵיהּ.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, תָּא חֲזֵי, מַה כְּתִיב בֵּיהּ בְּהַהוּא רָשָׁע דְּבִלְעָם, וַיֵּלֶךְ שֶׁפִי, מַהוּ שֶׁפִי, יְחִידָאי. כְּמָה דְאַתְּ אָמֵר שְׁפִיפוֹן עֲלֵי אֹרַח, כְּהַאי חִוְיָא דְּאָזִיל יְחִידָאי וְכָמִין עֲלֵי אָרְחִין וּשְׁבִילִין. הָכִי נָמֵי בִּלְעָם הֲוָה אָזִיל יְחִידָאי. מַאי טַעְמָא בְּגִין לְאַמְשָׁכָא עֲלֵיהּ רוּחָא מְסָאֲבָא. דְּכָל מַאן דְּאָזִיל יְחִידָאי בִּזְמַנִּין יְדִיעָן, אֲפִילּוּ בְּמָתָא, בְּאַתְרִין יְדִיעָן. מָשִׁיךְ עֲלֵיהּ רוּחָא מְסָאֲבָא.</p>\n<p>בְגִין כָּךְ, בְּכָל זִמְנָא לָא יְהַךְ בַּר נָשׁ יְחִידָאי בְּאָרְחָא בְמָתָא אֶלָּא בְּאֲתַר דִּבְנֵי נָשָׁא אָזְלִין וְתָבִין וּמִשְׁתַּכְּחִין תַּמָּן, וְעַל דָּא לָא יְהַךְ בַּר נָשׁ יְחִידָאי בְּלֵילְיָא הוֹאִיל וּבְנֵי נָשָׁא לָא מִשְׁתַּכְּחֵי, וְהַיְינוּ טַעְמָא דְּלָא תָלִין נִבְלָתוֹ. <Nonei></i>דְּלָא לְקַיְימָא גּוּפָא מִיתָא בְּלָא רוּחָא עַל אַרְעָא בְּלֵילְיָא. בְּגִין כָּךְ הַהוּא רָשָׁע דְּבִלְעָם הֲוָה אָזִיל יְחִידָאי כְּהַאי נָחָשׁ כְּמָה דְאוּקְמוּהָ.</p>"],[9520011345,"<p>וַיֵּאָבֵק אִישׁ עִמּוֹ, מַאי וַיֵּאָבֵק. (גליון דאמר רבי יהושע בן לוי, מלמד דסליקו אבק ברגליהון עד כורסי יקרא. כתיב הכא בהאבקו עמו, וכתיב (נחום א׳:ג׳) אבק רגליו, וההוא מלאך שרו של עשו היה, ואיהו סמאל. בגין כך, דינו הוא שיעלה אבק דרגליו עד כסא הכבוד, שהוא מקום המשפט). רִבִּי שִׁמְעוֹן אָמַר מִן אָבָק. אָבָק טָפֵל לֶעָפָר, מַה בֵּין עָפָר לְאָבָק. דָּא אָבָק דְּאִשְׁתָּאַר מִן נוּרָא וְלָא עֲבַד אִיבִּין (בעלמא) לְעָלְמִין. עָפָר דְכָל אִיבִּין נָפְקֵי מִנֵּיהּ וְאִיהוּ כְּלָלָא בְּעֵילָא וְתַתָּא.</p>\n<p>אָמַר רִבִּי יְהוּדָה אִי הָכִי מַאי (שמואל א ב׳:ח׳) מֵקִים מֵעָפָר דָּל. אָמַר לֵיהּ כְּמַשְׁמָעוֹ, אֲבָל בְּהַאי גַוְונָא מֵקִים מֵעָפָר דָּל, בְּגִין דְּלֵית לֵיהּ מִגַּרְמֵיהּ כְּלוּם, וּמֵהַהוּא עַפְרָא נָפַק דַּל דְּלֵית לֵיהּ כְּלוּם, וּמֵהַהוּא עָפָר כָּל אִיבִּין וְכָל טִיבוּ דְעַלְמָא נָפְקֵי מִנֵּיהּ. וּבֵיהּ אִתְעֲבִידוּ כָּל עוֹבָדִין דְּעַלְמָא כְּמָה דִכְתִיב, (קהלת ג׳:כ׳) הַכֹּל הָיָה מִן הֶעָפָר וְהַכֹּל שָׁב אֶל הֶעָפָר. וְתָנִינָן הַכֹּל הָיָה מִן הֶעָפָר וְאֲפִילּוּ גַּלְגַּל חַמָּה. אֲבָל אָבָק לָא עָבִיד פֵּירִין וְאִיבִּין (לעלמא) לְעָלְמִין, וּבְגִין כָּךְ וַיֵּאָבֵק אִישׁ, דְּאַתְיָא בְּהַהוּא אָבָק וּרְכִיב עֲלֵיהּ, בְּגִין לְקַטְרְגָא לֵיהּ לְיַעֲקֹב.</p>\n<p>עַד עֲלוֹת הַשָּׁחַר, דְּאִתְעֲבַר שׁוּלְטָנוּתֵיהּ וְאִתְחַלַּף. וְכָךְ הוּא לְזִמְנָא דְאָתֵי, בְּגִין דְּגָלוּתָא הַשְׁתָּא כְּלֵילְיָא דַמְיָא, וְאִיהוּ לֵילְיָא. וְשָׁלְטָא הַהוּא אָבָק עַל יִשְׂרָאֵל וְאִינוּן שְׁכִיבֵי לְעַפְרָא (אוחרא), עַד דְּיִסְתַּלַּק נְהוֹרָא וְיִתְנְהַר יְמָמָא. וּכְדֵין יִשְׁלְטוּן יִשְׂרָאֵל וּלְהוֹן יִתְיָהִיב מַלְכוּתָא דְּאִינוּן קַדִּישֵׁי עֶלְיוֹנִין. כְּמָה דְאַתְּ אָמֵר, (דניאל ז׳:כ״ז) וּמַלְכוּתָא וְשָׁלְטָנָא וּרְבוּתָא דִי מַלְכְוָת תְּחוֹת כָּל שְׁמַיָא יְהִיבַת לְעַם קַדִּישֵׁי עֶלְיוֹנִין מַלְכוּתֵהּ מַלְכוּת עָלַם וְכֹל שָׁלְטָנַיָא לֵהּ יִפְלְחוּן וְיִשְׁתַּמְּעוּן:</p>"],[9520011346,"<p>וַיֹּאמֶר שַׁלְחֵנִי כִּי עָלָה הַשָּׁחַר וַיֹּאמֶר לֹא אֲשַׁלֵּחֲךָ כִּי אִם בֵּרַכְתָּנִי. רִבִּי יְהוּדָה פָּתַח וְאָמַר, (שיר השירים ו׳:י׳) מִי זֹאת הַנִּשְׁקָפָה כְּמוֹ שָׁחַר יָפָה כַלְּבָנָה בָּרָה כַּחַמָּה אֲיֻמָּה כַּנִּדְגָלוֹת. הַאי קְרָא אוּקְמוּהָ וְאִתְּמָר, אֲבָל מִי זֹאת הַנִּשְׁקָפָה, אִלֵּין אִינוּן יִשְׂרָאֵל בְּזִמְנָא דְקוּדְשָׁא בְּרִיךְ הוּא יוֹקִים לוֹן וְיָפִיק לוֹן מִן גָּלוּתָא. כְּדֵין יִפְתַּח לוֹן פִּתְחָא דִּנְהוֹרָא (דהיא) דַּקִּיק זְעֵיר. וּלְבָתַר פִּתְחָא אַחֲרִינָא דְּאִיהוּ רַב מִינֵיהּ, עַד דְּקוּדְשָׁא בְּרִיךְ הוּא יִפְתַּח לוֹן תַּרְעִין עִלָּאִין פְּתִיחִין לְאַרְבַּע רוּחֵי עָלְמָא.</p>\n<p>וְכֵן כָּל מַה דְּעָבִיד קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל וּלְצַדִּיקַיָיא דִּי בְּהוּ, הָכִי כֻּלְּהוּ וְלָאו בְּזִמְנָא חָדָא. לְבַר נָשׁ דְּאִתְיְהִיב בַּחֲשׁוֹכָא וְדִיּוּרֵיהּ הֲוָה בַּחֲשׁוֹכָא תָּדִיר, כַּד יִבְעוּן לְאַנְהָרָא לֵיהּ, בַּעְיָין לְאִפְתְּחָא לֵיהּ נְהוֹרָא זְעֵירְתָּא כְּעֵינָא דְּמַחֲטָא, וּלְבָתַר רַב מִנֵּיהּ, וּכְדֵין בְּכָל זִמְנָא עַד דְּיִנְהֲרוּן לֵיהּ כָּל נְהוֹרָא כְּדְקָא יְאוּת.</p>\n<p>כָּךָ אִינוּן יִשְׂרָאֵל כְּמָה דְאַתְּ אָמֵר, (שמות כ״ג:ל׳) מְעַט מְעַט אֲ גרַשֶׁנּוּ מִפָּנֶיךָ עַד אֲשֶׁר תִּפְרֶה וְגו'. וְכֵן לְמַאן דְּאָתֵי אַסְוָותָא לָאו אִיהוּ בְּשַׁעְתָּא חָדָא, אֶלָּא זְעֵיר זְעֵיר עַד דְּיִתְתַּקַּף. אֲבָל לְעֵשָׂו לָאו הָכִי, אֶלָּא בְּזִמְנָא חָדָא נָהִיר לֵיהּ וְאִתְאֲבִיד מִנֵּיהּ זְעֵיר זְעֵיר. (ולזמנא דאתי לאומות עובדי עבודת כוכבים ומזלות (ישעיהו מ״ב:י״ג) יי כגבור יצא) עַד דְּיִתְתַּקְפוּן יִשְׂרָאֵל וִישֵׁיצוּן (וישבון) לֵיהּ מִכֹּלָּא, מֵעַלְמָא דֵין וּמֵעַלְמָא דְאָתֵי. וּבְגִין דְּנָהִיר בְּשַׁעְתָּא חָדָא, הֲוָה לֵיהּ שֵׁצִיאוּ מִכֹּלָּא. אֲבָל יִשְׂרָאֵל נְהוֹרָא דִלְהוֹן זְעֵיר זְעֵיר, עַד דְּיִתְתַּקְפוּן וְיַנְהִיר לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְעָלְמִין.</p>\n<p>וְכֹלָּא שָׁאֲלֵי לוֹן וְאָמְרֵי מִי זֹאת הַנִּשְׁקָפָה כְּמוֹ שָׁחַר, אִיהוּ קַדְרוּתָא דְצַפְרָא, וְדָא אִיהוּ נְהוֹרָא דָּקִיק. וּלְבָתַר יָפָה כַלְּבָנָה, בְּגִין דְּסִיהֲרָא נְהוֹרָא דִילָהּ נָהִיר יַתִּיר מִשַּׁחַר. וּלְבָתַר בָּרָה כַּחַמָּה, בְּגִין דִּנְהוֹרֵיהּ תַּקִּיף וְנָהִיר יַתִּיר מִסִּיהֲרָא. וּלְבָתַר אֲיֻמָּה כַּנִּדְגָלוֹת, תַּקִּיפָא בִּנְהוֹרָא תַּקִּיף כְּדְקָא יְאוּת.</p>\n<p>תָּא חֲזֵי, בְּעוֹד דְּאִתְחֲשַׁךְ יְמָמָא וְאִתְכַּסְיָא נְהוֹרָא וְאָתֵי צַפְרָא, יִתְנְהִיר בְּקַדְמִיתָא זְעֵיר זְעֵיר עַד דְּיִתְרַבֵּי נְהוֹרָא כְּדְקָא יְאוּת. דְּהָא כֵּיוָן דְּקוּדְשָׁא בְּרִיךְ הוּא יִתְעַר לְאַנְהָרָא לָהּ לִכְנֶסֶת יִשְׂרָאֵל, יִתְנְהִיר בְּקַדְמִיתָא כְּמוֹ שָׁחַר דְאִיהִי אוּכְמָא. וּלְבָתַר יָפָה כַלְּבָנָה, וּלְבָתַר בָּרָה כַּחַמָּה. וּלְבָתַר אֲיֻמָּה כַּנִּדְגָּלוֹת כְּמָה דְאִתְּמָר.</p>\n<p><Nonei></i>וְתָּא חֲזֵי, כֵּיוָן דְּאִסְתַּלִיק צַפְרָא, דְּהָא לָא כְּתִיב כִּי בָא הַשָּׁחַר אֶלָּא כִּי עָלָה, דְּהָא בְּזִמְנָא כִּי בָא הַשָּׁחַר, כְּדֵין אִתְתַּקַּף הַהוּא מְמַנָּא וְאַכִּישׁ לֵיהּ לְיַעֲקֹב. בְּגִין דְּהַהוּא מְמַנָּא אַכִּישׁ לְיַעֲקֹב לְמֵיהַב תַּקִּיפוּ לְאִתַתַּקָּפָא לְעֵשָׂו.</p>\n<p>וְכַד סָלִיק הַהוּא אוּכְמָא דְּשָׁחַר וְאִתְחֲזֵי אֲתָא נְהוֹרָא וְאִתְתַּקַּף יַעֲקֹב, דְּהָא כְדֵין מָטָא זִמְנֵיהּ לְאִתְנְהָרָא, מַה כְּתִיב וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ כַּאֲשֶׁר עָבַר אֶת פְּנוּאֵל וְהוּא צוֹלֵעַ עַל יְרֵכוֹ. וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ, דְּהָא כְּדֵין זִמְנָא לְאִתְנָהָרָא.</p>\n<p>וְהוּא צוֹלֵעַ עַל יְרֵכוֹ. כְּדֵין אִיהוּ רֶמֶז דְּהָא בְּעוֹד דְּיִשְׂרָאֵל בְּגָלוּתָא וְסָבְלִין כְּאֵבִין וְצַעֲרִין וְכַמָּה בִּישִׁין, כַּד אִתְנְהִיר לוֹן יְמָמָא וְיֵיתֵי לוֹן נַיְיחָא, כְּדֵין יִסְתַּכְּלוּן וְיִכְאֲבוּן בְּגַרְמַיְיהוּ מִכַּמָּה בִּישִׁין וְצַעֲרִין דְּסָבְלוּ וְיִתְמְהוּ עֲלַיְיהוּ. בְּגִין כָּךְ וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ. דְּהַהוּא זִמְנָא דְנַיְיחָא, וּכְדֵין וְהוּא צוֹלֵעַ עַל יְרֵכוֹ אִתְכָּאַב וְצָעֵיר גַּרְמֵיהּ עַל מַה דְּעֲבַר.</p>\n<p>וְאִיהוּ כַּד אִסְתַּלַּק קַדְרוּתָא דְּשַׁחֲרָא כְּדֵין אִתְתַּקַּף וְאִתְאֲחִיד בֵּיהּ דְּכַד אִתְחַלַּשׁ חֵילֵיהּ, דְּלֵית לֵיהּ שׁוּלְטָנוּתָא אֶלָּא בְּלֵילְיָא, וְיַעֲקֹב שָׁלְטָנוּתֵיהּ בִּימָמָא. וְעַל דָּא אָמַר וַיֹּאמֶר שַׁלְחֵנִי כִּי עָלָה הַשָּׁחַר, דְּהָא אֲנָא בִּרְשׁוּתְךָ קָאִימְנָא, וְהָא אִתְּמָר וְאוּקְמוּהָ:</p>"],[9520011347,"<p>(על כן לא יאכלו בני ישראל את גיד הנשה וגו', כי נגע בכף ירך יעקב, בגיד הנשה, דאפילו בהנאה אסיר ואפילו ליהביה לכלבא. ואמאי אקרי גיד הנשה. כלומר גיד דאיהו מנשה לבני נשא לפולחנא דמאריהון, ותמן הוא יצר הרע רביע.</p>\n<p>כיון דאתדבק עם יעקב לא אשכח אתר דיכיל לאתגברא עליה דיעקב, בגין דכל שייפי גופא סייעי ליעקב, וכלהו הוו תקיפין ולא הוו בהון חולשא, מה עבד, ויגע בכף ירכו בגיד הנשה, בזיניה ביצר הרע דאיהו זיניה ואתריה, ומתמן אתי יצר הרע על בני נשא.</p>\n<p>ובגין כך אמרה אורייתא לא יאכלו בני ישראל את גיד הנשה. כמה דאמרו חברייא, בשייפין דבר נש דרמיז לעילא אי טב, טב. ואי ביש, ביש. ובגין כך כל שייפא מתקיף שייפא. ודאי גיד הנשה מתקיף ליצר הרע דהוא זיניה, ובני ישראל לא יאכלו ליה, דלאו אינון מסטריה ומזיניה. אבל עמין עובדי עבודה זרה, יאכלו ליה, דאיהו מסטרא ומזינא דמלאכא דלהון דאיהו סמא\"ל בגין לתקפא לבהון.</p>\n<p>בגין דאית בבר נש רמ\"ח שייפין לקבל רמ\"ח פקודין דאורייתא דאינון למעבד אתיהבו, ולקבל רמ\"ח מלאכין דאתלבשת בהון שכינתא ושמא דלהון כשמא דמאריהון.</p>\n<p>ואית בבר נש שס\"ה גידין ולקבלהון שס\"ה פקודין דלאו אינון אתיהבו למעבד ולקבל שס\"ה יומי שתא, והא תשעה באב חד מנהון דאיהו לקבל סמא\"ל דאיהו חד מאינון שס\"ה מלאכין (נ\"א יומין), ובגין כך אמרה אורייתא לא יאכלו בני ישראל את גיד הנשה. א\"ת, לאסגאה תשעה באב דלא אכלין ביה ולא שתין.</p>\n<p>ובגין כך חזא קודשא בריך הוא כלא ונרמז בהון רמז ליעקב, ויאבק איש עמו, בכל יומי שתא ובכל שייפין דיעקב ולא אשכח בר ההוא גיד הנשה, מיד תשש חיליה דיעקב, וביומי שתא אשכח יום תשעה באב דביה אתתקף ואתגזר דינא עלנא ואתחרב בי מקדשא, וכל מאן דאכיל בתשעה באב כאילו אכיל גיד הנשה). רַבִּי חִיָּיא אָמַר, אִלְּמָלֵא לָא אִתְחַלַּשׁ חֵילָא (נ\"א דאתר) דָא דְּיַעֲקֹב, אִתְקְיַּים יַעֲקֹב לְגַבֵּיהּ וְאִתְבַּר חֵילָא דְעֵשָׂו לְעֵילָא וְתַתָּא.</p>\n<p>רִבִּי שִׁמְעוֹן פָּתַח וְאָמַר, (יחזקאל א׳:כ״ח) כְּמַרְאֵה הַקֶּשֶׁת אֲשֶׁר יִהְיֶה בֶּעָנָן בְּיוֹם הַגֶּשֶׁם כֵּן מַרְאֵה הַנֹּגַהּ סָבִיב הוּא מַרְאֵה דְּמוּת כְּבוֹד יְיָ וָאֶרְאֶה וָאֶפֹּל עַל פָּנַי וְגו'. הַאי קְרָא אִתְּמָר. אֲבָל תָּא חֲזֵי, דְּהָא כְּתִיב, (דברים לה) וְלֹא קָם נָבִיא עוֹד בְּיִשְׂרָאֵל כְּמשֶׁה. מַה בֵּין משֶׁה לִשְׁאָר נְבִיאֵי עָלְמָא. משֶׁה אִסְתַּכַּל בְּאַסְפַּקְלַרְיָא דְנָהֲרָא, שְׁאָר נְבִיאֵי לָא הֲווּ מִסְתַּכְּלֵי אֶלָּא בְּאַסְפַּקְלַרְיָא <Nonei></i>דְּלָא נָהֲרָא. משֶׁה הֲוָה שָׁמַע וְקָאִים עַל רַגְלוֹי, וְחֵילֵיהּ אִתְתַּקַּף, וְהֲוָה יָדַע מִלָּה עַל בּוּרְיֵיהּ, כְּמָה דִכְתִיב, (במדבר י״ב:ח׳) וּמַרְאֶה וְלֹא בְחִידוֹת. שְׁאָר נְבִיאֵי הֲווּ נָפְלֵי עַל אַנְפַּיְיהוּ וְאִתְחַלַּשׁ חֵילָא דִלְהוֹן וְלָא הֲווּ יָכְלֵי לְקָיְימָא עַל בּוּרְיֵיהּ דְּמִלָּה. מַאן גָּרַם לוֹן דָּא בְּגִין דִּכְתִיב כִּי נָגַע בְּכַף יֶרֶךְ יַעֲקֹב וְהוּא צוֹלֵעַ עַל יְרֵכוֹ.</p>\n<p>וְכָל אִינוּן נְבִיאִין לָא יָכִילוּ לְקָיְימָא עַל מַה דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד לֵיהּ לְעֵשָׂו, בַּר עוֹבַדְיָה נְבִיאָה דְּהֲוָה גִיּוֹרָא דְּאָתֵי מִסִּטְרָא דְעֵשָׂו, דָּא קָאִים בְּקִיּוּמֵיהּ עֲלֵיהּ דְּעֵשָׂו וְלָא אִתְחַלַּשׁ חֵילֵיהּ. וְעַל דָּא כָּל שְׁאָר נְבִיאֵי אִתְחַלַּשׁ תּוּקְפַיְיהוּ וְלָא הֲווּ יָכְלִין לְאִתְקָיְימָא לְקַבְּלָא מִלָּה עַל בּוּרְיֵיהּ כְּדְקָא יְאוּת, מַאי טַעְמָא, בְּגִין כִּי נָגַע בְּכַף יֶרֶךְ יַעֲקֹב בְּגִין הַנָּשֶׁה, דְּנָסִּיב וְשָׁאִיב כָּל חֵילָא דְּיַרְכָא, וְעַל דָּא אִתְבַּר חֵילָא דְיַרְכָא וְאִשְׁתָּאַר צוֹלֵעַ עַל יְרֵכוֹ. דְּהָא כָּל נְבִיאִין דְּעַלְמָא לָא יָכִילוּ לְאִדַּבְּקָא וּלְקָיְימָא בֵּיהּ.</p>\n<p>תָּא חֲזֵי, נְבִיאִין כֻּלְּהוּ בַּר משֶׁה לָא קָיְימוּ בְּתוּקְפַיְיהוּ כְּדְקָא חָזֵי. וּמַאן דְּלָעֵי בְּאוֹרַיְיתָא וְלֵית מַאן דְּסָמִיךְ לֵיהּ וְלָא אִשְׁתְּכַח מַאן דְּאַטִּיל מְלַאי לְכִיסֵיהּ לְאִתְתַּקְפָא. עַל דָּא אוֹרַיְיתָא קָא מִשְׁתַּכְּחָא בְּכָל דָּרָא וְדָרָא וְאִתְחַלַּשׁ תּוּקְפָא דְאוֹרַיְיתָא כָּל יוֹמָא וְיוֹמָא, בְּגִין דְּלֵית לוֹן לְאִינוּן דְּלָעָאן בָּהּ עַל מַה דְּסָמְכִין, וּמַלְכוּ חַיָּיבָא אִתְתַּקַּף בְּכָל יוֹמָא וְיוֹמָא. תָּא חֲזֵי,</p>\n<p>כַּמָּה גָּרִים חוֹבָא דָא, וּבְגִין דְּלֵית (לון) מַאן דְּאַסְמִיךְ לְאוֹרַיְיתָא כְּדְקָא יְאוּת אִינוּן סָמְכִין חַלָּשִׁין, וְגָרְמִין לְאִתְתַּקְפָא לְהַהוּא דְּלֵית לֵיהּ שׁוֹקִין וְרַגְלִין לְקָיְימָא עֲלַיְיהוּ.</p>\n<p>פָּתַח וְאָמַר, (בראשית ג׳:י״ד) וַיֹּאמֶר יְיָ אֱלֹהִים אֶל הַנָּחָשׁ כִּי עָשִׂיתָ זֹאת אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וְגו' עַל גְּחוֹנְךָ תֵּלֵךְ. מַאי עַל גְּחוֹנְךָ תֵּלֵךְ. דְּאִתָּבְרוּ סָמְכִין דִּילֵיהּ וּקְצִיצוּ רַגְלוֹי וְלֵית לֵיהּ עַל מַה דְּקָאִים. כַּד יִשְׂרָאֵל לָא בָּעָאן לְסָמְכָא לֵיהּ לְאוֹרַיְיתָא, אִינוּן יָהֲבִין לֵיהּ סָמְכִין וְשׁוֹקִין לְקָיְימָא וּלְאִתְתַּקְּפָא בְּהוּ.</p>\n<p>תָּא חֲזֵי, כַּמָּה עֲקִימוּ וְחַכִּימוּ אִתְחַכַּם בְּהַהוּא לֵילְיָא הַהוּא דְרָכִיב נָחָשׁ לְקֳבְלֵיהּ דְּיַעֲקֹב, דְּהָא אִיהוּ הֲוָה יָדַע דִּכְתִיב, (בראשית כ״ז:כ״ב) הַקּוֹל קוֹל יַעֲקֹב וְהַיָּדַיִם יְדֵי עֵשָׂו. וְאִי פָּסִיק קָלָא דְיַעֲקֹב כְּדֵין וְהַיָּדַיִם יְדֵי עֵשָׂו. בְּגִין כָּךְ אִסְתַּכַּל לְכָל סִטְרִין לְאַבְאָשָׁא לֵיהּ לְיַעֲקֹב וּלְאַפְסָקָא קָלֵיהּ.</p>\n<p>וְחָמָא לֵיהּ תַּקִּיף בְּכֹלָּא. דְּרוֹעִין מִסִּטְרָא דָא וּמִסִּטְרָא דָא דְּאִינוּן תָּקִפִין גּוּפָא דְּאִתְתַּקַּף בֵּינַיְיהוּ, וְחָמָא תּוּקְפָא דְאוֹרַיְיתָא וְאִתְתַּקַּף בְּכֹלָּא, כְּדֵי וַיַּרְא כִּי לא יָכוֹל לוֹ. מָה עֲבַד, מִיָּד וַיִּגַּע בְּכַף יְרֵכוֹ, דְּאִתְחַכַּם לְקֳבְלֵיהּ. אָמַר כֵּיוָן דְּאִתְּבָרוּ סָמְכִין דְּאוֹרַיְיתָא, מִיָּד אוֹרַיְיתָא לָא אִתְתַּקַּף. וּכְדֵין יִתְקַיַּים מַה דְּאָמַר אֲבוּהוֹן, הַקּוֹל קוֹל יַעֲקֹב וְהַיָּדַיִם יְדֵי עֵשָׂו. (בראשית כ״ז:מ׳) וְהָיָה כַּאֲשֶׁר תָּרִיד וּפָרַקְתָּ עֻלּוֹ מֵעַל צַוָּארֶךָ.</p>\n<p>וּבְדָא אִתְחַכַּם לְקֳבְלֵיהּ דְּיַעֲקֹב דְּהָא בְּגִין דְּיִתָּבַר חֵילָא דְאוֹרַיְיתָא אָזִיל וְאִתְתַּקַּף עֵשָׂו. וְכַד חָמָא דְלָא יָכִיל לָהּ לְאוֹרַיְיתָא, כְּדֵין חָלִישׁ תּוּקְפָא דְּאִינוּן דְּסָמְכִין לָהּ, וְכַד לָא יִשְׁתַּכַּח מַאן דְּסָמִיךְ לְאוֹרַיְיתָא, כְּדֵין לָא יְהֵא קוֹל קוֹל יַעֲקֹב וִיהוֹן יָדַיִם יְדֵי עֵשָׂו.</p>\n<p>וְכַד חָמָא יַעֲקֹב הָכִי כַּד סָלִיק צַפְרָא, אַתְקִיף (יעקב) בֵּיהּ וְאִתְגַּבַּר עֲלֵיהּ עַד דְּאִיהוּ בְּרִיךְ לֵיהּ וְאוֹדֵי לֵיהּ עַל אִינוּן בִּרְכָאן, וְאָמַר לֵיהּ לא יַעֲקֹב יֵאָמֵר עוֹד שִׁמְךָ כִּי אִם יִשְׂרָאֵל, לָאו יַעֲקֹב בְּעֲקִימוּ אֶלָּא בְּגְאוּתָא וְתוּקְפָא דְּלֵית מַאן דְּיָכִיל לָךְ.</p>\n<p>וְתָּא חֲזֵי, מֵהַאי נָחָשׁ כַּמָּה חֵילִין מִתְפָּרְשָׁן לְכָל סְטַר וְאִשְׁתַּכָּחוּ בְּעַלְמָא לְגַבֵּי בְּנֵי נָשָׁא. וּבְעִינָן לְקָיְימָא לְהַהוּא גִּיד הַנָּשֶׁה, דְּאַף עַל גַּב דְּקָרִיב בֵּיהּ הַהוּא דְּרָכִיב עַל חִוְיָא קַיָּים אִיהוּ, וְאִתְקְיַּים בְּגַוָּון וְלָא אִתְּבַּר.</p>\n<p>וְחֵילָא בְּעִינָן לְאִתְתַּקָּפָא בְּעַלְמָא וּלְאַחֲזָאָה כִּי שָׂרִיתָ עִם אֱלֹהִים וְעִם אֲנָשִׁים וַתּוּכָל. וְכַד חָמֵי דְּהָא לָא אִתְּבַּר וְלָא אִתְאֲכִיל הַהוּא אֲתַר, כְּדֵין אִתְבַּר חֵילֵיהּ וְתוּקְפֵיהּ <Nonei></i>וְלָא יָכִיל לְאַבְאָשָׁא לִבְנוֹי דְיַעֲקֹב. וְעַל דָּא לָא בְּעִינָן לְמֵיהַב דּוּכְתָּא לִבְרִיָּיתָא דְעַלְמָא לְמֵיכַל לֵיהּ וְלָא לְאִתְאֲכָלָא כְּלָל.</p>\n<p>רַבִּי יֵיסָא סָבָא דָּרַשׁ, כִּי נָגַע בְּכַף יֶרֶךְ יַעֲקֹב. כְּתִיב הָכָא כִּי נָגַע בְּכַף, וּכְתִיב הָתָם (במדבר י״ט:י״ג) כָּל הַנּוֹגֵעַ בְּמֵת בְּנֶפֶשׁ הָאָדָם (יטמא) וְגו'. מַה לְּהַלָּן מְסָאֲבָא אוּף הָכָא נָמֵי מְסָאֲבָא, דְּסָאִיב הַהוּא אֲתַר, וּמֵאֲתַר מְסָאֲבָא לֵית לָן (לאתתקנא) לְאִתְהֲנָאָה מִנֵּיהּ כְּלַל, כָּל שֶׁכֵּן בְּאֲתַר דְּקָרִיב הַהוּא סְטַר מְסָאֲבָא, וְאוֹרַיְיתָא לָא קָאֲמַר אֶלָּא כִּי נָגַע, וּכְתִיב וַיִּגַּע בְּכַף יְרֵכוֹ, כְּמָה דְאַתְּ אָמֵר, (במדבר י״ט:כ״ב) וְכֹל אֲשֶׁר יִגַּע בּוֹ הַטָּמֵא יִטְמָא, בְּרִיךְ רַחֲמָנָא דְּיָהִיב אוֹרַיְיתָא לְיִשְׂרָאֵל לְמִזְכֵּי בָהּ בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי כְּמָה דִכְתִיב, (משלי ג׳:ט״ז) אֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאלָהּ עשֶׁר וְכָבוֹד:</p>"],[9520011348,"<p>וְהוּא עָבַר לִפְנֵיהֶם וַיִּשְׁתַּחוּ אַרְצָה שֶׁבַע פְּעָמִים עַד גִּשְׁתּוֹ עַד אָחִיו. רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (שמות לה) כִּי לֹא תִשְׁתַּחֲוֶה לְאֵל אַחֵר כִּי יְיָ קַנָּא שְׁמוֹ. וְכִי יַעֲקֹב דְּאִיהוּ שְׁלֵימָא דְּאֲבָהָן דְּאִתְבְּרִיר חוּלָקָא שְׁלֵימָתָא לְקוּדְשָׁא בְּרִיךְ הוּא וְאִיהוּ אִתְקְרִיב לְגַבֵּיהּ יַתִּיר, (ס\"א ואשתלים לעילא ולתתא) הֵיךְ סָגִיד לֵיהּ לְהַהוּא רָשָׁע דְּעֵשָׂו דְּאִיהוּ בְּסִטְרָא דְאֵל אַחֵר, וּמַאן דְּסָגִיד לֵיהּ סָגִיד לְאֵל אַחֵר. אִי תֵימָא בְּגִין דְּאָמְרוּ תַּעְלָא בְּעִדָנֵיהּ סָגִיד לֵיהּ, לָאו הָכִי. דְּהָא עֵשָׂו כְּאֵל אַחֵר הֲוָה, וְיַעֲקֹב לא יִסְגוֹד לְהַהוּא סִטְרָא וּלְהַהוּא חוּלָקָא כְּלַל.</p>\n<p>(פתח רבי אבא ואמר) אֶלָא כְּתִיב, (שמואל א כ״ה:ו׳) וַאֲמַרְתֶּם כֹּה לֶחָי וְאַתָּה שָׁלוֹם וּבֵיתְךָ שָׁלוֹם וְכָל אֲשֶׁר לְךָ שָׁלוֹם. וְהָא אִתְּמָר דְּאָסִיר (ד\"א ל\"ג ליה) לְאַקְדוּמֵי לְהוּ שְׁלָם לְרַשִּׁיעַיָא, וְכֵיוָן דְּאָסִיר הֵיכִי אַשְׁכַּחְנָא דְּדָוִד אָמַר הַאי קְרָא לְנָבָל, אֶלָּא הָא אוּקְמוּהָ (שמות כג ב) דִּלְקוּדְשָׁא בְּרִיךְ הוּא קָאֲמַר, בְּגִין לְקָשְׁרָא לֵיהּ לְחַי. וְחָשִׁיב נָבָל דְּעֲלֵיהּ קָאֲמַר.</p>\n<p>כְּגַוְונָא דָא (בראשית יב) וַיִּשְׁתַּחוּ יִשְׂרָאֵל עַל רֹאשׁ הַמִּטָּה, וְכִי לְגַבֵּי דִבְרֵיהּ סְגִיד. אֶלָּא לְאַתְרֵיהּ דִּשְׁכִינְתָּא קָא כָּרַע וְסָגִיד, אוּף הָכָא, וְהוּא עָבַר לִפְנֵיהֶם. מַאי וְהוּא, דָּא שְׁכִינְתָּא עִלָּאָה דְּהֲוָה אָזְלָא קַמֵּיהּ (כרע), וְדָא הוּא נְטִירוּ עִלָּאָה. כֵּיוָן דְּחָמָא יַעֲקֹב, אָמַר, הָא עִידָן לְסָגְדָא לְגַבֵּיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא דְּהֲוָה אָזִיל קַמֵּיהּ.</p>\n<p>כָּרַע וְסָגִיד שְׁבַע זִמְנִין עַד גִּשְׁתּוֹ עַד אָחִיו, וְלָא כְּתִיב וַיִּשְׁתַּחוּ לְעֵשָׂו. אֶלָּא כֵּיוָן דְּחָמָא דְּהָא קוּדְשָׁא בְּרִיךְ הוּא אָזַל קַמֵּיהּ, כְּדֵין סָגִיד לְקֳבְלֵיהּ. בְּגִין דְּלָא לְמֵיהַב יְקָר לְמִסְגַד לְאָחֳרָא בַּר מִנִּיהּ, וְכֹלָּא אִיהוּ כְּדְקָא יְאוּת. זַכָּאִין אִינוּן צַדִּיקַיָיא דְּכָל עוֹבָדֵיהוֹן דְּקָא עָבְדֵי בְּגִין יְקָרָא דְמָארֵיהוֹן אִיהוּ, וּבְגִין דְּלָא יִסְטוּן לִימִינָא וְלִשְׂמָאלָא:</p>"],[9520011349,"<p>וַיָּרָץ עֵשָׂו לִקְרָאתוֹ וַיְחַבְּקֵהוּ וַיִּפֹּל עַל צַוָּארָו. צַוָּארוֹ כְּתִיב חָסֵר. וַיִּשָּׁקֵהוּ וַיִּבְכּוּ. רַבִּי יִצְחָק אָמַר (ישעיהו נ״ז:כ׳) וְהָרְשָׁעִים כַּיָּם נִגְרָשׁ כִּי הַשְׁקֵט לֹא יוּכַל וַיִּגְרְשׁוּ מֵימָיו רֶפֶשׁ וָטִיט, הַאי קְרָא אִתְּמָר. וּמִלֵּי דְאוֹרַיְיתָא, כַּמָּה רָזִין עִלָּאִין אִית בְּהוּ מְשַׁנְיָין דָּא מִן דָּא, וְכֹלָּא חַד.</p>\n<p>וְהָרְשָׁעִים כַּיָּם נִגְרָשׁ כִּי הַשְׁקֵט לא יוּכָל, דָּא עֵשָׂו דְּכָל עוֹבָדוֹי בִּרְשִׁיעוּ וּבְחִיּוּבָא, דְהָא כַּד אֲתָא לְגַבֵּיהּ דְּיַעֲקֹב, עוֹבָדוֹי לָא הֲווּ בִּשְׁלָם, וַיִּפּוֹל עַל צַוָּארָו, חַד. צַוָּארוֹ דָּא יְרוּשָׁלַ ם דְּאִיהוּ צַוָּארוֹ דְּכָל עָלְמָא. וַיִּפֹּל עַל צַוָּארוֹ, וְלא עַל צַוָּארָיו. בְּגִין דִּתְרֵין זִמְנִין אִתְחָרִיב בֵּי מַקְדְּשָׁא. חַד מִבָּבֶל, וְחַד מִזַּרְעֵיהּ דְּעֵשָׂו, דְּאַפִּיל גַּרְמֵיהּ עֲלֵיהּ זִמְנָא חָדָא וְחָרִיב לֵיהּ. וְעַל דָּא וַיִּפֹּל עַל צַוָּארוֹ חַד.</p>\n<p>וַיִּשָּׁ\"קֵהוּ, נָקוּד לְעֵיל, דְּלָא נָשְׁקֵיהּ בִּרְעוּתֵיהּ. וּתְנַן מַאי דִכְתִיב, (משלי כ״ז:ו׳) וְנְעְתָּרוֹת נְשִׁיקוֹת שׂוֹנֵא, דָּא בִּלְעָם כַּד בָּרִיךְ לוֹן לְיִשְׂרָאֵל. דְהָא לָא בָּרִיךְ לוֹן בִּרְעוּתָא דְלִבָּא. אוּף הָכָא נֶעְתָּרוֹת נְשִׁיקוֹת שׂוֹנֵא, דָּא עֵשָׂו.</p>\n<p>אָמַר רִבִּי יוֹסֵי, כְּתִיב (תהילים ג׳:ח׳) קוּמָה יְיָ הוֹשִׁיעֵנִי אֱלֹהַי כִּי הִכִּיתָ אֶת כָּל אוֹיְבַי לֶחִי שִׁנֵּי רְשָׁעִים שִׁבַּרְתָּ. וּתְנַן אַל תִּקְרֵי שִׁבַּרְתָּ אֶלָּא שִׁרְבַּבְתָּ. דְּהָא אַסְגִּיאוּ שִׁינוֹי וְחָשִׁיב לְנָשְׁכָא לֵיהּ וְכוּ'. וְעַל דָּא וַיִּבְכּוּ, דָּא בָּכֵי וְדָא בָּכֵי, וְאוּקְמוּהָ חַבְרַיָיא.</p>\n<p>תָּא חֲזֵי, כַּמָּה הֲוָה <Nonei></i>לִבֵּיהּ וּרְעוּתֵיהּ דְּעֵשָׂו לְגַבֵּי דְיַעֲקֹב, דְּהָא אֲפִילּוּ בְּהַהוּא שַׁעְתָּא חָשִׁיב לְאֹרֶךְ זִמְנִין (ס\"א לאורכא דיומין) לְמֶעְבַּד לֵיהּ בִּישִׁין וּלְקַטְרְגָא לֵיהּ, וְעַל דָּא וַיִּבְכּוּ. דָּא הֲוָה בָּכֵי, דְּלָא הֲוָה חָשִׁיב לְאִשְׁתְּזָבָא מִן יְדוֹי. וְדָא הֲוָה בָּכֵי, בְּגִין דְּאֲבוֹי הֲוָה קַיָּים וְלָא יָכִיל לֵיהּ.</p>\n<p>אָמַר רִבִּי אַבָּא וַדַּאי אִתְחַלַּשׁ רוּגְזֵיהּ דְּעֵשָׂו בְּשַׁעְתָּא דְחָמָא לֵיהּ לְיַעֲקֹב. מַאי טַעְמָא, בְּגִין דְּהָא אִסְתַּכַּם בַּהֲדֵיהּ הַהוּא מְמַנָּא דְעֵשָׂו. וְעַל דָא לָא יָכִיל עֵשָׂו לְשַׁלְטָאָה בְּרוּגְזֵיהּ, דְּהָכִי כָּל מִלִּין דְּהַאי עַלְמָא תַּלְיָין לְעֵילָא. וְכַד אִסְתַּכְּמוּ לְעֵילָא בְּקַדְמִיתָא אִסְתַּכְּמוּ לְתַתָּא. שָׁלְטָנוּתָא לָאו אִיהוּ לְתַתָּא עַד דְּאִיתְיָהִיב שָׁלְטָנוּתָא לְעֵילָא, וְכֹלָּא דָּא בְּדָא תַלְיָא:</p>"],[9520011350,"<p>יַעֲבָר נָא אֲדֹנִי לִפְנֵי עַבְדּוֹ וַאֲנִי אֶתְנַהֲלָה לְאִטִּי וְגו'. אָמַר רִבִּי אֶלְעָזָר, הַיְינוּ דְקָאַמְרִינָן בְּקַדְמִיתָא דְּיַעֲקֹב לָא בָּעָא הַשְׁתָּא אִינוּן בִּרְכָאן קַדְמָאי דְּבָרְכֵיהּ אֲבוֹי. (ס\"א בגין דכתיב, (איכה ג׳:כ״ז) טוב לגבר כי ישא על בנעוריו. וכתיב (משלי ל״א:כ״ה) ותשחק ליום אחרון) וַעֲדַיִין לָא אִתְקַיְימוּ בֵּיהּ אֲפִילּוּ חַד מִנַּיְיהוּ. בְּגִין דְּסָלִיק לוֹן לְסוֹף יוֹמַיָא בְּשַׁעְתָּא דְּאִצְטְרִיכוּ לִבְנוֹי לְגַבֵּי כָּל עַמִּין דְּעַלְמָא.</p>\n<p>וּבְגִין כָּךְ בְּשַׁעְתָּא דְּאָמַר עֵשָׂו נִסְעָה וְנֵלֵכָה, וְנִפְלוּג הַאי עַלְמָא כְּחֲדָא וְנִשְׁלוֹט כְּחֲדָא. מַה אָמַר, יַעֲבָר נָא אֲדֹנִי לִפְנֵי עַבְדּוֹ. יַקְדִּים עֵשָׂו שָׁלְטָנֵיהּ הַשְׁתָּא בְּהַאי עַלְמָא. יַעֲבָר נָא, כְּמָה דְאַתְּ אָמֵר, (מיכה ב׳:י״ג) וַיַּעֲבוֹר מַלְכָּם לִפְנֵיהֶם וַיְיָ בְּרֹאשָׁם, אַקְדִּים אַנְתְּ שׁוּלְטָנוּתָךְ בְּקַדְמִיתָא בְּהַאי עַלְמָא, וַאֲנִי אֶתְנַהֲלָה לְאִטִּי. אֲנָא אֲסַלֵּק גַּרְמִי לְהַהוּא עַלְמָא דְאָתֵי וּלְסוֹף יוֹמַיָא לְאִינוּן יוֹמַיָא דְאָזְלִין לְאַט.</p>\n<p>לְרֶגֶל הַמְלָאכָה, מַאן מְלָאכָה. דָּא אַסְפַּקְלַרְיָא דְלָא נָהֲרָא דְּבָהּ אִתְעֲבִיד עֲבִידְתָּא דְעָלְמָא. אֲשֶׁר לִפְנֵי, דָּא הִיא מִן קֳדָם יְיָ בְּכָל אֲתַר. וּלְרֶגֶל הַיְלָדִים, דָא הוּא רָזָא דִכְרוּבִים, לְאַחֲזָאָה רָזָא דִמְהֵימְנוּתָא דְּאִיהוּ אִתְדָּבַּק בְּהוּ.</p>\n<p>עַד אֲשֶׁר אָבֹא אֶל אֲדֹנִי שֵׂעִירָה, אֲנָא אֶסְבּוֹל גָּלוּתָא דִילָךְ עַד דְּיֵיתֵי וְיִמְטֵי זִמְנָא דִילִי לְשַׁלְטָאָה עַל הַר עֵשָׂו, כְּמָה דְאַתְּ אָמֵר, (עובדיה א׳:כ״א) וְעָלוּ מוֹשִׁיעִים בְּהַר צִיּוֹן לִשְׁפֹּט אֶת הַר עֵשָׂו, וּכְדֵין וְהָיְתָה לַיְיָ הַמְלוּכָה:</p>"],[9520011351,"<p>וְיַעֲקֹב נָסַע סֻכֹּתָה וַיִּבֶן לוֹ בָּיִת וּלְמִקְנֵהוּ עָשָׂה סֻכֹּת עַל כֵּן קָרָא שֵׁם הַמָּקוֹם סֻכּוֹת. רִבִּי חִיָּיא פָּתַח וְאָמַר, (תהילים קכ״ז:א׳) שִׁיר הַמַּעֲלוֹת לִשְׁלֹמֹה אִם יְיָ לֹא יִבְנֶה בַּיִת וְגו', אִם יְיָ לא יִשְׁמָר עִיר וְגו'. תָּא חֲזֵי, בְּשַׁעְתָּא דְסָלִיק בִּרְעוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא לְמִבְרֵי עַלְמָא, אַפִּיק (טו א) מִבּוּצִינָא דְקַרְדִינוּתָא חַד קִטּוּרָא, וְאִתְלְהִיט מִגּוֹ חֲשׁוֹכָא, וְאִשְׁתָּאַר בִּסְלִיקוּ. וְנָחֲתָא לְתַתָּא, הַהִיא חֲשֵׁכָה לָהִיט (ואתלהיט) בְּמֵאָה שְׁבִילִין אוֹרְחִין דְּקִיקִין רַבְרְבָן, וְאִתְעֲבִיד בֵּיתָא דְעַלְמָא.</p>\n<p>הַאי בֵּיתָא אִיהוּ גוֹ אֶמְצָעִיתָא דְכֹלָּא, כַּמָּה פִּתְחִין וְאִדְרִין לֵיהּ סְחוֹר סְחוֹר, דּוּכְתִּין עִלָּאִין קַדִּישִׁין, תַּמָּן מְקַנְנֵי צִפֳּרֵי שְׁמַיָא, כָּל חַד וְחַד לְזִינֵיהּ. בְּגַוֵּויהּ נָפִיק חַד אִילָנָא רַבְרְבָא וְתַקִּיף עָפְיֵיהּ וְאִנְבֵּיהּ סַגֵּי, מְזוֹנָא לְכֹלָּא בֵּיהּ. הַהוּא אִילָנָא סָלִיק לַעֲנָנֵי שְׁמַיָא וְאִתְטַמַּר בֵּין תְּלַת טוּרִין, מִתְּחוֹת אִילֵּין תְּלַת טוּרִין נָפִיק, סָלִיק לְעֵילָא נָחִית לְתַתָּא.</p>\n<p>הַאי בֵּיתָא אִתְשַׁקְיָיא מִנֵּיהּ, וְגָנִיז בְּגַוֵּויהּ כַּמָּה גִּנְזִין עִלָּאִין דְּלָא אִתְיְדָעוּ, בְּדָא אִתְבְּנֵי הַאי בֵּיתָא וְאִשְׁתַּכְלַל הַהוּא אִילָנָא אִתְגַּלְּיָיא בִּימָמָא, וְאִתְכַּסְּיָא בְּלֵילְיָא, וְהַאי בֵּיתָא שָׁלְטָא בְּלֵילְיָא וְאִתְכַּסְּיָא בִּימָמָא.</p>\n<p>בְּשַׁעְתָּא דְּעָאל חֲשׁוֹכָא וְאִתְקַטִּיר בֵּיהּ שָׁלְטָא, וְכָל פִּתְחִין סְתִימִין מִכָּל סִטְרִין, כְּדֵין כַּמָּה רוּחִין פָּרְחִין בַּאֲוִירָא, תְּאִיבִין לְמִנְדַע וּלְמֵיעַל בֵּיהּ, וְעָאלִין בֵּין אִינוּן צִפּוֹרִין, וְנָטְלִין סָהֲדוּתָא, וְשָׁטְיָין וְחָמָאן מַה דְּחָמָאן.</p>\n<p>עַד דְּאִתְעַר הַהוּא חֲשׁוֹכָא דְּאִתְקַטִּיר בֵּיהּ, וְאַפִּיק חַד שַׁלְהוֹבָא וּבָטַשׁ בְּכָל פַּטִּישִׁין תַּקִּיפִין, וּפְתַח פִּתְחִין, וּבָקַע טִנָּרִין. סַלְקָא וְנָחֲתָא הַהוּא שַׁלְהוֹבָא, וּבָטַשׁ בְּעַלְמָא, וְאִתְעַר קָלִין לְעֵילָא וְתַתָּא.</p>\n<p>כְּדֵין חַד <Nonei></i>כָּרוֹזָא סָלִיק, וְאִתְקַטִּיר בַּאֲוִירָא, וְקָרֵי, הַהוּא אֲוִירָא נָפְקָא מִגּוֹ עַמּוּדָא דַּעֲנָנָא דְּמַדְבְּחָא פְּנִימָאָה, וְכַד נַפְקָא אִתְפַּשַּׁט בְּאַרְבַּע סִטְרֵי עָלְמָא. אֶלֶף אַלְפִין קָיְימִין מִסִּטְרָא דְאִיהוּ שְׂמָאלָא, וְרִבּוֹא רִבְוָון קָיְימִין מִסִּטְרָא דְאִיהוּ יָמִינָא, וְכָרוֹזָא קָאִים בְּקִיּוּמֵיהּ. קָרֵא בְחָיִל וְאַכְרִיז, כְּדֵין כַּמָּה אִינוּן דִּמְתַקְּנִי שִׁירָתָא וּפָלְחִין פּוּלְחָנָא, וּתְרֵין פִּתְחִין פְּתִיחוּ. חַד לִסְטַר דָּרוֹמָא, וְחַד לִסְטַר צָפוֹן.</p>\n<p>סָלְקָא הַאי בֵיתָא וְאִתְיְהִיבַת וְאִתְקַטְּרַת בֵּין תְּרֵין סִטְרִין, וְשִׁירִין מְזַמְּרָן וְתוּשְׁבְּחָן סָלְקִין. כְּדֵין עָאל מַאן דְּעָאל בִּלְחִישָׁא, וּבֵיתָא מִתְלַהֲטָא בְּשִׁית נְהוֹרִין, נָהֲרִין זִיוָא לְכָל סְטַר, וְנַהֲרִין דְּבוּסְמָא נָפְקִין. וְאִתְשַׁקְיָין כָּל חֵיוַת בְּרָא, כְּמָה דְאַתְּ אָמֵר (תהילים ק״ד:י״א) יַשְׁקוּ כָּל חַיְתוֹ שָׂדָי יִשְׁבְּרוּ פְרָאִים צְמָאָם וְגו'. וְזָמְרִין עַד דְּסָלְקָא צַפְרָא. וְכַד סָלְקָא צַפְרָא כְּדֵין כֹּכְבַיָא וּמַזָּלֵי שְׁמַיָא וְחֵילֵיהוֹן כֻּלְּהוֹן מְשַׁבְּחָן וְאָמְרֵי שִׁירָתָא, כְּמָה דְאַתְּ אָמֵר, (איוב ל״ח:ז׳) בְּרָן יַחַד כֹּכְבֵי בֹקֶר וַיָּרִיעוּ כָּל בְּנֵי אֱלהִים.</p>\n<p>תָּא חֲזֵי (תהילים קכ״ז:א׳) אִם ה' לא יִבְנְה בַיִת שָׁוְא עָמְלוּ בוֹנָיו בּוֹ. אִם יְיָ לֹא יִשְׁמָר עִיר שָׁוְא שָׁקַד שׁוֹמֵר. אִם יְיָ וְגו' דָּא מַלְכָּא עִלָּאָה, דְּאִיהוּ בּוֹנֶה לְהַאי בֵּיתָא תָּדִיר וְאַתְקִין לֵיהּ, אֵימָתַי, כַּד סָלְקִין רְעוּתִין פּוּלְחָנִין מִתַּתָּא כְּדְקָא יְאוּת.</p>\n<p>אִם יְיָ לֹא יִשְׁמָר עִיר, אֵימָתַי, בְּשַׁעְתָּא דְּאִתְחַשְׁכָא לֵילְיָא, וְסִטְרִין מְזַיְינִין שָׁרָאן וְשָׁטָאן בְּעַלְמָא, וּפִתְחִין סְתִימִין, וְאִתְנְטִיר מִכָּל סִטְרִין דְּלָא יִקְרַב בֵּיהּ עָרֵל וּמְסָאֲבָא, כְּמָה דְאַתְּ אָמֵר (ישעיהו נ״ב:א׳) לֹא יוֹסִיף יָבֹא בָךְ עוֹד עָרֵל וְטָמֵא, דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאַעֲבָרָא לוֹן מֵעַלְמָא.</p>\n<p>מַאן עָרֵל וּמַאן טָמֵא. אֶלָא כֹּלָּא חַד, עָרֵל וְטָמֵא. דָּא הוּא דְּאִתְפַּתָּא בֵּיהּ וְאָזִיל אֲבַתְרֵיהּ אָדָם וְאִנְתְּתֵיהּ, וְגָרִימוּ מוֹתָא לְכָל עַלְמָא. וְאִיהוּ דְּמַסְאִיב הַאי בֵּיתָא, עַד הַהוּא זִמְנָא דְּיַעֲבַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא מֵעַלְמָא. בְגִין כָּךְ אִם יְיָ לֹא יִשְׁמָר עִיר, שָׁוְא וַדַּאי.</p>\n<p>תָּא חֲזֵי, וְיַעֲקֹב נָסַע סֻכֹּתָה, אִתְנְטִיל לְקֳבְלָא חוּלָקֵיהּ דִּמְהֵימְנוּתָא. מַה כְּתִיב לְעֵילָא, וַיָּשָׁב בַּיּוֹם הַהוּא עֵשָׂו לְדַרְכּוֹ שֵׂעִירָה, וּכְתִיב וְיַעֲקֹב נָסַע סֻכֹּתָה. אֶלָּא כָּל חַד אִתְפְּרַשׁ לְסִטְרָא דִילֵיהּ, עֵשָׂו לְסִטְרָא דְשֵׂעִיר. מַאן שֵׂעִיר, דָּא הִיא אִשָּׁה זָרָה אֵל נִכָר. וְיַעֲקֹב נָסַע סֻכֹּתָה, דָּא מְהֵימְנוּתָא עִלָּאָה.</p>\n<p>וַיִּבֶן לוֹ בָיִת, כְּמָה דְאַתְּ אָמֵר, (ישעיה ב) בֵּית יַעֲקֹב. אָמַר רִבִּי אֶלְעָזָר, דְּאַתְקִין תְּפִלַּת עַרְבִית כְּדְקָא יְאוּת. וּלְמִקְנִהוּ עָשָׂה סֻכֹּת, שְׁאָר סֻכֹּת לְנַטְרָא לוֹן וְדָא הוּא חוּלָקֵיהּ.</p>\n<p>וּכְדֵין וַיָּבֹא יַעֲקֹב שָׁלֵם. שָׁלֵם מִכֹּלָּא וְאוּקְמוּהָ. וּכְתִיב, (תהילים ע״ו:ג׳) וַיְהִי בְשָׁלֵם סֻכּוֹ וְגו' וְאוּקְמוּהָ, וְכֹלָּא רָזָא חָדָא. כְּדֵין אִתְחַבֵּר עִמֵּיהּ מְהֵימְנוּתָא כַּד הֲוָה שְׁלִים כַּד אִתְעֲטַר בְּדוּכְתֵּיהּ דְּאִתְחֲזֵי לֵיהּ. וּכְדֵין הַאי סֻכָּה אִתְעַטְּרַת בַּהֲדֵיהּ, דְּהֲוָה שְׁלִים מֵאֲבָהָן, דְּהֲוָה שְׁלִים מִבְּנוֹי, וְדָא הוּא שָׁלֵם. שָׁלֵם לְעֵילָא שָׁלֵם לְתַתָּא, שָׁלֵם בִּשְׁמַיָא שָׁלֵם בְּאַרְעָא. שָׁלֵם לְעֵילָא דְּאִיהוּ כְּלָלָא דְּאֲבָהָן, תִּפְאֶרֶת יִשְׂרָאֵל. שָׁלֵם לְתַתָּא בִּבְנוֹי קַדִּישִׁין. שְׁלִים בִּשְׁמַיָא, שְׁלִים בְּאַרְעָא, וּכְדֵין וַיְהִי בְשָׁלֵם סֻכּוֹ וְאוּקְמוּהָ. מִיָּד מַה כְּתִיב וַתֵצֵא דִינָה בַת לֵאָה, וְאוּקְמוּהָ חַבְרַיָיא.</p>"],[9520011352,"<p>תָּא חֲזֵי, כַּמָּה דַרְגִין וְסִטְרִין מִתְפָּרְשָׁן לְעֵילָא וְכֻלְּהוּ מְשַׁנְיָין דָּא מִן דָּא. חֵיוָון מְשַׁנְיָין אִלֵּין מֵאִלֵּין, אִלֵּין מְקַטְרְגִין לְשַׁלְּטָאָה עַל אִלֵּין וּלְמִטְרַף טַרְפִין כָּל חַד וְחַד לְזִינֵיהּ.</p>\n<p>מִסִּטְרָא דְרוּחָא מְסָאֲבָא כַּמָּה דַרְגִּין מִתְפָּרְשִׁין, וְכֻלְּהוּ כָּמַן לְקַטְרְגָא אִלֵּין לָקֳבֵיל אִלֵּין, דְּהָא כְּתִיב (דברים כ״ב:י׳) לֹא תַחֲרשׁ בְּשׁוֹר וּבַחֲמֹר יַחְדָּו, דְּכַד קָא מִתְחַבְּרָן מְקַטְרְגֵי עַלְמָא.</p>\n<p>וְתָּא חֲזֵי, תִּיאוּבְתָּא דְדַרְגִין מְסָאֲבִין לָאו אִיהוּ אֶלָּא לְקַטְרְגָא בְּסִטְרִין קַדִּישִׁין. יַעֲקֹב דְּאִיהוּ קַדִּישָׁא, כֻּלְּהוּ כָּמַן לֵיהּ וְקִטְרְגוּ בַּהֲדֵיהּ. בְּקַדְמִיתָא נָשְׁכֵיהּ חִוְיָא, כְּמָה דְאַתְּ אָמֵר וַיִּגַּע בְּכַף יֻרִכוֹ, הַשְׁתָּא נָשְׁכֵיהּ חֲמוֹר.</p>\n<p>תַּמָּן אִיהוּ קָאִים לְגַבֵּי חִוְיָא, הַשְׁתָּא שִׁמְעוֹן וְלֵוִי דְאָתוּ מִסִּטְרָא <Nonei></i>דְּדִינָא קַשְׁיָא קָיְימוּ לְגַבֵּיהּ דְּחֲמוֹר וְשַׁלִּיטוּ עֲלוֹי בְּכָל סִטְרִין וְאִתְכַּפְיָא קַמַּיְיהוּ. כְּמָה דְאַתְּ אָמֵר וְאֶת חֲמוֹר וְאֶת שְׁכֶם בְּנוֹ הָרְגוּ לְפִי חָרֶב. וְשִׁמְעוֹן דְּהֲוָה (שור) מַזָּלֵיהּ (איהו) שׁוֹר, אֲתָא עַל חֲמוֹר וְקִטְרֵג בֵּיהּ, בְּגִין דְּלָא יִתְחַבְּרוּן כְּחֲדָא, וְאִשְׁתַּכַּח אִיהוּ מְקַטְרְגָא דִילֵיהּ.</p>\n<p>וְכֻלְּהוּ אָתֵי לְקַטְרְגָא לֵיהּ לְיַעֲקֹב וְאִשְׁתְּזִיב, וּלְבָתַר אִיהוּ שַׁלִּיט עֲלַיְיהוּ. לְבָתַר אֲתָא שׁוֹר וְאִשְׁתַּלִים בַּחֲמוֹרִים דְּכֻלְּהוּ מִסִּטְרָא דְּחֲמוֹר. יוֹסֵף דְּאִיהוּ שׁוֹר, וּמִצְרַיִם דְּאִינוּן חֲמוֹרִים דִּכְתִיב בְּהוּ (יחזקאל כ״ג:כ׳) אֲשֶׁר בְּשַׂר חֲמוֹרִים בְּשָׂרָם.</p>\n<p>וְעַל דָּא לְבָתַר בְּנֵי יַעֲקֹב נָפְלוּ בֵּין אִינוּן חֲמוֹרִים, בְּגִין דְּאִזְדַּוַּוג שׁוֹר בַּהֲדַיְיהוּ, וְנָשְׁכוּ לוֹן גַּרְמַיָיא וּבִשְׂרָא. עַד דְּאִתְעַר לֵוִי כְּמִלְקַדְּמִין וּבַדַּר לְאִינוּן חֲמוֹרִים (ס\"א דאזדווגו) לְכַפְיָא לוֹן וְתָבַר תּוּקְפֵהוֹן מֵעַלְמָא, וְאַפִּיק לְשׁוֹר מִתַּמָּן. הֲדָא הוּא דִכְתִיב, (שמות י״ג:י״ט) וַיִּקַּח משֶׁה אֶת עַצְמוֹת יוֹסֵף עִמּוֹ.</p>\n<p>תָּא חֲזֵי, כַּד אֲתָא שִׁמְעוֹן בְּקַדְמִיתָא עַל הַהוּא חֲמוֹר, אִתְעַר עֲלֵיהוֹן דַּם דְּאִתְגַּזָּרוּ, וּלְבָתַר וַיַּהַרְגוּ כָּל זָכָר. כְּגַוְונָא דָא עֲבַד קוּדְשָׁא בְּרִיךְ הוּא עַל יְדָא דְּלֵוִי, דָּא משֶׁה. בְּאִינוּן חֲמוֹרִים בְּמִצְרַיִם. בְּקַדְמִיתָא דַּם, וּלְבָתַר (שמות י״ג:ט״ו) וַיַּהֲרֹג יְיָ כָּל בְּכוֹר בְּאֶרֶץ מִצְרַיִם וְגו'. הָכָא בְּהַאי חֲמוֹר כְּתִיב, וְאֶת כָּל חֵילָם וְאֶת כָּל טַפָּם וְאֶת כָּל בְּהֶמְתָּם וְגו'. הָתָם בְּאִינוּן חֲמוֹרִים כְּתִיב, (שמות י״ב:ל״ה) כְּלֵי כֶסֶף וּכְלֵי זָהָב וּשְׂמָלוֹת, וּכְתִיב, (שמות י״ב:ל״ח) וְגַם עֵרֶב רַב עָלָה אִתָּם וְצֹאן וּבָקָר וְגו'.</p>\n<p>וְשִׁמְעוֹן וְלֵוִי, דָּא קָאִים לְגַבֵּי הַאי חֲמוֹר, וְדָא קָאִים לְגַבֵּי כָּל אִינוּן חֲמוֹרִים, כֻּלְּהוּ בָּעוּ לְאִשְׁתַּתְּפָא בַּהֲדֵיהּ דְּיַעֲקֹב קַדִּישָׁא וְאִתְתַּקְּנוּ לְנַשְׁכָא לֵיהּ, וְאִיהוּ בִּבְנוֹי קָאִים לְגַבַּיְיהוּ וְכַיִּיף לוֹן תְּחוֹתֵיהּ.</p>\n<p>הַשְׁתָּא דְעֵשָׂו נָשִׁיךְ לֵיהּ וְלִבְנוֹי, מַאן יָקוּם לְגַבֵּיהּ, יַעֲקֹב וְיוֹסֵף. דָּא מִסִּטְרָא דָא וְדָא מִסִּטְרָא דָא. דִּכְתִיב, (עובדיה א׳:י״ח) וְהָיָה בֵּית יַעֲקֹב אֵשׁ וּבֵית יוֹסֵף לֶהָבָה וּבֵית עֵשָׂו לְקַשׁ וְגו':</p>\n<p>וַיִּסָּעוּ וַיְהִי חִתַּת אֱלהִים עַל הֶעָרִים אֲשֶׁר סְבִיבוֹתֵיהֶם וְלֹא רָדְפוּ אַחֲרֵי בְּנֵי יַעֲקֹב. אָמַר רִבִּי יוֹסֵי כֻּלְּהוּ הֲווּ מִתְכַּנְּשֵׁי, וְכַד הֲווּ חַגְרֵי זַיְינֵי קְרָבָא הֲווּ מְרַתְּתֵי וְשַׁבְקִין לוֹן, וּבְגִין כָּךְ וְלא רָדְפוּ אַחֲרִי בְּנֵי יַעֲקֹב:</p>"],[9520011353,"<p>הָסִירוּ אֶת אֱלהֵי הַנֵּכָר וְגו'. הָסִירוּ אֶת אֱלהֵי הַנֵּכָר, אִלֵּין אִינוּן דְּנָטְלוּ מִשְּׁכֶם מָאנֵי כַּסְפָּא וְדַהֲבָא דְּהֲוָה חָקִיק עֲלַיְיהוּ טַעֲוָא דִלְהוֹן. רִבִּי יְהוּדָה אָמַר, טַעֲוָון הֲווּ מִכַּסְפָּא וְדַהֲבָא. וְיַעֲקֹב אַטְמִין לוֹן תַּמָּן, בְּגִין דְּלָא יִתְהַנּוּן מִסִּטְרָא דְּעֲבוֹדָה זָרָה, דְּאָסִיר לֵיהּ לְבַר נָשׁ לְאִתְהַנֵּי מִנֵּיהּ לְעָלְמִין.</p>\n<p>רִבִּי יְהוּדָה וְרִבִּי חִזְקִיָּה הֲווּ אָזְלֵי בְּאָרְחָא, אָמַר רִבִּי חִזְקִיָּה לְרִבִּי יְהוּדָה, מַאי דִכְתִיב, (שמואל ב י״ב:ל׳) וַיִּקַּח אֶת עֲטֶרֶת מַלְכָּם מֵעַל רֹאשׁוֹ וּמִשְׁקָלָהּ כִּכַּר זָהָב וְאֶבֶן יְקָרָה וַתְּהִי עַל רֹאשׁ דָּוִד. וְתָנִינָן, שִׁקּוּץ בְּנֵי עַמּוֹן מִלְכֹּם שְׁמֵיהּ. וְדָא הוּא עֲטֶרֶת מַלְכָּם. מַאי טַעֲמָא וַתְּהִי עַל רֹאשׁ דָּוִד. וּמַאי טַעְמָא כְּתִיב שִׁקּוּץ. דְּהָא בִּשְׁאָר טַעֲוָון עַמְּמַיָא עוֹבְדֵי עֲבוֹדָה זָרָה כְּתִיב אֱלֹהֵי הָעַמִּים, אֱלֹהִים אֲחֵרִים, אֵל נֵכָר, אֵל אַחֵר, וּבְהַאי אָמַר שִׁקּוּץ חַד.</p>\n<p>אָמַר לֵיהּ, וּבְכָל טַעֲוָון עַמְּמַיָיא עוֹבְדֵי עֲבוֹדָה זָרָה הָכִי קָרָא לוֹן קוּדְשָׁא בְּרִיךְ הוּא, דִּכְתִיב, (דברים כג) וַתִּרְאוּ אֶת שִׁקּוּצֵיהֶם וְאֶת גִּלּוּלֵיהֶם. וּמַה דְּאָמַר וַיִּקַּח אֶת עֲטֶרֶת מַלְכָּם, דְּאִיהוּ מִלְכּוֹם, הָכִי הוּא וַדַּאי. אֶלָּא אִיתַּי הַגִּתִּי עַד דְּלָא אִתְגְיַּיר, כְּדֵין אִיהוּ תָּבַר לָהּ לְהַהוּא עֲטֶרֶת דְּאִיהוּ מִלְכּוֹם, הַהוּא דִיוּקְנָא דְּחֲקִיק עֲלָהּ וּפָגִים לָהּ. כְּדֵין אִיהוּ עֲבַד לָהּ הֵיתֵּר לְאִתְהַנֵּי מִנָּהּ וְהֲוַת עַל רֵישֵׁיהּ. וְתָּא חֲזֵי, שִׁקּוּץ בְּנֵי עַמּוֹן, חַד חִוְיָא בְּסוּרְטָא הֲוָה חָקִיק עַל הַהוּא כִּתְרָא, וּבְגִין כָּךְ אִקְרֵי שִׁקּוּץ זוּהֲמָא.</p>\n<p>רִבִּי יִצְחָק אָמַר, הָסִירוּ אֶת אֱלהֵי הַנֵּכָר, אִלֵּין שְׁאָר נָשִׁין דְּהֲווּ מַיְיתֵי בְּגַוַּיְיהוּ כָּל נְבַזְבְּזָן דִּלְהוֹן. וְעַל דָּא כְּתִיב וַיִּתְּנוּ אֶל יַעֲקֹב אֶת כָּל אֱלֹהֵי הַנִּכָר. אִלֵּין נָשִׁין, כָּל נְבַזְבְּזָן וְכָל טַעֲוָון דְּדַהֲבָא וְכַסְפָּא. וַיִּטְמוֹן אוֹתָם יַעֲקֹב, בְּגִין דְּלָא <Nonei></i>יִתְהַנּוּן מִסִּטְרָא דְּעֲבוֹדָה זָרָה כְּלָל.</p>\n<p>תָּא חֲזֵי, דְּיַעֲקֹב גְּבַר שְׁלִים בְּכֹלָּא הֲוָה, וְהֲוָה מִתְדַּבַּק בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא. מַה כְּתִיב, וְנָקוּמָה וְנַעֲלֲה בֵּית אֵל וְאֶעֱשֶׂה שָׁם מִזְבֵּחַ לָאֵל הָעוֹנֶה אוֹתִי בְּיוֹם צָרָתִי וַיְהִי עִמָּדִי בַּדֶּרֶךְ אֲשֶׁר הָלָכְתִּי, מִיָּד וַיִּתְּנוּ אֶל יַעֲקֹב. מִכָּאן דְּבָעֵי בַּר נָשׁ לְשַׁבָּחָא לְקוּדְשָׁא בְּרִיךְ הוּא וּלְאוֹדָאָה לֵיהּ עַל נִסִּין וְעַל טָבָאן דְּעֲבַד עִמֵּיהּ, הֲדָא הוּא דִכְתִיב וַיְהִי עִמָּדִי בַּדֶּרֶךְ אֲשֶׁר הָלָכְתִּי.</p>\n<p>תָּא חֲזֵי, בְּקַדְמִיתָא כְּתִיב וְנָקוּמָה וְנַעֲלֶה בֵּית אֵל וְגו', אַכְלִיל בְּנוֹי בַּהֲדֵיהּ. וּלְבָתַר כְּתִיב וְאֶעֱשֶׂה שָׁם מִזְבֵּחַ וְלָא כְּתִיב וְנַעֲשֶׂה. דְּאַפִּיק לוֹן מִכְּלָלָא דָא, מַאי טַעְמָא, בְּגִין דְּעֲלֵיהּ הֲוָה מִלָּה. יַעֲקֹב אַתְקִין תְּפִלַּת עַרְבִית, וַדַּאי. וְאִיהוּ עֲבַד מַדְבְּחָא וְעֲלֵיהּ הֲוָה מִלָּה, וּבְגִין דְּאִיהוּ עָבַר כָּל אִינוּן עָקְתִין מִן יוֹמָא דְעָרַק קַמֵּיהּ דְּאֲחוּהָ. דִּכְתִיב וַיְהִי עִמָּדִי בַּדֶּרֶךְ אֲשֶׁר הָלָכְתִּי, וְאִינוּן אָתוּ לְבָתַר לְעַלְמָא. וְעַל דָּא לָא אָעִיל לוֹן בַּהֲדֵיהּ.</p>\n<p>רִבִּי אֶלְעָזָר אָמַר, מִכָּאן מַאן דְּיִתְעֲבִיד לֵיהּ נִסָּא, אִיהוּ בָּעֵי לְאוֹדָאָה. מַאן דְּאָכִיל נַהֲמָא בְּפָתוֹרָא, אִיהוּ בָּעֵי לְבָרְכָא, וְלָא אָחֳרָא דְּלָא אָכִיל מִידִי:</p>"],[9520011354,"<p>וַיִּבֶן שָׁם מִזְבֵּחַ וְגו', תָּא חֲזֵי, כְּתִיב וַיִּבֶן שָׁם מִזְבֵּחַ, וְלָא כְּתִיב (בהני מדבחן) דְּאַסִּיק עֲלֵיהּ נִסְכִין וְעֲלָוָון, אֶלָּא בְּגִין דְּאַתְקִין הַהוּא דַרְגָּא דְּאִתְחֲזֵי לְאִתְתַּקְּנָא. מִזְבֵּחַ לַיְיָ, לְאַתְקָנָא דַּרְגָּא תַּתָּאָה לְחַבְּרָא לֵיהּ בְּדַרְגָּא עִלָּאָה, וְעַל דָּא וַיִּבֶן שָׁם מִזְבֵּחַ דָּא דַרְגָּא תַּתָּאָה. לַיְיָ דָּא דַרְגָּא עִלָּאָה. וַיִּקְרָא לַמָּקוֹם אֵל בֵּית אֵל, שְׁמָא דָא כִּשְׁמָא עִלָּאָה. בְּגִין דְּכַד אִתְנַהֲרָא כְּדֵין כְּאִמָּה בִּתָּהּ וְכֹלָּא חַד.</p>\n<p>כִּי שָׁם נִגְלוּ אֵלָיו הָאֱלהִים, בְּגִין דְּאִינוּן לָא אִשְׁתַּכָּחוּ אֶלָּא בִּשְׁכִינְתָּא, דְּהָא שִׁבְעִין הֲווּ דְּאִינוּן מִשְׁתַּכְּחֵי תָּדִיר בַּהֲדֵי שְׁכִינְתָּא, וְשִׁבְעִין קַתַּדְרָאֵי סַחֲרָנִיהּ דִּשְׁכִינְתָּא. וְעַל דָּא כִּי שָׁם נִגְלוּ אֵלָיו הָאֱלֹהִים בְּאַתְרָא דָא דְּאִתְגַּלְּיָא, דְּהָא כְּתִיב וְהִנֵּה יְיָ נִצָּב עָלָיו:</p>"],[9520011355,"<p>וַיַּעַל מֵעָלָיו אֱלֹהִים בַּמָּקוֹם אֲשֶׁר דִּבֶּר אִתּוֹ, רִבִּי שִׁמְעוֹן אָמַר, מִכָּאן דְּאִתְעֲבִיד רְתִיכָא קַדִּישָׁא בַּהֲדֵי אֲבָהָן. וְתָּא חֲזֵי, יַעֲקֹב אִיהוּ רְתִיכָא קַדִּישָׁא עִלָּאָה דְּקַיְימָא לְאַנְהָרָא לְסִיהֲרָא, וְאִיהוּ רְתִיכָא בִּלְחוֹדוֹי. הֲדָא הוּא דִכְתִיב וַיַּעַל מֵעָלָיו אֱלהִים.</p>\n<p>פָּתַח וְאָמַר, (דברים ד׳:ז׳) כִּי מִי גּוֹי גָדוֹל אֲשֶׁר לוֹ אֱלֹהִים קְרוֹבִים אֵלָיו כַּיְיָ אֱלֹהֵינוּ בְּכָל קָרְאֵנוּ אֵלָיו. תָּא חֲזֵי, כַּמָּה אִינוּן חֲבִיבִין יִשְׂרָאֵל קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, דְּלֵית לָךְ עַם וְלִישָׁן בְּכָל עַמִּין עוֹבְדֵי עֲבוֹדָה זָרָה דְּעַלְמָא דְּאִית לֵיהּ אֱלָהָא דְּיִשְׁמַע לוֹן, כְּמָה דְקוּדְשָׁא בְּרִיךְ הוּא זַמִּין לְקַבְּלָא צְלוֹתְהוֹן וּבָעוּתְהוֹן דְּיִשְׂרָאֵל בְּכָל שַׁעְתָּא דְאִצְטְרִיךְ לוֹן לְמִשְׁמַע צְלוֹתָא דְאִינוּן בָּעָאן, בְּגִין הַהוּא דַרְגָּא דִלְּהוֹן.</p>\n<p>תָּא חֲזֵי, יַעֲקֹב, קָרֵי לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, יִשְׂרָאֵל. דִּכְתִיב לא יִקָּרֵא שִׁמְךָ עוֹד יַעֲקֹב כִּי אִם יִשְׂרָאֵל יִהְיֶה שְׁמֶךָ. וַיִּקְרָא אֶת שְׁמוֹ, מַאן וַיִּקְרָא, דָּא שְׁכִינְתָּא. כְּמָה דְאַתְּ אָמֵר וַיִּקְרָא אֶל משֶׁה. וַיֹּאמֶר לוֹ אֱלֹהִים.</p>\n<p>לְעֵיל אוֹקִימְנָא יִשְׂרָאֵל דְּהָא אִשְׁתְּלִּים בְּכֹלָּא כְּדְקָא יְאוּת, וּכְדֵין אִסְתַּלַּק בְּדַרְגֵּיהּ וְאִשְׁתְּלִים בִּשְׁמָא דָא, וְעַל דָּא וַיִּקְרָא אֶת שְׁמוֹ יִשְׂרָאֵל וְהָא אִתְּמָר.</p>"],[9520011356,"<p>רִבִּי אֶלְעָזָר וְרִבִּי יוֹסֵי הֲווּ אָזְלֵי בְּאָרְחָא, אָמַר רִבִּי יוֹסֵי לְרַבִּי אֶלְעָזָר, וַדַּאי הָא דְּאֲמַרְתְּ דְּיַעֲקֹב שְׁלֵימָא דְּאֲבָהָן אִיהוּ, וְאִיהוּ אָחִיד לְכָל סִטְרִין, וְקָרָא שְׁמֵיהּ יִשְׂרָאֵל, וּכְתִיב לא יִקָּרֵא שִׁמְךָ עוֹד יַעֲקֹב כִּי אִם יִשְׂרָאֵל יִהְיֶה שְׁמֶךָ. וּכְתִיב וַיִּקְרָא אֶת שְׁמוֹ יִשְׂרָאֵל. אַמַּאי אַהֲדַר קוּדְשָׁא בְּרִיךְ הוּא וְקָרָא לֵיהּ יַעֲקֹב בְּכַמָּה זִמְנִין, וְכֹלָּא קָרוּן לֵיהּ יַעֲקֹב כְּמִלְּקַדְּמִין. אִי הָכִי, מַהוּ וְלא יִקָּרֵא שִׁמְךָ עוֹד יַעֲקֹב.</p>\n<p>אָמַר לֵיהּ, שַׁפִּיר קָא אֲמַרְתְּ. פָּתַח וְאָמַר, (ישעיהו מ״ב:י״ג) יְיָ כַּגִּבּוֹר יֵצֵא כְּאִישׁ מִלְחָמוֹת יָעִיר קִנְאָה, הַאי קְרָא אוּקְמוּהָ. אֲבָל תָּא חֲזֵי, כַּגִּבּוֹר יֵצֵא, גִּבּוֹר מִבָּעֵי לֵיהּ. כְּאִישׁ מִלְחָמוֹת, אִישׁ מִלְחָמוֹת מִבָּעֵי לֵיהּ.</p>\n<p>אֶלָּא הָא אִתְּמָר יְיָ בְּכָל אֲתַר רַחֲמֵי אִיהוּ, וַדַּאי <Nonei></i>קוּדְשָׁא בְּרִיךְ הוּא, יְיָ שְׁמֵיהּ אִיהוּ, דִּכְתִיב, (ישעיהו מ״ב:ח׳) אֲנִי יְיָ הוּא שְׁמִי, וְחָמִינָן דִּלְזִמְנִין אִתְקְרֵי שְׁמֵיהּ אֱלהִים וְהוּא דִינָא בְּכָל אֲתַר. אֶלָּא בְּזִמְנָא דְאַסְגִיאוּ זַכָּאִין בְּעַלְמָא, יְיָ שְׁמֵיהּ וְאִתְקְרֵי בִּשְׁמָא דְרַחֲמֵי. וּבְזִמְנָא דְאַסְגִיאוּ חַיָּיבִין בְּעַלְמָא, אֱלֹהִים שְׁמֵיהּ וְאִתְקְרֵי בִּשְׁמָא דֵּאֱלהִים. כָּךְ בְּזִמְנָא דְיַעֲקֹב לָא הֲוָה בֵּין שָׂנְאִין וְלָא הֲוָה בְּאַרְעָא אָחֳרָא, קָרֵי לֵיהּ יִשְׂרָאֵל. וְכַד הֲוָה בֵּין שָׂנְאִין, אוֹ בְּאַרְעָא אָחֳרָא קָרֵי לֵיהּ יַעֲקֹב.</p>\n<p>אָמַר לֵיהּ, עֲדַיִין לָא אִתְיַישְׁבָא מִלָּה. דִּכְתִיב לֹא יִקָּרֵא, וְהָא אֲנַן קָרִינָן לֵיהּ. וּמַאי דַאֲמַרְתְּ דְּכַד הֲוָה בֵּין שָׂנְאִין אוֹ בְּאַרְעָא אָחֳרָא קָרֵי לֵיהּ יַעֲקֹב. תָּא חֲזֵי, כְּתִיב, (בראשית ל״ז:א׳) וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו בְּאֶרֶץ כְּנַעַן, וְהָא לָא הֲוָה בְּאַרְעָא אָחֳרָא.</p>\n<p>אָמַר לֵיהּ, הָא בְּקַדְמִיתָא אִתְּמָר, כְּמָה דְקוּדְשָׁא בְּרִיךְ הוּא לְזִמְנִין אִתְקְרֵי יְיָ, וּלְזִמְנִין אִתְקְרֵי אֱלֹהִים. הָכִי נָמֵי לְזִמְנִין אִקְרֵי יִשְׂרָאֵל וּלְזִמְנִין אִקְרֵי יַעֲקֹב וְכֹלָּא בְּדַרְגִּין יְדִיעָן. וּמַה דְּאִתְּמָר לא יִקָּרֵא שִׁמְךָ עוֹד יַעֲקֹב, לְאִתְיַשְּׁבָא בִּשְׁמָא דָא.</p>\n<p>אָמַר לֵיהּ, אִי הָכִי, הָא כְּתִיב, (בראשית י״ז:ה׳) וְלֹא יִקָּרֵא עוֹד אֶת שִׁמְךָ אַבְרָם וְהָיָה שִׁמְךָ אַבְרָהָם. אָמַר לֵיהּ, הָתָם כְּתִיב וְהָיָה. וְעַל דָּא קָיְימָא בְּהַהוּא שְׁמָא. אֲבָל הָכָא לָא כְּתִיב וְהָיָה, אֶלָּא כִּי אִם יִשְׂרָאֵל יִהְיֶה שְׁמֶךָ. וְלָא כְּתִיב וְהָיָה שִׁמְךָ יִשְׂרָאֵל, וְאֲפִילּוּ בְּזִמְנָא חָדָא סַגֵּי לֵיהּ, כָּל שֶׁכֵּן דִּלְזִמְנִין כָּךְ וּלְזִמְנִין כָּךְ. וְכַד אִתְעַטְּרוּ בְּנוֹי בְּכֹהֲנֵי וְלֵיוָאֵי וְאִסְתַּלְּקוּ בְּדַרְגִּין עִלָּאִין, כְּדֵין אִתְעַטַּר בִּשְׁמָא דָא תָּדִיר.</p>"],[9520011357,"<p>עַד דְּהֲווּ אָזְלֵי, אָמַר לֵיהּ רִבִּי יוֹסֵי לְרִבִּי אֶלְעָזָר, הָא אִתְּמָר דְּכַד מִיתַת רָחֵל נָטְלָא בֵּיתָא מַאן דְּאִצְטְרִיךְ לְאִתְתַּקְּנָא בִּתְרֵיסַר שִׁבְטִין כְּדְקָא יְאוּת. אַמַּאי מִיתַת רָחֵל מִיָּד, אָמַר לֵיהּ, הָא לְמֶהֱוֵי שְׁכִינְתָּא מִתְעַטְּרָא כְּדְקָא יְאוּת וּלְמֶהֱוֵי אֵם הַבָּנִים שְׂמֵחָה וּבֵיהּ שַׁרְיָא (לעילא) לְנַטְלָא בֵּיתָא וּלְאִתְתַּקָּנָא. וְעַל דָּא בִּנְיָמִין הוּא תָּדִיר בְּמַעֲרָב וְלָא בְסִטְרָא אָחֳרָא.</p>\n<p>וּבֵיהּ שַׁרְיָא לְאִתְתַּקְּנָא בִּתְרֵיסַר שִׁבְטִין, וּבֵיהּ שַׁרְיָא מַלְכוּתָא דִרְקִיעָא לְאִשְׁתְּמוֹדְעָא בְּאַרְעָא. וְרָזָא דָּא, בְּכָל שֵׁירוּתָא דְּאַתְיָא לְאִשְׁתְּמוֹדְעָא בְּקַשְׁיוּ אִיהוּ, וְעַל דָּא אִית בָּהּ דִּינָא דְמוֹתָא וּמִתַּמָּן אִתְיַשְּׁבַת.</p>\n<p>הָכָא כַּד בָּעָא לְאִתְתַּקְּנָא וּלְנַטְלָא בֵּיתָא אִתְעֲבִיד דִּינָא בְּרָחֵל וּבָתַר כֵּן אִתְתַּקְּנַת לְאִתְיַשְּׁבָא. כַּד בָּעָא לְאִשְׁתְּמוֹדְעָא מַלְכוּתָא בְּאַרְעָא שַׁרְיָא בְּדִינָא. וְלָא אִתְיַשְּׁבַת מַלְכוּתָא בְּדוּכְתָא כְּדְקָא יְאוּת עַד דְּאִתְעַר דִּינָא בִּשָׁאוּל לְפוּם עוֹבָדוֹי, וּלְבָתַר אִתְיַשְּׁבַת מַלְכוּתָא וְאִתְתַּקְּנַת.</p>\n<p>תָּא חֲזֵי, כָּל שֵׁירוּתָא תַּקִּיף וּלְבָתַר נַיְיחָא. בְּרֹאשׁ הַשָּׁנָה שֵׁירוּתָא תַּקִּיף. דְּכָל עַלְמָא אִתְדָּן כָּל חַד וְחַד לְפוּם עוֹבָדוֹי, וּלְבָתַר נַיְיחָא סְלִיחָה וְכִפּוּרֵי. בְּגִין דְּשֵׁירוּתָא אִיהוּ מִשְׂמָאלָא וְעַל דָּא דִּינוֹי תַּקִּיפִין, וּלְבָתַר אִתְעַר יָמִינָא וְעַל דָּא הֲוֵי נַיְיחָא.</p>\n<p>וּלְזִמְנָא דְאָתֵי זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְאִתְעָרָא בְּנַיְיחָא עַל שְׁאָר עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, וּלְבָתַר יִתְתַּקַּף עֲלַיְיהוּ בְּדִינָא קַשְׁיָא. הֲדָא הוּא דִכְתִיב, (ישעיהו מ״ב:י״ג) יְיָ כַּגִּבּוֹר יֵצֵא כְּאִישׁ מִלְחָמוֹת יָעִיר קִנְאָה יָרִיעַ אַף יַצְרִיחַ עַל אוֹיְבָיו יִתְגַּבָּר. יְיָ בְּקַדְמִיתָא דְּאִיהוּ רַחֲמֵי, וּלְבָתַר כַּגִּבּוֹר וְלָא גִבּוֹר. וּלְבָתַר כְּאִישׁ מִלְחָמוֹת וְלֹא אִישׁ מִלְחָמוֹת. לְבָתַר אִתְגְּלִי תּוּקְפָא עֲלַיְיהוּ וְיִתְתַּקַּף לְשֵׁיצָאָה לוֹן, דִּכְתִיב יָרִיעַ אַף יַצְרִיחַ עַל אוֹיְבָיו יִתְגַּבָּר. וּכְתִיב, (זכריה י״ד:ג׳) וְיָצָא יְיָ וְנִלְחַם בַּגּוֹיִם הָהֵם כְּיוֹם הִלָּחֲמוֹ בְּיוֹם קְרָב. וּכְתִיב, (ישעיהו ס״ג:א׳) מִי זֶה בָּא מֶאֱדוֹם חֲמוּץ בְּגָדִים מִבָּצְרָה וְגו':</p>\n<p>וַיְהִי בְּצֵאת נַפְשָׁהּ כִּי מֵתָה וַתִּקְרָא שְׁמוֹ בֶּן אוֹנִי וְאָבִיו קָרָא לוֹ בִּנְיָמִן. רִבִּי יְהוּדָה פָּתַח וְאָמַר, (נחום א׳:ז׳) טוֹב יְיָ לְמָעוֹז בְּיוֹם צָרָה וְיֹדֵעַ חֹסֵי בוֹ. זַכָּאָה חוּלָקֵיהּ דְּבַר נָשׁ דְּאִתְתַּקַּף בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין דְּתוּקְפָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִיהוּ תּוּקְפָא, וְאוּקְמוּהָ טוֹב יְיָ, כְּמָה דְאַתְּ אָמֵר (תהילים קמ״ה:ט׳) טוֹב יְיָ לַכֹּל. לְמָעוֹז, דָּא הוּא תּוּקְפָא דְּאִית בֵּיהּ יְשׁוּעוֹת. דִּכְתִיב, (תהילים כ״ח:ח׳) וּמָעוֹז <Nonei></i>יְשׁוּעוֹת מְשִׁיחוֹ הוּא. בְּיוֹם צָרָה, בְּיוֹמָא דְעָקוּ דְּעָקִין שְׁאָר עַמִּין לְיִשְׂרָאֵל.</p>"],[9520011358,"<p>תָּא חֲזֵי, מַה כְּתִיב (משלי כ״ד:י׳) הִתְרַפִּיתָ בְּיוֹם צָרָה צַר כֹּחֶכָה. מַאי הִתְרַפִּיתָ. מַאן דְּאִתְרַפֵּי יְדוֹי מִקוּדְשָׁא בְּרִיךְ הוּא דְּלָא לְאִתְתַּקְּפָא בֵּיהּ. וְהֵיךְ יִתְקַף בַר נָשׁ בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, יַתְקִיף בְּאוֹרַיְיתָא. דְּכָל מַאן דְּאִתְתַּקַּף בְּאוֹרַיְיתָא, אִתְתַּקַּף בְּאִילָנָא דְחַיֵּי. כִּבְיָכוֹל יָהַב תּוּקְפָא לִכְנֶסֶת יִשְׂרָאֵל לְאִתְתַּקְפָא.</p>\n<p>וְאִי הוּא יִתְרַפֵּי מֵאוֹרַיְיתָא, מַה כְּתִיב הִתְרַפִּיתָ. אִי אִיהוּ אִתְרַפֵּי מִן אוֹרַיְיתָא בְּיוֹם צָרָה צַר כֹּחֶכָה, בְּיוֹמָא דְיֵיתֵי לֵיהּ עָקוּ, כִּבְיָכוֹל דָּחִיק לָהּ לִשְׁכִינְתָּא דְּאִיהוּ חֵילָא דְעַלְמָא.</p>\n<p>דָבָר אַחֵר צַר כֹּחֶכָה, תָּא חֲזֵי, בְּשַׁעְתָּא דְבַר נָשׁ אִתְרַפֵּי מֵאוֹרַיְיתָא וְאָזִיל בְּאָרְחָא דְלָא כַשְׁרָא, כַּמָּה בַּעֲלֵי דְבָבוּ זְמִינִין לֵיהּ לִמֶהֱוֵי לֵיהּ קַטֵּיגוֹרִין בְּיוֹמָא דְעָקוּ. וְאֲפִילּוּ נִשְׁמָתֵיהּ דְּבַר נָשׁ דְּאִיהוּ חֵילָא וְתוּקְפָא דִילֵיהּ אִיהוּ מָארֵי דְבָבוּ לְקֳבְלֵיהּ, דִּכְתִיב צַר כֹּחֶכָה, בְּגִין דְּאִיהוּ צַר לְגַבֵּיהּ. אָמַר רִבִּי אַבָּא בְּשַׁעְתָּא דְבַר נָשׁ אָזִיל בְּאָרְחֵי דְאוֹרַיְיתָא וְכָל אָרְחוֹי מִתְתַּקְּנָן כְּדְקָא יְאוּת, כַּמָּה סָנֵיגוֹרִין קָיְימִין עֲלֵיהּ לְאַדְכָּרָא לֵיהּ לְטַב.</p>\n<p>פָּתַח וְאָמַר, (איוב ל״ג:כ״ג-כ״ד) אִם יֵשׁ עָלָיו מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף לְהַגִּיד לְאָדָם יָשְׁרוֹ וַיְחֻנְּנּוּ וַיֹּאמֶר פְּדָעֵהוּ מֵרֶדֶת שַׁחַת מָצָאתִי כֹפֶר. הַנֵּי קְרָאֵי אִית לְאִסְתַּכָּלָא בְּהוּ, וְכִי לָא אִתְגְּלִי כֹּלָּא קַמֵי קוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהוּ צָרִיךְ לְמַלְאכָא דְּיֵימָא קַמֵּיהּ טַב אוֹ בִישׁ.</p>\n<p>אֶלָּא וַדַּאי אִצְטְרִיךְ. דְּכַד אִית לֵיהּ לְבַר נָשׁ סַנֵּיגוֹרִין לְאַדְכָּרָא זְכוּ דִידֵיהּ קַמֵּיהּ, וְלָא אִית לֵיהּ (לבר נש) קַטֵּיגוֹרִין, כְּדֵין וַיְחֻנְּנּוּ וַיֹּאמֶר פְּדָעֵהוּ מֵרֶדֶת שַׁחַת מָצָאתִי כֹפֶר.</p>\n<p>תָּא חֲזֵי, בְּהַאי קְרָא תִּשְׁכַּח בְּרִירָא דְמִלָּה, כְּתִיב אִם יֵשׁ עָלָיו מַלְאָךְ, אִי לָא כְּתִיב יַתִּיר יָאוֹת הוּא. אֲבָל מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף כְּתִיב, וּמַאן אִיהוּ. דָּא הוּא מַלְאָךְ דִּמְמַנָּא עִמֵּיהּ דְּבַר נָשׁ בִּסְטַר שְׂמָאלָא, דִּכְתִיב, (תהילים צ״א:ז׳) יִפֹּל מִצִּדְךָ אֶלֶף, וְדָא הוּא סִטְרָא דִשְׂמָאלָא, דִּכְתִיב בַּתְרֵיהּ וּרְבָבָה מִימִינֶךָ.</p>\n<p>אֲבָל אֶחָד מִנִּי אֶלֶף, דָּא הוּא יֵצֶר הָרָע, דְּאִיהוּ אֶחָד מֵאִנּוּן (דאיהו) אֶלֶף דְּהֲווּ לִסְטַר שְׂמָאלָא. בְּגִין דְּאִיהוּ סָלִיק לְעֵילָא וְנָטִיל רְשׁוּ. וְעַל דָּא אִי בַר נָשׁ אָזִיל בְּאֹרַח קְשׁוֹט, הַהוּא יֵצֶר הָרָע אִיהוּ עֶבֶד לוֹ. כְּמָה דְאִתְּמָר דִּכְתִיב, (משלי י״ב:ט׳) טוֹב נִקְלֶה וְעֶבֶד לוֹ. כְּדֵין אִיהוּ סָלִיק וְאִתְעֲבִיד סַנֵּיגוֹרָא, וְאָמַר קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, זְכוּ עֲלֵיהּ דְּבַר נָשׁ. כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא אָמַר, פְּדָעֵהוּ מֵרֶדֶת שָׁחַת.</p>\n<p>וְעִם כָּל דָּא לָא אַהֲדַר בְּרֵיקַנְיָא, בְּגִין דְּאִתְיְהִיב לֵיהּ אָחֳרָא לְשַׁלְטָאָה עֲלוֹי וְלִיטּוֹל נִשְׁמָתֵיהּ מִנֵּיהּ. בְּגִין דְּאַקְדִּים חוֹבוֹי דְּהַהוּא בַּר נָשׁ וְאִיהוּ כֹּפֶר עַל הַאי. הֲדָא הוּא דִכְתִיב מָצָאתִי כֹּפֶר, לְמִפְדֵי לֵיהּ.</p>\n<p>דָבָר אַחֵר מָצָאתִי כֹפֶר. הַהוּא זְכוּ דְּאֲמַרְתְּ אִיהוּ עֲלֵיהּ כֹּפֶר לְמִפְדֵי לֵיהּ דְּלָא יֵחוֹת לַגֵּיהִנֹּם וְלָא יְמוּת. וְעַל דָּא מִבָּעֵי לֵיהּ לְבַר נָשׁ לְמֵיהַךְ בְּאֹרַח קְשׁוֹט וּבְגִין דִּיְהֵא לֵיהּ הַהוּא קַטֵּיגוֹרָא, סַנֵּיגוֹרָא.</p>\n<p>כְּגַוְונָא דָא יִשְׂרָאֵל בְּיוֹמָא דְכִפּוּרֵי, דְּיַהֲבֵי לֵיהּ שָׂעִיר וְאִתְעַסִּיקוּ בַּהֲדֵיהּ. עַד דְּאִתְהֲדַר עֶבֶד לְהוּ וְסָלִיק וְסָהִיד סַהֲדוּתָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וְאִתְעֲבִיד לְהוּ סַנֵּיגוֹרָא. וְעַל דָּא אָמַר שְׁלמֹה, (משלי כ״ה:כ״א) אִם רָעֵב שׂנַאֲךָ הַאֲכִילֵהוּ לֶחֶם וְאִם צָמֵא הַשְׁקֵהוּ מַיִם. וְעַל הַאי יֵצֶר הָרָע אִתְּמָר.</p>\n<p>וּבְגִין דָּא בְּיוֹם צָרָה, כַּד בַר נָשׁ אִתְרַפֵּי מֵאוֹרַיְיתָא, כִּבְיָכוֹל דָּחִיק לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא בַּהֲדֵיהּ דְּהַהוּא יֵצֶר הָרָע דְּאִיהוּ אִתְעֲבִיד קַטֵּיגוֹרָא. צַר כֹּחֶכָה. צַר כֹּחַ כֹּ\"ה, בְּגִין דְּאִתְקָרֵב קַמֵּיהּ לְקַטְרְגָא וְאִתְחַלַּשׁ חֵילָא.</p>\n<p>תָּא חֲזֵי, טוֹב יְיָ לְמָעוֹז בְּיוֹם צָרָה, מַאי בְּיוֹם צָרָה. דָּא יַעֲקֹב כַּד אֲתָא עֲלֵיהּ עֵשָׂו לְקַטְרְגָא לֵיהּ. וְיוֹדֵעַ חוֹסֵי בוֹ, כַּד אֲתָא עֲלֵיהּ עָקוּ דְדִינָא. וְתָּא חֲזֵי, לֵית מְקַטְרְגָא אִשְׁתַּכַּח עֲלֵיהּ דְּבַר נָשׁ אֶלָּא בְּזִמְנָא דְסַכָּנָה.</p>\n<p>וְתָּא חֲזֵי, בְּגִין דְּיַעֲקֹב אַחַר נִדְרֵיהּ דְּנָדִיר קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, אִתְתַּקַּף דִּינָא עַל יְדָא דִּמְקַטְרְגָא דְּקַטְרִיג עֲלֵיהּ דְּיַעֲקֹב, <Nonei></i>וּבָעָא דִינָא בְּשַׁעְתָּא דְסַכָּנָה דְּהֲוַת רָחֵל בָּהּ. אָמַר קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְהָא יַעֲקֹב נָדַר נִדְרֵיהּ וְלָא שָׁלִים, וְהָא אִיהוּ תַּקִּיף מִכֹּלָּא בְּעוּתְרָא וּבִבְנִין בְּכָל מַה דְּאִצְטְרִיךְ. וְלָא שָׁלִים נִדְרֵיהּ דְּנָדַר קַמָּךְ וְלָא נָסַבְתְּ עוֹנָשָׁא מִנֵּיהּ. מִיָּד וַתֵּלֶד רָחֵל וַתְּקַשׁ בְּלִדְתָּהּ. מַאי וַתְּקַשׁ. דְּאִתְקַשֵּׁי דִינָא לְעֵילָא גַּבֵּי מַלְאַךְ הַמָּוֶת.</p>\n<p>וְאִתְעַנַּשׁ יַעֲקֹב בְּהַאי. מַאי טַעְמָא, בְּגִין דִּכְתִיב (משלי כ״ב:כ״ז) וְאִם אֵין לְךָ לְשַׁלֵּם לָמָּה יִקַּח מִשְׁכָּבְךָ מִתַּחְתֶּיךָ. וְעַל דָּא מִיתַת רָחֵל וְאִתְמָסַר דִּינָא עַל יְדָא דְּמַלְאַךְ הַמָּוֶת.</p>\n<p>וְתָּא חֲזֵי, בְּשַׁעְתָּא דְּאֲתָא עֵשָׂו, מָה עֲבַד. וַיָּשֶׂם אֶת הַשְּׁפָחוֹת וְאֶת יַלְדֵיהֶן רִאשׁוֹנָה וְאֶת לֵאָה וִילָדֶיהָ אַחֲרוֹנִים וְאֶת רָחֵל וְאֶת יוֹסֵף אַחֲרוֹנִים. מַאי טַעְמָא, בְּגִין דְּדָחִיל עֲלָה דְרָחֵל, דְּלָא יִסְתַּכַּל הַהוּא רָשָׁע בְּשַׁפִּירוּ דִילָהּ וְלָא יְקַטְרֵג לֵיהּ עֲלָהּ.</p>\n<p>תוּ מַה כְּתִיב, וַתִּגַּשְׁנָה הַשְׁפָחוֹת הֵנָּה וְיַלְדֵיהֶן וַתִּשְׁתַּחֲוֶיןָ וַתִּגַּשׁ גַּם לֵאָה וִילָדֶיהָ וַיִּשְׁתַּחֲווּ, נָשִׁין מִקַּמֵּי גוּבְרִין. אֲבָל בְּרָחֵל מַה כְּתִיב וְאַחַר נִגַּשׁ יוֹסֵף וְרָחֵל, וְיוֹסֵף מִקַּמֵי אִמֵּיהּ וְאִיהוּ חָפָּא עֲלָהּ, וְעַל דָּא כְּתִיב, (בראשית מ״ט:כ״ב) בֶּן פּוֹרָת יוֹסֵף בֶּן פּוֹרָת עֲלֵי עָיִן. דְּאַסְגֵי גוּפֵיהּ וְחָפָּא עַל אִמֵּיהּ. עֲלֵי עָיִן, עֲלֵי עֵינָא דְהַהוּא רָשָׁע.</p>\n<p>וְהָכָא אִתְעֲנָשַׁת עַל יְדָא דְּיֵצֶר הָרָע דְּקִטְרֵג בְּשַׁעְתָּא דְסַכָּנָה, וְאִתְעַנַּשׁ יַעֲקֹב עַל נִדְרָא דְּלָא שָׁלִים, וְדָא קַשְׁיָא לֵיהּ לְיַעֲקֹב מִכָּל עָקוּ דַּעֲבְרוּ עֲלֵיהּ. וּמְנָלָן דִּבְגִינֵיהּ דְּיַעֲקֹב הֲוָה, דִּכְתִיב, (בראשית מ״ח:ז׳) מֵתָה עָלַי רָחֵל. עָלַי וַדַּאי, עַל דְּאֲחָרִית נִדְרִי.</p>\n<p>רִבִּי יוֹסֵי אָמַר, כְּתִיב, (משלי כז) קִלְּלַת חִנָּם לֹא תָבֹא. וְאוּקְמוּהָ לוֹ בְּוי\"ו, דְּאִי קִלְּלַת צַדִּיקָא הִיא, אֲפִילּוּ דְּלָא אִתְכַּוַּן בָּהּ, כֵּיוָן דְּנָפְקָא מִפּוּמֵיהּ נָטַל לָהּ הַהוּא יֵצֶר הָרָע וְקִטְרֵג בָּהּ בְּשַׁעְתָּא דְסַכָּנָה.</p>\n<p>יַעֲקֹב אָמַר, (בראשית ל״א:ל״ב) עִם אֲשֶׁר תִּמְצָא אֶת אֱלֹהֶיךָ לא יִחְיֶה. וְאַף עַל גַּב דְּאִיהוּ לָא הֲוָה יָדַע, נָטִיל לָהּ לְהַהִיא מִלָּה הַהוּא שָׂטָן דְּאִשְׁתַּכַּח גַּבַּיְיהוּ תָּדִיר בִּבְנִי נָשָׁא. וְעַל דָּא תָּנִינָן, לְעוֹלָם לֹא יִפְתַּח בַּר נָשׁ פּוּמֵיהּ לְשִׂטְנָא, בְּגִין דְּנָטִיל הַהִיא מִלָּה וְקִטְרֵג בָּהּ לְעֵילָא וְתַתָּא. כָּל שֶׁכֵּן מִלָּה דְחָכָם אוֹ מִלָּה דְצַדִּיקָא, וְעַל תְּרֵין אִלֵּין אִתְעֲנָשַׁת רָחֵל:</p>"],[9520011359,"<p>וַיְהִי (קנהב) בְּצֵאת נַפְשָׁהּ כִּי מֵתָה. אָמַר רִבִּי אַבָּא וְכִי כֵּיוָן דְּאָמַר וַיְהִי בְּצֵאת נַפְשָׁהּ לָא יְדַעְנָא כִּי מֵתָה. אֶלָא אִצְטְרִיךְ בְּגִין דְּלָא אַהֲדָרַת לְגוּפָא יַתִּיר, וּמִיתַת רָחֵל מִיתַת גּוּפָא, בְּגִין דְּאִית בְּנִי נָשָׁא דְּנָפְקֵי נִשְׁמָתַיְיהוּ וְאַהַדְרָן לְאַתְרַיְיהוּ וּכְּמָה דְאַתְּ אָמֵר, (שמואל א ל) וַתָּשָׁב נַפְשׁוֹ (לפנינו בקרא רוחו. ובדפוס ירושלים איתא גם בזוה\"ק ותשב רוחו אליו) אֵלָיו, (בראשית מ״ב:כ״ח) וַיֵּצֵא לִבָּם, (שיר השירים ה׳:ו׳) נַפְשִׁי יָצְאָה בְּדַבְּרוֹ. (מלכים א י״ז:י״ז) לא נוֹתְרָה בּוֹ נְשָׁמָה. אֲבָל הַאי נָפְקַת נִשְׁמָתָהּ וְלָא אִתְהַדָּרַת לְאַתְרָהּ וּמִיתַת רָחֵל.</p>\n<p>וַתִּקְרָא שְׁמוֹ בֶּן אוֹנִי. דְּקַשְׁיוּ דְדִינָא דְּאִתְגְּזַר עֲלָהּ. וְיַעֲקֹב אַהֲדַר לֵיהּ וְקָשִׁיר לֵיהּ לְימִינָא, בְּגִין דְּמַעֲרָב אִצְטְרִיךְ לְקָשְׁרָא לֵיהּ לִימִינָא, וְאַף עַל גַּב דְּאִיהוּ בֶּן אוֹנִי סִטְרָא דְדִינָא קַשְׁיָא, בֶּן יָמִין אִיהוּ, דְּהָא בִּימִינָא אִתְקַשְּׁרַת.</p>\n<p>וְאִתְקְבָרַת בְּאָרְחָא כְּמָה דְאִתְּמָר. הַאי אִתְגַּלְּיָא מִיתָתָהּ וּקְבוּרָתָהּ, אֲבָל לֵאָה לָא אִתְגַּלְּיָא מִיתָתָהּ וּקְבוּרָתָהּ. וְאַף עַל גַּב דְּהַנֵּי אַרְבַּע אִמָּהָן רָזָא אִית לוֹן וְהָא אוּקְמוּהָ:</p>"],[9520011360,"<p>וַיַּצֶּב יַעֲקֹב מַצֵּבָה עַל קְבוּרָתָהּ, אָמַר רִבִּי יוֹסֵי, מַאי טַעְמָא. בְּגִין דְּלָא אִתְכַּסְיָא אַתְרָהּ עַד יוֹמָא דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לַאֲחָיָיא מֵתַיָיא. כְּמָה דְאִתְּמָר עַד הַיּוֹם, עַד הַהוּא יוֹמָא מַמָּשׁ.</p>\n<p>רִבִּי יְהוּדָה אָמַר, עַד יוֹמָא דְּתֵהְדַר שְׁכִינְתָּא בְּגָלוּתְהוֹן דְּיִשְׂרָאֵל בְּהַהוּא אֲתַר, כְּמָה דְאַתְּ אָמֵר, (ירמיהו ל״א:י״ז) וְיֵשׁ תִּק2וה לְאַחֲרִיתֵךְ נְאֻם יְיָ וְשָׁבוּ בָנִים לִגְבוּלָם. וְדָא אוֹמָאָה דְּאוֹמֵי לָהּ קוּדְשָׁא בְּרִיךְ הוּא. וּזְמִינִין יִשְׂרָאֵל כַּד יְתוּבוּן מִן גָּלוּתָא, לְקָיְימָא עַל הַהִיא קְבוּרָה דְרָחֵל וּלְמִבְכֵּי תַּמָּן. כְּמָה דְאִיהִי בָּכַאת עַל גָּלוּתְהוֹן דְּיִשְׂרָאֵל. וְעַל דָּא כְּתִיב, (ירמיהו ל״א:ט׳) בִּבְכִי יָבֹאוּ וּבְתַחֲנוּנִים אוֹבִילֵם וְגו'. וּכְתִיב, (ירמיהו ל״א:ט׳) כִּי יֵשׁ שָׂכָר לִפְעוּלָתֵךְ. וּבְהַהִיא <Nonei></i>שַׁעְתָּא זְמִינַת רָחֵל דְּאִיהִי בְאָרְחָא לְמֶחֱדֵי בְּהוּ בְּיִשְׂרָאֵל וְעִם שְׁכִינְתָּא וְאוּקְמוּהָ חַבְרַיָּיא:</p>"],[9520011361,"<p>וַיְהִי בִּשְׁכֹּן יִשְׂרָאֵל בָּאָרֶץ הַהִיא וַיֵּלֶךְ רְאוּבֵן וַיִּשְׁכַּב אֶת בִּלְהָה פִּלֶּגֶשׁ אָבִיו וַיִּשְׁמַע יִשְׂרָאֵל וַיִּהְיוּ בְּנֵי יַעֲקֹב שְׁנֵים עָשָׂר. רִבִּי אֶלְעָזָר אָמַר, וַיְהִי בִּשְׁכֹּן יִשְׂרָאֵל בָּאָרֶץ הַהִיא, דְּהָא לֵאָה וְרָחֵל מִיתוּ, וְנָטְלָא בֵּיתָא מַאן דְּנָטִיל.</p>\n<p>וְכִי סַלְקָא דַעְתָּךְ דִּרְאוּבֵן אָזִיל וְשָׁכִיב בַּהֲדָהּ דְּבִלְהָה. אֶלָּא, כָּל יוֹמָא דְּלֵאָה וְרָחֵל שְׁכִינְתָּא שַׁרְיָיא עֲלַיְיהוּ. וְהַשְׁתָּא דְמִיתוּ, שְׁכִינְתָּא לָא אִתְפְּרָשַׁת מִן בֵּיתָא, וְשַׁרְיָא בְּבֵיתָא בְּמִשְׁכְּנָא דְבִלְהָה. וְאַף עַל גַּב דִּשְׁכִינְתָא בַּעְיָא לְנַטְלָא בֵּיתָא כְּדְקָא יָאוֹת, אִלְמָלֵא יַעֲקֹב לָא אִשְׁתַּכַּח בְּזִוּוּגָא דְּכַר וְנוּקְבָא, לָא שַׁרְיָא שְׁכִינְתָּא בְּאִתְגַּלְּיָא בְּבֵיתָא. וְעַל דָּא קָיְימָא שְׁכִינְתָּא בְּמַשְׁכְּנָא דְבִלְהָה. וְאָתָא רְאוּבֵן וּבְגִין דְּחָמָא דְבִלְהָה יָרְתָא אַתְרָא דְאִמֵּיהּ, אֲזַל וּבִלְבֵּל עַרְסָא. וְעַל דְּקָיְימָא שְׁכִינְתָּא עֲלָהּ, כְּתִיב בֵּיהּ וַיִּשְׁכַּב אֶת בִּלְהָה.</p>\n<p>רַבִּי יֵיסָא אָמַר, דְּנָאִים עַל הַהוּא עַרְסָא וְלָא חַיִּישׁ לִיקָרָא דִשְׁכִינְתָּא. וּבְגִין כָּךְ לָא אִתְפְּגִים מֵחוּשְׁבָּנָא דְשִׁבְטִין וְאָתָא קְרָא וְעֲבִיד חוּשְׁבְּנָא. בְּגִין כָּךְ כְּתִיב, בְּכוֹר יַעֲקֹב רְאוּבֵן. וְאִיהוּ עָבִיד קְרָא רֵישָׁא דְּכָל שִׁבְטִין.</p>\n<p>רַבִּי יְהוּדָה פָּתַח וְאָמַר, (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי יְיָ וְגו', כָּל אָרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא כֻּלְּהוּ יְשָׁרִים וְאָרְחוֹי קְשׁוֹט, וּבְנִי עַלְמָא לָא יָדְעִין וְלָא מַשְׁגִּיחִין עַל מַה אִינוּן קָיְימִין. וְעַל דָּא וְצַדִּיקִים יֵלְכוּ בָם, בְּגִין דְּאִינוּן יָדְעִין אָרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא וּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא. דְּכָל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא, אִיהוּ יָדַע וְאָזִיל בְּהוּ דְּלָא סָטֵי לִימִינָא וְלִשְׂמָאלָא.</p>\n<p>וּפוֹשְׁעִים יִכָּשְׁלוּ בָם, אִלֵּין אִינוּן חַיָּיבִין דְּלָא מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, וְלָא מִסְתַּכְּלָן בְּאָרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא וְלָא יָדְעִין לְאָן אוֹרְחֵי אָזְלִין. וּבְגִין דְּלָא יָדְעֵי לְאִסְתַּכְּלָא וְלא מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא, אִינוּן כָּשְׁלֵי בְּהוּ בְּאִינוּן אָרְחוֹי בְּהַאי עַלְמָא וּבְעַלְמָא דְאָתֵי.</p>\n<p>תָּא חֲזֵי, כָּל בַּר נָשׁ דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא, כַּד נָפִיק מֵהַאי עַלְמָא נִשְׁמָתֵיהּ סָלְקָא בְּאִינוּן אָרְחִין וּשְׁבִילִין (דאינון באורייתא) דְּאוֹרַיְיתָא. וְאִינוּן אָרְחִין וּשְׁבִילִין דְּאוֹרַיְיתָא יְדִיעָן אִינוּן, וְאִינוּן דְּיָדְעֵי אָרְחוֹי דְאוֹרַיְיתָא בְּהַאי עַלְמָא יַהֲכוּן בְּהוּ בְּהַהוּא עַלְמָא כַּד יִפְקוּן מֵהַאי עַלְמָא.</p>\n<p>וְאִי לָא אִשְׁתַּדָּלוּ בְּאוֹרַיְיתָא בְּהַאי עַלְמָא וְלָא יָדְעִין אָרְחִין וּשְׁבִילִין, כַּד יִפְקוּן מֵהַאי עַלְמָא לָא יִנְדְּעוּן לְמֵיהַךְ בְּאִינוּן אָרְחִין וּשְׁבִילִין וְכָשְׁלִין בְּהוֹן. כְּדֵין יְהַךְ בְּאָרְחִין אָחֳרָנִין דְּלָאו אִינוּן אָרְחִין דְּאוֹרַיְיתָא, וְיִתְעָרוּן לֵיהּ בְּכַמָּה דִינִין וְאִתְעַנַּשׁ בְּהוּ.</p>\n<p>וּמַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא מַה כְּתִיב, (משלי ו׳:כ״ב) בְּשָׁכְבְּךָ תִּשְׁמֹר עָלֶיךָ וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךָ. בְּשָׁכְבְּךָ בְּקִבְרָא, אוֹרַיְיתָא תִּצּוֹר עָלֶיךָ מִדִּינָא דְּהַהוּא עָלְמָא. וְהֱקִיצוֹתָ, כַּד קוּדְשָׁא בְּרִיךְ הוּא יִתְעַר רוּחִין וְנִשְׁמָתִין לְאַחַיָּיא מֵתַיָיא כְּדֵין הִיא תְּשִׂיחֶךָ, הִיא תְּהֵא סַנֵּיגוֹרְיָא עַל גּוּפָא, בְּגִין דִּיקוּמוּן אִינוּן גּוּפִין דְּאִשְׁתַּדְּלוּ בְאוֹרַיְיתָא כִּדְּקָא יָאוֹת. וְאִלֵּין אִינוּן דִּיקוּמוּן בְּקַדְמִיתָא לְחַיֵּי עָלְמָא, כְּמָה דְאַתְּ אָמֵר, (דניאל י״ב:ב׳) וְרַבִּים מִישֵׁנִי אַדְמַת עָפָר יָקִיצוּ אֵלֶּה לְחַיֵּי עוֹלָם וְגו'. וְאִלֵּין אִינוּן לְחַיֵּי עוֹלָם, בְּגִין דְּאִתְעַסְּקוּ בְּחַיֵּי עוֹלָם דְּאִיהִי אוֹרַיְיתָא.</p>\n<p>וְתָּא חֲזֵי, כָּל אִינוּן דְּאִשְׁתַּדְּלוּ בְּאוֹרַיְיתָא, הַהוּא גּוּפָא יִתְקַיַּים וְאוֹרַיְיתָא תָּגִין עֲלֵיהּ. מַאי טַעְמָא, בְּגִין דִּבְהַהִיא שַׁעְתָּא יִתְעַר קוּדְשָׁא בְּרִיךְ הוּא חַד רוּחָא דְּכָלִיל מֵאַרְבַּע רוּחִין, וְהַהוּא רוּחָא דְּכָלִיל מֵאַרְבַּע רוּחִין, אִזְדַּמַּן לְכָל אִינוּן דְּאִשְׁתַּדְּלוּ בְּאוֹרַיְיתָא לַאֲחָיָיא לוֹן בְּהַאי רוּחָא בְּגִין דְּיִתְקַיַים לְעָלְמִין.</p>\n<p>וְאִי תֵימָא, הָא כְּתִיב (יחזקאל ל״ז:ט׳) מֵאַרְבַּע רוּחוֹת בֹּאִי הָרוּחַ, אַמַּאי לָא אִתְקַיְימוּ, דְּהָא כֻּלְּהוּ מִיתוּ כְּמִלְּקַדְמִין. תָּא חֲזֵי, הַהוּא זִמְנָא דְּאוֹקִים קוּדְשָׁא בְּרִיךְ הוּא עַל יְדָא דִיחֶזְקֵאל אִינוּן מֵתַיָיא, הַהוּא (זמני דאתא) רוּחָא אַף עַל גַּב דְּהֲוָה מֵאַרְבַּע רוּחַיָּיא, לָא נָחִית לְקָיְימָא לוֹן בְּקִיּוּמָא, אֶלָּא לְאַחֲזָאָה דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לַאֲחָיָיא מֵתַיָיא בְּהַהוּא גַוְונָא וּלְקַיְימָא לוֹן בְּרוּחָא <Nonei></i>דְּאִתְכְּלִיל בְּהַאי גַוְונָא. וְאַף עַל גַּב דְּאַהֲדָרוּ גַּרְמִין בְּהַהִיא שַׁעְתָּא כְּמָה דְהֲוָה. קוּדְשָׁא בְּרִיךְ הוּא בָּעָא לְאַחֲזָאָה לְכָל עַלְמָא דְּאִיהוּ זַמִּין לַאֲחָיָיא מֵתַיָיא (מה כתיב, (ישעיהו כ״ו:י״ט) יחיו מתיך נבלתי יקומון. על דא ההוא רוחא דזמין לנחתא בהו בצדיקיא) (נ\"א ועל דא ההוא רוחא דזמין לנחתא בהו בצדיקיא. מה כתיב מארבע רוחות באי הרוח, רוחא דאתכלילת בארבע), בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא זַמִּין לְקַיְימָא לְהוּ קִיּוּמָא שְׁלִים בְּעַלְמָא כְּדְקָא יְאוּת. וְאִינוּן דְּאִשְׁתַּדְּלוּ בְּאוֹרַיְיתָא בְּהַאי עַלְמָא, הִיא קָיְימָא עֲלֵיהּ דְּבַר נָשׁ וְאִתְעֲבִידַת סַנִּיגוֹרְיָא קַמֵּי דְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, כָּל אִינוּן מִלִּין דְּאוֹרַיְיתָא וְכָל הַהִיא אוֹרַיְיתָא דְּאִשְׁתַּדַּל בָּהּ בַּר נָשׁ בְּהַאי עָלְמָא, אִינוּן מִלִּין וְהַהִיא אוֹרַיְיתָא קָיְימָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וַאֲמָרַת קַמֵיהּ וְהִיא אֲרִימַת קָלִין וְלָא אִשְׁתַּכָּכַת. וּלְהַהוּא זִמְנָא אִיהִי תָשִׂיחַ וְתֵימָא כְּפוּם דְאִתְדָּבַּק בַּר נָשׁ וְאִשְׁתְּדָּל בְּהַאי עַלְמָא, וְעַל דָּא אִינוּן יְקוּמוּן בְּקִיּוּמָא שְׁלִים לְחַיֵּי עַלְמָא כְּדְקָאֲמָרָן. וּבְגִין כָּךְ (הושע י״ד:י׳) כִּי יְשָׁרִים דַּרְכֵי יְיָ וְצַדִּיקִים יֵלְכוּ בָם וּפוֹשְׁעִים יִכָּשְׁלוּ בָם.</p>\n<p>רַבִּי חִיָּיא פָּתַח וְאָמַר, (שמואל א ב׳:כ״ב) וְעֵלִי זָקֵן מְאֹד וְשָׁמַע אֵת כָּל אֲשֶׁר יַעֲשׂוּן בָּנָיו לְכָל יִשְׂרָאֵל וְאֵת אֲשֶׁר יִשְׁכְּבֻן אֶת הַנָּשִׁים הַצֹּבְאוֹת פֶּתַח אֹהֶל מוֹעֵד. וְכִי סַלְקָא דַעְתָּךְ דְּכֹהֲנֵי יְיָ דְּיַעַבְדוּן עֲבִידְתָּא דָא. וְהָא מִקַּדְמַת דְּנָא אִתְּמָר וּפְרִישַׁת אוֹרַיְיתָא הַהוּא חוֹבָא דִלְהוֹן דִּכְתִיב, (שמואל א ב׳:י״ז) כִּי נִאֲצוּ הָאֲנָשִׁים אֶת מִנְחַת יְיָ. וּכְתִיב וּמִשְׁפַּט הַכֹּהֲנִים מֵאֵת הָעָם כָּל אִישׁ זוֹבֵחַ זֶבַח וְגו'. וּכְתִיב גַּם בְּטֶרֶם יַקְטִירוּן אֶת הַחֵלֶב וּבָא נַעַר הַכֹּהֵן וְאָמַר לָאִישׁ הַזּוֹבֵחַ תְּנָה לִצְלוֹת לַכֹּהֵן וְגו'. וּכְתִיב וְאָמַר לוֹ כִּי עַתָּה תִּתֵּן וְאִם לֹא לָקַחְתִּי בְּחָזְקָה. וְעַל דָּא וַתְּהִי חַטַּאת הַנְּעָרִים גְּדוֹלָה מְאֹד וְגו'. וְכָל דָּא לָא הֲווּ נָטְלִין אֶלָּא מֵאִינוּן חוּלָקִין דְּהֲווּ לְהוּ לְכַהֲנֵי לְמֵיכַל מִנֵּיהּ, וְעַל דְּהֲוָה קָלִיל קָרְבָּנָא בְּעֵינַיְיהוּ אִתְעֲנָשׁוּ. וְהָכָא אָמַר אֵת אֲשֶׁר יִשְׁכְּבוּן אֶת הַנָּשִׁים הַצּוֹבְאוֹת.</p>\n<p>(אלא) חַס וְשָׁלוֹם דְּהֲווּ עָבְדוּ עֲבֵירָה דָא, כָּל שֶׁכֵּן בְּאַתְרָא קַדִּישָׁא הַהוּא, דְּלָא יְקוּמוּן כָּל יִשְׂרָאֵל וְיִקְטְלוּן לְהוֹן. אֶלָּא בְּגִין דְּהֲווּ מְעַכְּבֵי לוֹן לְאָעֳלָא לְמַקְדְּשָׁא, וּמָחָאן בִּידֵהוֹן דְּלָא לְאָעֳלָא לְמִצְלֵי צְלוֹתָא עַד דְּקוּרְבָּנַיָא אִתְעֲבִידוּ בְּגִין דְּאִינוּן לָא מַיְיתִין קָרְבָּנִין לְמֵיטַל חוּלָקָא מִנַּיְיהוּ, וּבְגִין כָּךְ מְעַכְּבִין לוֹן. וּבְגִין כָּךְ אִינוּן נָשִׁים הֲווּ בָּעָאן מִנַּיְיהוּ לְאַעֳלָא תַּמָּן. וְעַל דָּא כְּתִיב אֵת אֲשֶׁר יִשְׁכְּבוּן אֶת הַנָּשִׁים, דִּמְעַכְּבֵי לוֹן כִּדְקָאֲמָרָן.</p>\n<p>כְּגַוְונָא דָא וַיִּשְׁכַּב אֶת בִּלְהָה. חַס וְשָׁלוֹם דְּאִיהוּ שָׁכַב עִמָּהּ, אֶלָּא בְּגִין דְּעָכַּב לָהּ לְשַׁמָּשָׁא בַּאֲבוֹי שִׁמּוּשָׁא דְמִצְוָה, וְדָא הוּא בִּלְבּוּלָא דְעַרְסָא. וְעֲבַד לָקֳבֵיל שְׁכִינְתָּא עֲבִידְתָּא דָא, דְּבְּכָל אֲתַר דְּשִׁמּוּשָׁא דְמִצְוָה אִשְׁתַּכַּח, שְׁכִינְתָּא שַׁרְיָא עַל הַהוּא אֲתַר וְאִשְׁתַּכַּח תַּמָּן. וּמַאן דְּגָרִים לְעַכָּבָא שִׁמּוּשָׁא דְמִצְוָה גָּרִים דְּיִסְתַּלַּק שְׁכִינְתָּא מֵעַלְמָא. וְעַל דָּא כְּתִיב (בראשית מ״ט:ד׳) כִּי עָלִיתָ מִשְׁכְּבֵי אָבִיךָ אָז חִלַּלְתָּ יְצוּעִי עָלָה. וּבְגִין דָּא כְּתִיב, וַיִּשְׁכַּב אֶת בִּלְהָה פִּלֶגֶשׁ אָבִיו וַיִּשְׁמַע יִשְׂרָאֵל וַיִּהְיוּ בְּנִי יַעֲקֹב שְׁנֵים עָשָׂר. כֻּלְּהוּ הֲווּ בְּמִנְיָינָא וְלָא גָרַע מִזְּכוּתָא דִלְהוֹן כְּלוּם.</p>\n<p>רִבִּי אֶלְעָזָר אָמַר, מַאי טַעֲמָא בְּקַדְמִיתָא יִשְׂרָאֵל וּלְבָתַר יַעֲקֹב. דִּכְתִיב, וַיִּשְׁמַע יִשְׂרָאֵל וַיִּהְיוּ בְּנֵי יַעֲקֹב שְׁנֵים עָשָׂר. אֶלָּא כַּד אֲתָא רְאוּבֵן וּבִלְבֵּל הַהוּא עַרְסָא אָמַר וּמַה תְּרֵיסַר שִׁבְטִין הֲווּ לֵיהּ לְאַבָּא לְקַיְימָא בְּעַלְמָא וְלָא יַתִּיר, וְהַשְׁתָּא בָּעֵי לְאוֹלָדָא בְּנִין דִּילְמָא אֲנַן פְּגִימִין דְּאִיהוּ בָּעֵי לְאוֹלָדָא אָחֳרָנִין כְּמִלְּקַדְמִין. מִיָּד בִּלְבֵּל הַהוּא עַרְסָא, וְאִתְעַכַּב הַהוּא שִׁמּוּשָׁא. כְּאִילּוּ עֲבַד קְלָנָא לְגַבֵּי שְׁכִינְתָּא דְּשַׁרְיָא עַל הַהוּא עַרְסָא. וְעַל דָּא כְּתִיב וַיִּשְׁמַע יִשְׂרָאֵל, דְּהָא בִּשְׁמָא דָא אִסְתַּלַּק גּוֹ תְּרֵיסַר דְּאִתְכַּסְיָין דְּאִינוּן תְּרֵיסַר נַהֲרִי אֲפַרְסְמוֹנָא דַכְיָא.</p>\n<p>וַיִּהְיוּ בְּנִי יַעֲקֹב שְׁנֵים עָשָׂר, אִלֵּין תְּרֵיסַר שִׁבְטִין דִּשְׁכִינְתָּא אִתְתַּקָּנַת בְּהוּ. וּמַאן אִינוּן, אִלֵּין דְּאוֹרַיְיתָא אַהֲדָרַת וְעָבִיד לוֹן חוּשְׁבְּנָא <Nonei></i>כְּמִלְּקַדְּמִין. כֻּלְּהוּ קַדִּישִׁין, כֻּלְּהוּ אִתְחַזְיָין לְגַבֵּי שְׁכִינְתָּא לְאִסְתַּכָּלָא בִּקְדוּשָׁה דְמָארֵיהוֹן. דְּאִילּוּ עֲבַד הַהוּא עוֹבָדָא לָא יֵיתֵי רְאוּבֵן בְּמִנְיָינָא.</p>\n<p>וְעִם כָּל דָּא אִתְעֲנַשׁ דְּאִתְנְטִיל בְּכוֹרָתֵיהּ מִנֵּיהּ וְאִתְיְהִיב לְיוֹסֵף כְּמָה דְאַתְּ אָמֵר, (דברי הימים א ה׳:א׳) וּבְנֵי רְאוּבֵן בְּכוֹר יִשְׂרָאֵל כִּי הוּא הַבְּכוֹר וּבְחַלְּלוֹ יְצוּעֵי אָבִיו נִתְּנָה בְּכוֹרָתוֹ לְיוֹסֵף. תָּא חֲזֵי, (דניאל ב׳:כ׳) לֶהוֵא שְׁמֵהּ דִּי אֱלָהָא מְבָרַךְ מִן עָלְמָא וְעַד עָלְמָא דִּי כָּל מַעְבְּדוֹהִי קְשׁוֹט וְאָרְחָתֵיהּ דִּין, וְכָל מַה דְּאִיהוּ עָבִיד כֹּלָּא אִיהוּ בְּחָכְמְתָא עִלָּאָה.</p>\n<p>תָּא חֲזֵי, כַּמָּה גָרִים עוֹבָדָא דְבַר נָשׁ, דְּהָא כָּל מַאי (מאן) דְאִיהוּ עָבִיד, כֹּלָּא אִתְרְשִׁים וְקָיְימָא קַמֵּי דְקוּדְשָׁא בְּרִיךְ הוּא. דְּהָא יַעֲקֹב בְּשַׁעְתָּא דְעָאל לְגַבָּהּ דְלֵאָה, כָּל הַהוּא לֵילְיָא רְעוּתֵיהּ וְלִבֵּיהּ הֲוָה בְּרָחֵל, דְּחָשִׁיב דְּרָחֵל אִיהִי. וּמֵהַהוּא שִׁמּוּשָׁא וְטִפָּה קַדְמָאָה וּמֵהַהוּא רְעוּתָא אִתְעֲבָרַת לֵאָה וְאוּקְמוּהָ. דְּהָא אִלְמָלֵא דְיַעֲקֹב לָא יָדַע לָא יִסְתַּלִּיק רְאוּבֵן בְּחוּשְׁבָּנָא. וְעַל דָּא לָא אִסְתַּלַּק בִּשְׁמָא יְדִיעָא אֶלָּא שְׁמֵיהּ סְתָם רְאוּבֵן.</p>\n<p>וְעִם כָּל דָּא אַהֲדַר עוֹבָדָא לְאַתְרֵיהּ, כְּמָה דְהַהוּא רְעוּתָא קַדְמָאָה אִתְעֲבִידַת בְּרָחֵל, הַהוּא רְעוּתָא אִתְהַדָּרַת בָּהּ. דְּהָא בְּכוֹרָתֵיהּ אַהֲדָרַת לְיוֹסֵף בּוּכְרָא דְרָחֵל, אֲתַר דִּרְעוּתָא הֲוַת בְּרָחֵל וְכֹלָּא סָלִיק בְּאַתְרֵיהּ. בְּגִין דְּכָל עוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא כֻּלְּהוּ קְשׁוֹט וּזְכוּ.</p>"],[9520011362,"<p>רִבִּי חִזְקִיָּה אַשְׁכְּחֵיהּ יוֹמָא חַד לְרַבִּי יוֹסֵי דְּהֲוָה מִסְטְמִיט סַפְסִינָא גוֹ קִטְרֵי דְנוּרָא וְהֲוָה סָלִיק קִטּוֹרָא דִּתְנָנָא לְעֵילָא. אָמַר לֵיהּ, אִלּוּ קִטּוּרָא דִּתְנָנָא דְקָרְבָּנָא דְּהֲוָה סָלִיק עַל גַּבֵּי מַדְבְּחָא הֲוָה סָלִיק תָּדִיר כִּי הַאי גַוְונָא, לָא שַׁרְיָא רוּגְזָא בְּעַלְמָא וְיִשְׂרָאֵל לָא אִתְגְּלִי מֵעַל אַרְעָא.</p>\n<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, (שיר השירים ג׳:ו׳) מִי זֹאת עֹלָה מִן הַמִּדְבָּר כְּתִימְרוֹת עָשָׁן מְקֻטֶּרֶת מֹר וּלְבוֹנָה מִכֹּל אַבְקַת רוֹכֵל. מִי זֹאת עוֹלָה. תָּא חֲזֵי, בְּזִמְנָא דְהֲווּ יִשְׂרָאֵל אָזְלֵי בְּמַדְבְּרָא, שְׁכִינְתָּא אָזְלָא קַמַּיְיהוּ וְאִינְהוּ הֲווּ אָזְלֵי אֲבַתְרָהּ. דִּכְתִיב, (שמות י״ג:כ״א) וַיְיָ הוֹלֵךְ לִפְנֵיהֶם יוֹמָם בְּעַמּוּד עָנָן לַנְחוֹתָם הַדֶּרֶךְ וְלַיְלָה בְּעַמּוּד אֵשׁ לְהָאִיר לָהֶם וְגו'. וּבְגִין כָּךְ כְּתִיב, (ירמיה ב) כֹּה אָמַר יְיָ זָכַרְתִּי לָךְ חֶסֶד נְעוּרַיִךְ אַהֲבַת כְּלוּלוֹתַיִךְ לֶכְתֵּךְ אַחֲרַי בַּמִּדְבָּר וְגו'.</p>\n<p>וּשְׁכִינְתָּא הֲוַת אָזְלָא וְכֻלְּהוּ עֲנָנֵי יְקָר בַּהֲדָהּ. וְכַד הֲוָה שְׁכִינְתָּא נָטְלָא, הֲווּ נָטְלִין. כְּמָה דִכְתִיב, (שמות מ׳:ל״ו) וּבְהֵעָלוֹת הֶעָנָן מֵעַל הָאֹהֶל וְאַחֲרֵי כֵן יִסְּעוּ בְּנִי יִשְׂרָאֵל וְגו'. וְכַד אִיהִי סָלְקָא הַהוּא עֲנָנָא סָלְקָא עַד לְעֵילָא, וְכָל בְּנֵי עַלְמָא חָמָאן וְשָׁאֲלֵי וְאָמְרֵי, מִי זֹאת עוֹלָה מִן הַמִּדְבָּר כְּתִימְרוֹת עָשָׁן.</p>\n<p>הַהוּא עֲנָנָא דִּשְׁכִינְתָּא אִתְחַזְיָא עָשָׁן, מַאי טַעֲמָא אִיהִי עָשָׁן. בְּגִין דְּנוּרָא דְּאַדְלִיק אַבְרָהָם וְיִצְחָק בְּרֵיהּ הֲוָה אָחִיד בָּהּ וְלָא אַעֲדֵי מִינָהּ. וְכַד אִתְאַחְדַת הַהוּא נוּרָא בְּגַוָּוהּ הֲוָה סָלִיק עֲנָנָא (נ\"א תננא).</p>\n<p>וְעִם כָּל דָּא, מְקֻטֶּרֶת מֹר וּלְבוֹנָה. מַאי מְקֻטֶּרֶת, מִתְקַטְרָא בִּתְרֵין סִטְרִין אָחֳרָנִין, עֲנָנָא דְאַבְרָהָם לִימִינָא, עֲנָנָא דְיִצְחָק לִשְׂמָאלָא. מִכֹּל אַבְקַת רוֹכֵל, דָּא יַעֲקֹב.</p>\n<p>דָּבָר אַחֵר דָּא יוֹסֵף הַצַּדִּיק, בְּגִין דַּאֲרוֹנָא דְיוֹסֵף הֲוָה אָזִיל לְגַבֵּיהּ, אַמַּאי רוֹכֵל, בְּגִין דְּהֲוָה רָכִיל לַאֲחוֹי לְגַבֵּיהּ דְּאֲבוֹי. דָּבָר אַחֵר אַמַּאי רוֹכֵל, אֶלָּא מַה חֶנְוָנִי דָא קְטִירֵי דְּקוּסְטְרֵי וְאַבְקֵי דְפוּלְמֵי כֻּלְּהוּ בִּידֵיהּ. הָכִי נָמֵי יוֹסֵף, אִיהוּ קִיּוּמָא דְאוֹרַיְיתָא בְּגִין דְּאִיהוּ קִיֵּים לָהּ, בְּגִין דְּכָל פִּקּוּדֵי אוֹרַיְיתָא מִתְקַשְּׁרָן בִּנְטִירוּ דִּבְרִית קַדִּישָׁא.</p>\n<p>וְעַל דָּא שְׁכִינְתָא מִתְקַטְּרָא בְּאַבְרָהָם יִצְחָק וְיַעֲקֹב וְיוֹסֵף, כְּחֲדָא אִינוּן וְדִיוּקְנָא חָדָא לְהוּ. הֲדָא הוּא דִּכְתִיב, (בראשית ל״ז:ב׳) אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף. וּבְגִין כָּךְ מִכֹּל אַבְקַת רוֹכֵל, בְּגִין דְּמֵאֲתַר דְּנַהֲרָא דְּנָגִיד וְנָפִיק אִשְׁתַּקְיָיא כֹּלָּא וּנְהִירוּ כָּל אַנְפִּין.</p>\n<p>וְתָּא חֲזֵי, כַּד הֲווּ יִשְׂרָאֵל בְּאַרְעָא וְהֲווּ מַקְרִיבִין קָרְבָּנִין, כֻּלְּהוּ הֲווּ מִתְקָרְבִין לְגַבֵּי קוּדְשָׁא בְּרִיךְ הוּא כְּדְקָא יָאוֹת, וְכַד קָרְבָּנָא אִתְעֲבִיד וּתְנָנָא סָלִיק בְּאֹרַח מֵישַׁר, כְּדֵין הֲווּ יָדְעֵי דִּתְנָנָא דְּמַדְבְּחָא אַדְלִיק <Nonei></i>בּוֹצִינָא דְּאִתְחַזְּיָא לְאַדְלָקָא, וְכָל אַנְפִּין נְהִירִין וּבוֹצִינִין דָּלְקִין.</p>\n<p>וּמִיּוֹמָא דְּאִתְחָרִיב בֵּי מַקְדְּשָׁא לֵית לָךְ יוֹמָא וְיוֹמָא דְּלֵית בֵּיהּ זְעִימוּ וְרוּגְזָא. כְּמָה דְאַתְּ אָמֵר, (תהלים ז) וְאֵל זוֹעֵם בְּכָל יוֹם, וְאִתְפָּרַשׁ חֶדְוָה מֵעֵילָא וּמִתַּתָּא. וְיִשְׂרָאֵל אָזְלִין בְּגָלוּתָא וְאִינוּן בִּרְשׁוּ דְּטַעֲוָון אָחֳרָנִין. וּכְדֵין אִתְקְיַּים קְרָא דִּכְתִיב, (דברים כ״ח:ל״ו) וְעָבַדְתָּ שָׁם אֱלֹהִים אֲחֵרִים.</p>\n<p>וְכָל דָּא לָמָּה, בְּגִין דִּכְתִיב, (דברים כ״ח:מ״ז) תַּחַת אֲשֶׁר לא עָבַדְתָּ אֶת יְיָ אֱלֹהֶיךָ בְּשִׂמְחָה וּבְטוּב לֵבָב מֵרוֹב כֹּל. מַאי מֵרוֹב כֹּל. הָכָא מֵרוֹב כֹּל, וְהָתָם בְּחֹסֶר כֹּל.</p>\n<p>עַד דְּיִתְעַר קוּדְשָׁא בְּרִיךְ הוּא וְיִפְרוֹק לוֹן מִבֵּינִי עַמְמַיָא, כְּמָא דְאַתְּ אָמֵר, (דברים ל׳:ג׳) וְשָׁב יְיָ אֱלֹהֶיךָ אֶת שְׁבוּתְךָ וְרִחַמְךָ וְשָׁב וְקִבֶּצְךָ מִכָּל הָעַמִּים אֲשֶׁר הֶפִיצְךָ יְיָ אֱלהֶיךָ שָׁמָּה. וּכְתִיב אִם יִהְיֶה נִדַּחֲךָ בִּקְצֵה הַשָּׁמַיִם מִשָּׁם יְקַבֶּצְךָ וְגו':</p>"],[9520011363,"<p>וְאֵלֶּה תּוֹלְדוֹת עֵשָׂו הוּא אֱדוֹם. תָּא חֲזֵי, בְּחַיֵּי יִצְחָק לָא אִתְמַנּוּן בְּנוֹי דְעֵשָׂו כְּמָה דְּאִתְמַנּוּן בְּנוֹי דְיַעֲקֹב, דְּהָא עַד לָא מִית יִצְחָק אִתְמַנּוּן. אֲבָל בְּעֵשָׂו מַה כְּתִיב וַיִּגְוַע יִצְחָק וַיָּמָת וַיֵּאָסֶף אֶל עַמָּיו זָקֵן וּשְׂבַע יָמִים וַיִּקְבְּרוּ אֹתוֹ עֵשָׂו וְיַעֲקֹב בָּנָיו. בַּתְרֵיהּ מַה כְּתִיב וְאֵלֶּה תּוֹלְדוֹת עֵשָׂו הוּא אֱדוֹם. מַאי טַעְמָא, בְּגִין דְּהָא בְּחוּלָקֵיהּ וּבְאַחְסַנְתֵיהּ וְעַדְבֵיהּ לָאו אִיהוּ, אֶלָּא יַעֲקֹב וּבְנוֹי. וּבְגִין כָּךְ יַעֲקֹב וּבְנוֹי אִינוּן חוּלָקֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא וְעָאלִין בְּחוּשְׁבְּנָא. אֲבָל עֵשָׂו דְּלָאו אִיהוּ בְּחוּלָקָא דְּבִסְטַר דִּמְהֵימְנוּתָא, עָבִיד חוּשְׁבְּנֵיהּ לְבָתַר דְּמִית יִצְחָק, וְאִתְפְּרַשׁ חוּלָקֵיהּ לְאֲתַר אָחֳרָא.</p>\n<p>תָּא חֲזֵי, לְבָתַר דְּמִית יִצְחָק, וְעֵשָׂו אִתְפָּרַשׁ לְסִטְרֵיהּ, מַה כְּתִיב וַיִקַּח עֵשָׂו אֶת נָשָׁיו וְגו' מִפְּנֵי יַעֲקֹב אָחִיו. דְּשָׁבַק לֵיהּ לְיַעֲקֹב קֶרֶן וְרֶיוַח שִׁעְבּוּדָא דְמִצְרַיִם, וְאַרְעָא. וְזַבִּין לֵיהּ חוּלָקֵיהּ מִן מְעַרְתָּא דְכָפֶלְתָּא, וְאֲזַל לֵיהּ מִן אַרְעָא וּמִן מְהֵימְנוּתָא וּמֵחוּלָקֵיהּ, דְּאֲזַל לֵיהּ מִכֹּלָּא.</p>\n<p>תָּא חֲזֵי, כַּמָּה הֲוָה חוּלָקֵיהּ דְּיַעֲקֹב טָבָא בְּכֹלָּא. בְּגִין דְּלָא אִשְׁתָּאַר עֵשָׂו בַּהֲדֵיהּ וְאִתְפְּרַשׁ מִנֵּיהּ וְאֲזַל לֵיהּ לְחוּלָקֵיהּ וּלְעַדְבֵיהּ, וְאִשְׁתָּאַר יַעֲקֹב אָחִיד בְּאַחְסָנַת אֲבוֹי וּבְאַחְסָנַת אַבְהָתוֹי. וְעַל דָּא וַיֵּלֶךְ אֶל אֶרֶץ מִפְּנֵי יַעֲקֹב אָחִיו. מַאי מִפְּנֵי יַעֲקֹב אָחִיו. דְּלָא בָּעָא חוּלָקֵיהּ וְאַחְסַנְתֵּיהּ וְעַדְבָא דִמְהֵימְנוּתָא דִילֵיהּ. זַכָּאָה חוּלָקֵיהּ דְּיַעֲקֹב עֲלֵיהּ כְּתִיב, (דברים ל״ב:ט׳) כִּי חֵלֶק יְיָ עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ:</p>"],[9520011364,"<p>וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל. רַבִּי יֵיסָא פָּתַח וְאָמַר, (עובדיה א׳:ב׳) הִנֵּה קָטָן נְתַתִּיךָ בַּגּוֹיִם בָּזוּי אַתָּה מְאֹד. תָּא חֲזֵי, כַּד עֲבַד קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, וּפָלַג אַרְעָא לְשִׁבְעָה תְּחוּמֵי פְּלִיגִין לָקֳבֵיל שִׁבְעִין רַבְרְבִין מְמַנָּן, וְקוּדְשָׁא בְּרִיךְ הוּא פָּלִיג לוֹן לְשִׁבְעִין עַמִין כָּל חַד וְחַד כְּדְקָא חָזֵי לֵיהּ, כְּמָה דְאַתְּ אָמֵר, (דבהם לכ) בְּהַנְחֵל עֶלְיוֹן גּוֹיִם בְּהַפְרִידוֹ בְּנֵי אָדָם יַצֵב גְּבוּלוֹת עַמִים.</p>\n<p>וּמִכֻּלְּהוּ רַבְרְבָן מְמַנָּן דְּאִתְמַסְרוּ לִשְׁאָר עַמִין לָא אִית בְּהוּ בָּזוּי קַמֵּיהּ כִּמְמַנָּא דְעֵשָׂו. מַאי טַעֲמָא, בְּגִין דְּסִטְרָא דְעֵשָׂו סִטְרָא מְסָאֲבָא אִיהוּ, וְסִטְרָא דִמְסָאֲבָא אִיהוּ קְלָנָא קַמֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא. מֵאִינוּן דַּרְגִּין זְעִירִין דְּבָתַר רֵיחַיָא סְרִיקְתָּא דְּקוֹסְטְרֵי סוּמְקֵי קָא אַתְיָא, וְעַל דָּא הִנֵּה קָטָן נְתַתִּיךָ בַּגּוֹיִם, בָּזוּי אַתָּה מְאֹד. דִּכְתִיב, (בראשית ג׳:י״ד) עַל גְּחוֹנְךָ תֵּלֵךְ וְעָפָר תֹּאכַל כָּל יְמֵי חַיֶּיךָ. מְאֹד, כְּמָה דְאַתְּ אָמֵר אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וּמִכָּל חַיַּת הַשָּׂדֶה.</p>\n<p>תָּא חֲזֵי, בְּדַרְגִּין תַּתָּאִין אִית דַּרְגִּין עַל דַּרְגִּין, כֻּלְּהוּ מְשַׁנְיָין דָּא מִן דָּא, וְכֻלְּהוּ דַרְגִּין קַפְטִירִין אִלֵּין, וּקְשִׁירִין אִלֵּין בְּאִלֵּין, וּמַלְכוּ אִתְפָּרַשׁ דָּא מִן דָּא, וּמַלְכוּ אִתְקַשַּׁר בְּמַלְכוּ. דָּא עֲיִּיל, וְדָא סָלִיק, אֲחִידָן בְּקִשְׁרָא חָדָא.</p>\n<p>הַהוּא קִשְׁרָא מִשְׁחָתָא חָדָא לֵיהּ, וּתְלַת קִשְׁרִין לְהַהִיא מִשְׁחָתָא. בְּכָל קִשְׁרָא וְקִשְׁרָא חַד עִטְּרָא, וּבְכָל עִטְּרָא וְעִטְּרָא חַד קַפְסוֹרָא</p>\n<p>וְאִתְמַנָּא בְּעִטּוּרָא דִלְעֵילָא, וְאִתְמַנָּא וְנָחִית לְתַתָּא, עַד דְּאִתְקַשְּׁרוּ בֵּיהּ כֹּכְבַיָא וּמַזָּלֵי. כָּל חַד וְחַד אִתְפְּרַשׁ בֵּיהּ חַד <Nonei></i>כֹּכָבָא וְחַד מַזָּלָא, וְכָל כֹּכְבַיָא זְמִינִין אִינוּן בְּאִינוּן דַּרְגִּין דִּלְעֵילָא. וְעַל דָּא כָּל דַּרְגָּא וְדַרְגָּא אִתְעַטַּר בְּאַתְרִין יְדִיעָן כְּדְקָא חָזֵי.</p>\n<p>וְכַד מִתְפָּרְשָׁן דַּרְגִּין אִשְׁתַּכַּח קִטּוּרָא דְּפוּסְתָּקָא, עַד דְּאִתְקַשְּׁרָא בְּסִטְרָא דְּאִתְחֲזֵי לוֹן, וְסִטְרֵי דְדַרְגֵי מְסָאֲבֵי דְּאִינוּן בִּסְטַר שְׂמָאלָא כֻּלְּהוּ מִתְפָּרְשָׁן לְכַמָּה אָרְחִין וּשְׁבִילִין מִסִּטְרֵי גְּבוּרָן סוּמְקָן. וּבְגִין כָּךְ תַּלְיָין גְּבוּרָן לְתַתָּא לְאֶלֶף אַלְפִין וְרִבּוֹ רִבְבָן, וְעַל דָּא הִנֵּה קָטָן נְתַתִּיךָ בַּגּוֹיִם בָּזוּי אַתָּה מְאֹד כִּדְקָאֲמָרָן.</p>\n<p>תָּא חֲזֵי, וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם. בְּאֶרֶץ, בְּסִטְרָא דְדַרְגָּא דִּילֵיהּ דְּאִיהוּ דַּרְגָּא דְעֵשָׂו. דִּכְתִיב עֵשָׂו הוּא אֱדוֹם, וְכֻלְּהוּ קָאָתוּ מִסִּטְרָא דְרוּחַ מְסָאֲבָא. לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל, בְּגִין דְּאִינוּן דַּרְגִּין דְּקַיָּימִין בֵּי תַּרְעֵי לְתַתָּא קַדְמָאי. וּבְגִין כָּךְ אָמַר יַעֲקֹב, יַעֲבָר נָא אֲדֹנִי לִפְנֵי עַבְדּוֹ. בְּגִין דַּרְגִּין דִּילֵיהּ קַדְמָאִין אִינוּן לְאָעֳלָא. וּבְגִין כָךְ לִפְנֵי מְלָךְ מֶלֶךְ לִבְנִי יִשְׂרָאֵל. דְּעַד כְּעָן לָא מָטָא זִמְנָא דְּמַלְכוּ שְׁמַיָא לְשַׁלְטָאָה וּלְאִתְאַחֲדָא בִּבְנִי יִשְׂרָאֵל. וּבְגִין כָּךְ אָמַר יַעֲבָר נָא אֲדֹנִי לִפְנִי עַבְדּוֹ.</p>\n<p>וְכַד שְׁלִימוּ אִלֵּין דַּרְגִּין בְּקַדְמִיתָא, לְבָתַר אִתְעַר מַלְכוּ שְׁמַיָא לְשַׁלְטָאָה עַל תַּתָּאֵי. וְכַד שָׁרָא, שָׁרָא בִּזְעִירָא דְּכָל שִׁבְטִין דְּאִיהוּ בִּנְיָמִין. כְּמָה דְאַתְּ אָמֵר, (תהילים ס״ח:כ״ח) שָׁם בִּנְיָמִין צָעִיר רוֹדֵם וְגו'. וּבֵיהּ שָׁארֵי לְאַתְעָרָא מַלְכוּתָא, לְבָתַר אֲתָא מַלְכוּתָא בְּאַתְרֵיהּ וְאִתְקְיַּים בַּהֲדֵיהּ דְּלָא תַעֲדֵי לְעָלְמִין.</p>"],[9520011365,"<p>רִבִּי חִיָּיא פָּתַח וְאָמַר, (ישעיהו מ״ה:א׳) וְעַתָּה שְׁמַע יַעֲקֹב עַבְדִּי וְיִשְׂרָאֵל בָּחַרְתִּי בוֹ. כֹּה אָמַר יְיָ עֹשֶׂךָ וְיֹצֶרְךָ מִבֶּטֶן יַעַזְרֶךָּ אַל תִּירָא עַבְדִּי יַעֲקֹב וִישֻׁרוּן בָּחַרְתִּי בוֹ. תָּא חֲזֵי, כַּמָּה אַבְטַח לוֹן קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל בְּכַמָּה אֲתַר (ד\"א ל\"ג בגין) לְמִזְכֵּי לְהוּ לְעַלְמָא דְאָתֵי, דְּהָא לָא אִתְרָעֵי לְחוּלָקֵיהּ לְכָל עַם וְלִישָׁן בַּר לְיִשְׂרָאֵל בִּלְחוֹדוֹי. וּבְגִין כָּךְ יָהַב לוֹן אוֹרַיְיתָא דִקְשׁוֹט. לְמִזְכֵּי בָּהּ וּלְמִנְדַע אָרְחוֹי דְקוּדְשָׁא בְּרִיךְ הוּא בְּגִין דְּיִרְתוּן אַרְעָא קַדִּישָׁא. דְּכָל מַאן דְּזָכֵי בְּהַאי אַרְעָא קַדִּישָׁא, אִית לֵיהּ חוּלָקָא לְעַלְמָא דְאָתֵי. כְּמָה דְאַתְּ אָמֵר, (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִרְשׁוּ אָרֶץ. וְהָא אִתְּמָר.</p>\n<p>תְּלַת דַּרְגִּין הָכָא, בְּקַדְמִיתָא יַעֲקֹב, וּלְבָתַר יִשְׂרָאֵל, וּלְבָתַר יְשׁוּרוּן. תָּא חֲזֵי, יַעֲקֹב הָא אוּקְמוּהָ. יִשְׂרָאֵל אוּף הָכִי נָמֵי. וְאַף עַל גַּב דְּדַרְגִּין אִינוּן חַד.</p>\n<p>יְשׁוּרוּן, אַמַּאי אִקְרוּן יִשְׂרָאֵל בִּשְׁמָא דָא. אֶלָּא יִשְׂרָאֵל וִישׁוּרוּן כֹּלָּא חַד. יְשׁוּרוּן, כְּמָה דְאַתְּ אָמֵר, (איוב ל״ג:כ״ז) יָשֹׁר עַל אֲנָשִׁים, בְּגִין דְּנָטִיל שׁוּרָה לְהַאי סִטְרָא וּלְהַאי סִטְרָא, וּבְגִין אִינוּן תְּרֵין שׁוּרִין אִקְרֵי יְשׁוּרוּן, וְדָא הוּא יִשְׂרָאֵל.</p>\n<p>יִשְׂרָאֵל עַל דְּנָטִיל רְבוּ וְתוּקְפָא מִכֹּלָּא. יִשְׂרָאֵל (ס\"א ישורון) עַל אִינוּן חוּלָקֵי תְּרֵין סִטְרִין תְּרִין שׁוּרִין כְּדְקָא אֲמָרָן, וְכֹלָּא חַד.</p>\n<p>וְאִינוּן שְׁמָהָן כֻּלְּהוּ סָלְקֵי לְחַד. יַעֲקֹב עַבְדִּי, זִמְנִין דְּאִיהוּ עֶבֶד כְּעַבְדָא דְּאִית לֵיהּ פִּקּוּדָא דְמָארֵיהּ וּלְמֶעְבַּד רְעוּתֵיהּ. וְכֵן יִשְׂרָאֵל בָּחַרְתִּי בוֹ, לְאַשְׁרָאָה עֲלֵיהּ, וְכֹלָּא בְּרָזָא עִלָּאָה אִיהוּ. כְּתִיב, (ישעיהו מ״ג:א׳) בֹּרַאֲךָ יַעֲקֹב וְיֹצֶרְךָ יִשְׂרָאֵל, וּכְתִיב כֹּה אָמַר יְיָ עֹשֶׂךָ, כָּל אִלֵּין דַּרְגִּין סָלְקִין לְחַד וְהָא אִתְּמָר, בּוֹרֵ\"א, יוֹצֵ\"ר. עוֹשֶׂ\"ה. וְכֻלְּהוּ דַרְגִּין אִלֵּין עַל אִלֵּין וְכֻלְּהוּ חַד.</p>\n<p>זַכָּאָה חוּלַקְהוֹן דְּיִשְׂרָאֵל דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהוּ מִכָּל עַמִין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, בְּגִין דְּבְכֻלְּהוּ כְּתִיב, (ירמיהו י׳:ט״ו) הֶבֶל הֵמָּה מַעֲשֵׂה תַּעְתֻּעִים בְּעֵת פְּקֻדָּתָם יֹאבֵדוּ, בְּשַׁעְתָּא דְּקוּדְשָׁא בְּרִיךְ הוּא זַמִּין לְבַעֲרָא לוֹן מִן עַלְמָא, וְיִשְׁתָּאַר הוּא בִּלְחוֹדוֹי כְּמָה דְאַתְּ אָמֵר, (ישעיהו ב׳:י״א) וְנִשְׂגָּב יְיָ לְבַדּוֹ בַּיּוֹם הַהוּא.</p>"],[9520011366,"<p>רִבִּי יְהוּדָה פָּתַח וְאָמַר, (ישעיהו מ״א:י״ד) אַל תִּירְאִי תּוֹלַעַת יַעֲקֹב מְתֵי יִשְׂרָאֵל אֲנִי עֲזַרְתִּיךְ נְאֻם יְיָ וְגֹאֲלֵךְ קְדוֹשׁ יִשְׂרָאֵל. תָּא חֲזֵי, כָּל עַמִין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת דְּעַלְמָא, קוּדְשָׁא בְּרִיךְ הוּא יָהַב לוֹן לִמְמַנָּן שָׁלְטָנִין יְדִיעִין כְּמָה דְאִתְּמָר. וְכֻלְּהוּ אָזְלֵי בָּתַר אֱלָהֲהוֹן, כְּמָה דִכְתִיב, (מיכה ד׳:ה׳) כִּי כָל הָעַמִּים יֵלְכוּ אִישׁ בְּשֵׁם אֱלהָיו. וְכֻלְּהוּ אוֹשְׁדִין דָּמִין וּמַגִּיחִין קְרָבָא גָּזְלִין קַפְּחִין וּמְנָאֲפִין, וְאִתְעָרְבֵי <Nonei></i>בְּכַמָּה עוֹבָדִין לְבִישׁ, וְאִתְתַּקָּפוּ בְּחֵילְהוֹן לְאַבְאָשָׁא.</p>\n<p>וְיִשְׂרָאֵל לֵית לוֹן תּוּקְפָא וְחֵילָא לְנַצְחָאָה לוֹן בַּר בְּפוּמְהוֹן, כְּתוֹלַעְתָּא דָא דְּלֵית לָהּ תּוּקְפָא וְחֵילָא אֶלָּא בְּפוּמָא, וּבְפוּמָא מִתְבַּר כֹּלָּא, וְעַל דָּא אִקְרוּן יִשְׂרָאֵל תּוֹלַעַת.</p>\n<p>תוּ אַל תִּירְאִי תּוֹלַעַת יַעֲקֹב, מַה תּוֹלַעַת לֵית לִבְרִיָה דְעַלְמָא כְּהַאי תּוֹלַעַת דְּמֶשִׁי דְּסִיסְטְרָא, דְּמִנָּהּ נָפְקֵי כָּל לְבוּשֵׁי יְקָר טִיסְטְרֵי דְמַלְכִין, לְבָתַר זָרַע זַרְעִין וּמִית, וּלְבָתַר מֵהַהוּא זַרְעָא דְּאִשְׁתָּאַר מִנֵּיהּ אִתְקְיַּים כְּמִלְּקַדְּמִין וְהָא אִיהוּ בְּקִיּוּמָא. כָּךְ יִשְׂרָאֵל אִינוּן כְּהַאי תּוֹלַעַת. דְאַף עַל גַּב דְּמֵתִין, יִתְהַדְּרוּן וְיִתְקַיְּימוּן בְּעַלְמָא כְּמִלְּקַדְּמִין.</p>\n<p>וְהָא אִתְּמָר (ד\"א ל\"ג דכתיב) (ירמיהו י״ח:ו׳) כִּי כַּחֹמֶר בְּיַד הַיּוֹצֵר כֵּן אַתֶּם בְּיָדִי בֵּית יִשְׂרָאֵל. מַאי כַּחֹמֶר. אֶלָא דָא הוּא חֹמֶר דְּהַהוּא זְכוּכִית, דְּאַף עַל גַּב דְּאִתָּבַר אִתְתַּקַּן וְאִית לֵיהּ תַּקָּנָה כְּמִלְּקַדְּמִין.</p>\n<p>מְתֵי יִשְׂרָאֵל, דָּא אִילָנָא דְחַיֵּי, דִּבְגִין דְּיִשְׂרָאֵל אִינוּן אִתְדַּבָּקוּ בְּאִילָנָא דְחַיֵּי, בְּגִין כָּךְ יְהֵא חַיִּין לְהוֹן וִיקוּמוּן מֵעַפְרָא וְיִתְקַיְּימוּן בְּעַלְמָא, וִיהוֹן לְעַם חַד לְמִפְלַח לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא. כְּמָה דְאַתְּ אָמֵר (צפניה ג׳:ט׳) לִקְרֹא כֻּלָּם בְּשֵׁם יְיָ לְעָבְדוֹ שְׁכֶם אֶחָד.</p>"],[9520011367,"<p>רִבִּי אֶלְעָזָר וְרִבִּי יִצְחָק הֲווּ אָזְלֵי בְּאָרְחָא, וּמָטָא זִמְנָא דִּקְרִיאַת שְׁמַע, וְקָם רַבִּי אֶלְעָזָר וְקָרָא קְרִיאַת שְׁמַע וְצַלֵּי צְלוֹתֵיהּ. לְבָתַר אָמַר לֵיהּ רִבִּי יִצְחָק, וְהָא תָּנִינָן דְּעַד לָא יִפּוּק בַּר נַשׁ לְאָרְחָא אִבָּעֵי לֵיהּ לְנַטְלָא רְשׁוּ מִמָּארֵיהּ וּלְצַלֵּי צְלוֹתֵיהּ.</p>\n<p>אָמַר לֵיהּ, בְּגִין דְּכַד נָפִיקְנָא לָא הֲוָה זְמַן צְלוֹתָא וְלָא מָטָא זִמְנָא דִּקְרִיאַת שְׁמַע, הַשְׁתָּא דְּשִׁמְשָׁא נָהִיר צַלֵּינָא. אֲבָל עַד לָא נָפַקְנָא לְאָרְחָא בָּעִינָא בָּעוּתָא מִנֵּיהּ וְאִמְלַכְנָא בֵּיהּ, אֲבָל צְלוֹתָא דָא לָא צַלֵּינָא.</p>\n<p>דְּהָא אֲנָא אִשְׁתַּדַּלְנָא בְּאוֹרַיְיתָא מִפַּלְגוּת לֵילְיָא, וְכַד אֲתָא צַפְרָא עַד כְּעָן לָא הֲוָה עִדְנָא לְצַלֵּי צְלוֹתָא. בְּגִין דְּהַהִיא שַׁעְתָּא דְּקַדְרוּתָא דְצַפְרָא אִשְׁתַּכַּח, אִתְּתָא מִשְׁתָּעֲיָא בְּבַעֲלָהּ, וְאִינוּן בְּרָזָא כְּחֲדָא, דְּבָעְיָא אִיהִי לְמֵיהַךְ לְמִשְׁכְּנָא בְּעוּלֵמְתָהָא דְּיַתְבֵי בַּהֲדָהּ. וּבְגִין כָּךְ לָא בָּעֵי לֵיהּ לְבַר נָשׁ לְמִפְסַק מִלַיְיהוּ דְּמִתְחַבְּרָן כְּחֲדָא וּלְאַעֳלָא מִלָּה אַחֲרָא בֵּינַיְיהוּ.</p>\n<p>וְהַשְׁתָּא דְּנָהִיר שִׁמְשָׁא הוּא עִדַּן צְלוֹתָא לְצַלָּאָה, כְּמָה דְאוּקְמוּהָ. דִּכְתִיב, (תהילים ע״ב:ה׳) יִירָאוּךָ עִם שָׁמֶשׁ. מַהוּ עִם שָׁמֶשׁ, לְנַטְרָא נְהוֹרָא דְּשִׁמְשָׁא בַּהֲדָן לְאַנְהָרָא לָהּ, דְּהָא יֵרָאֶה בַּהֲדֵי שִׁמְשָׁא אִצְטְרִיךְ וְלָא לְאַפְרָשָׁא לוֹן. וְכַד לָא נָהִיר יְמָמָא לָאו הוּא יֵרָאֶה בַּהֲדֵי שִׁמְשָׁא, וּצְרִיכָא לְחַבְּרָא לוֹן כְּחֲדָא. וְדָא הוּא עִם שָׁמֶשׁ.</p>\n<p>אֲזְלֵי, כַּד מָטוּ חַד בֵּי חֲקַל, יָתְבוּ. זָקְפוּ עֵינַיְיהוּ וְחָמָא לֵיהּ לְטוּרָא דְּהֲווּ סָלְקוּ בְּרוּמֵיהּ בְּרִיָּין מְשַׁנְיָין, דָּחִיל רִבִּי יִצְחָק, אָמַר לֵיהּ רִבִּי אֶלְעָזָר אַמַּאי דְחִילַת. אָמַר לֵיהּ חָמֵינָא דְּהַאי טוּרָא אִיהוּ תַּקִּיף, וְחָמֵינָא אִלֵּין בְּרִיָּין דְּאִינוּן מְשַׁנְיָין וְדָחִילְנָא דְּלָא יְקַטְרְגוּ לוֹן, אָמַר לֵיהּ מַאן דְּדָחִיל מֵחֶטְאוֹי דְּבִידֵיהּ אִית לֵיהּ לְמִדְחַל. תָּא חֲזֵי, לָאו אִלֵּין מֵאִינוּן בְּרִיָּין תַּקִּיפִין דְּהֲווּ מִשְׁתַּכְּחִין בְּטוּרַיָא.</p>"],[9520011368,"<p>פָּתַח וְאָמַר. וְאֵלֶּה בְּנֵי צִבְעוֹן וְאַיָּה וַעֲנָה וְגו' הוּא עֲנָה אֲשֶׁר מָצָא אֶת הַיֵּמִים וְגו', הַאי קְרָא אוּקְמוּהָ, אֲבָל תָּא חֲזֵי, לָאו אִלֵּין אִינוּן דִּכְתִיב בְּהוּ (דברים ב׳:י״ב) הָאֵימִים לְפָנִים יָשְׁבוּ בָהּ וְגו' וּבְנֵי עֵשָׂו יִירָשׁוּם וְגו'.</p>\n<p>אֲבָל אִלֵּין דְּקָאֲמַר קְרָא אֲשֶׁר מָצָא אֶת הַיֵּמִים בַּמִּדְבָּר, יֵמִם כְּתִיב. אִלֵּין הֲווּ בְּרִיָּין מְשַׁנְיָין. דְּכַד הֲוָה אִתָּרַךְ קַיִן מֵעַל אַפֵּי אַרְעָא כְּדִכְתִיב, (בראשית ד׳:י״ד) הֵן גֵּרַשְׁתָּ אֹתִי הַיּוֹם מֵעַל פְּנֵי הָאֲדָמָה וּמִפָּנְיךָ אֶסָּתֵר, וּכְתִיב וַיֵּשֶׁב בְּאֶרֶץ נוֹד וְאוּקְמוּהָ.</p>\n<p>מִבְּנֵי בְּנוֹי בְּסִטְרָא (ויקרא עו ע\"ב) דְּרוּחִין וְעִלְעוּלִין וּמַזִּיקִין וְאִלֵּין קָיְימוּ, דְּהָא כַּד בָּעָא לְאִתְקַדְּשָׁא יוֹמָא דְשַׁבַּתָּא, אִתָּבְרוּן מֵהַהוּא סִטְרָא רוּחִין קָיְימִין טְסִירִין (נ\"א טהירין) בְּלָא גוּפָא. וְאִלֵין לָאו אִינוּן מִיּוֹמָא דְשַׁבַּתָּא וְלָא מִיּוֹמָא שְׁתִיתָאָה, וְאִשְׁתָּאֲרוּ אִלֵּין תְּרֵין יוֹמִין בְּהוּ בִּסְפֵקָא, וּבְגִין כָּךְ לָא אִתְקָיְימוּ לָא <Nonei></i>מֵהַאי וְלָא מֵהַאי.</p>\n<p>וְאֲזְלוּ וְאִתְפַּשְּׁטוּ בְּהַהוּא סִטְרָא דְקַיִן וְאִגְלִימוּ בְּהַהוּא סִטְרָא וְלָא אִתְגְּלִימוּ לְאִתְקָיְימָא וְאִקְרוּן יֵמִ\"ם חָסֵר, דְּלָא אִתְקָיְימוּ לָא בְּיוֹמָא דָא וְלָא בְּיוֹמָא דָא, וְאִתְחֲזוּן לִבְנֵי נָשָׁא. וְאִיהוּ אַשְׁכַּח לוֹן וְאוֹלְפֵי לֵיהּ לְאַיְיתָאָה מַמְזֵרִין לְעַלְמָא. וְאִינוּן אָזְלֵי בֵּינֵי טוּרַיָא וְקָיְימִין בְּגוּפָא זִמְנָא חָדָא בְּיוֹמָא, וּלְבָתַר מִתְפַּשְׁטֵי מִנֵּיהּ.</p>\n<p>תָּא חֲזֵי, עֲנָה דָא אִיהוּ מַמְזֵרָא הֲוָה, דְּאֲתָא צִבְעוֹן עַל אִמֵּיהּ וְאוֹלִיד מַמְזֵרָא, וְדָא אֲתָא מִסִּטְרָא דְרוּחַ מְסָאֲבָא דְּאִתְדָּבַּק בֵּיהּ. וּבְגִין כָּךְ אַשְׁכַּח לוֹן וְהֲווּ אוֹלְפֵי לֵיהּ כָּל זִינִין דִּסְטַר מְסָאֲבָא בְּגִין דָּא.</p>\n<p>וְתָּא חֲזֵי, אִלֵּין אִינוּן וְכַמָּה אָחֳרָנִין מִתְפַּרְשָׁן אִלֵּין מֵאִלֵּין, כֻּלְּהוּ אַתְיָין מֵהַהוּא סִטְרָא וְאָזְלֵי בְּמַדְבְּרָא וְאִתְחֲזוּן תַמָּן. בְּגִין דְּמַדְבְּרָא אֲתַר חָרוּב וְאִיהוּ בֵּי מוֹתָבָא דִלְהוֹן. וְעִם כָּל דָּא, כָּל בַר נָשׁ דְּאָזִיל בְּאוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא וְדָחִיל לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא לָא מִסְתָּפֵי מִנַּיְיהוּ. אֲזְלוּ וְאָעֳלוּ בְּטוּרָא.</p>\n<p>אָמַר רִבִּי יִצְחָק, כְּגַוְונָא דָא כָּל אִינוּן טוּרִין חֲרוּבִין אֲתַר בֵּי מוֹתָבָא דִלְהוֹן. אָמַר לֵיהּ, הָכִי הוּא, וְכָל אִינוּן דְּמִשְׁתַּדְּלוּ בְּאוֹרַיְיתָא עֲלַיְיהוּ כְּתִיב, (תהילים קכ״א:ז׳-ח׳) יְיָ יִשְׁמָרְךָ מִכָּל רָע יִשְׁמֹר אֶת נַפְשֶׁךָ יְיָ יִשְׁמָר צֵאתְךָ וּבוֹאֶךָ מֵעַתָּה וְעַד עוֹלָם.</p>"],[9520011369,"<p>פָּתַח רִבִּי אֶלְעָזָר וְאָמַר, (שם קיא) הַלְלוּיָה אוֹדֶה יְיָ בְּכָל לֵבָב בְּסוֹד יְשָׁרִים וְעֵדָה, הַאי קְרָא אוּקְמוּהָ. אֲבָל תָּא חֲזֵי, דָּוִד מַלְכָּא כָּל יוֹמוֹי הֲוָה מִשְׁתַּדַּל בְּפוּלְחָנָא דְקוּדְשָׁא בְּרִיךְ הוּא, וְהֲוָה קָם בְּפַלְגוּת לֵילְיָא וּמְשַׁבַּח וּמוֹדֶה בְּשִׁירִין וְתוּשְׁבְּחָן, בְּגִין לְאִתְתַּקָּנָא דּוּכְתֵּיהּ בְּמַלְכוּ דִּלְעֵילָא.</p>\n<p>דְּכַד אִתְעַר רוּחַ צָפוֹן בְּפַלְגוּת לֵילְיָא, הֲוָה יָדַע דְּקוּדְשָׁא בְּרִיךְ הוּא בְּהַהִיא שַׁעְתָּא יִתְעַר בְּגִנְתָּא דְעֵדֶן לְאִשְׁתַּעְשֵׁעַ עִם צַדִּיקַיָּיא, וְאִיהוּ הֲוָה קָם בְּהַהִיא שַׁעְתָּא וְאִתְגַּבַּר בְּשִׁירִין וְתוּשְׁבְּחָן עַד דְּסָלִיק צַפְרָא.</p>\n<p>בְּגִין דְּכַד קוּדְשָׁא בְּרִיךְ הוּא אִשְׁתַּכַּח בְּגִנְתָּא דְעֵדֶן, הָא אוֹקִימְנָא דְּאִיהוּ וְכָל צַדִּיקַיָּיא דִּבְגִנְתָּא כֻּלְּהוּ צַיְיתִין לְקָלֵיהּ. כְּדִכְתִיב, (שיר השירים ח׳:י״ג) חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִנִי. וְלָא עוֹד, אֶלָּא דְחוּטָא דְחֶסֶד מָשִׁיךְ עֲלֵיהּ בִּימָמָא כְּמָה דְאִתְּמָר. דִּכְתִיב, (תהילים מ״ב:ט׳) יוֹמָם יְצַוֶּה יְיָ חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי. וְלא עוֹד, אֶלָּא דְאִינוּן מִלִּין דְּאוֹרַיְיתָא דְּאִיהוּ אָמַר, כֻּלְּהוּ סָלְקִין וּמִתְעַטְּרִין קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. וּבְגִין כָּךְ דָּוִד מַלְכָּא הֲוָה מִשְׁתַּדֵּל בְּלֵילְיָא בְּפוּלְחָנָא דְמָארֵיהּ.</p>\n<p>תָּא חֲזֵי, הַלְלוּיָהּ, בְּכָל אִינוּן שִׁירִין וְתוּשְׁבְּחָן דְּקָאֲמַר דָּוִד, הָא תָּנִינָן דִּלְעֵילָא מִכֻּלְּהוֹן הוּא הַלְלוּיָהּ וְאוּקְמוּהָ. מַאי טַעְמָא בְּגִין דְּכָלִיל שְׁמָא וּשְׁבָחָא כַּחֲדָא. מַאי שְׁמָא וּשְׁבָחָא. שְׁמָא דָּא (א) י\"ה. שְׁבָחָא מַאן אִיהוּ, אֶלָּא דָּא כְּנֶסֶת יִשְׂרָאֵל דְּאִיהוּ (הלל בגימ' ה\"ס שהוא אדני) מְתַקְנָּא שְׁבָחָא תָּדִיר לְקוּדְשָׁא בְּרִיךְ הוּא, וְלָא אִשְׁתַּכְּכַת. כְּמָה דְאַתְּ אָמֵר, (תהילים פ״ג:ב׳) אֱלהִים אַל דֳּמִי לָךְ אַל תֶּחרָשׁ וְאַל תִּשְׁקֹט אֵל. בְּגִין דְּסִדּוּרָא דְּשְׁבָחָא אִיהִי מְסַדְּרַת וּמְשַׁבַּחַת תָּדִיר לְגַבֵּיהּ. וּבְגִין כָּךְ שְׁמָא וּשְׁבָחָא כַּחֲדָא.</p>\n<p>אוֹדֶה יְיָ בְּכָל לֵבָב, כְּמָה דְאוּקְמוּהָ בְּיֵצֶר הַטּוֹב וּבְיֵצֶר הָרָע, בְּגִין דְּאִינוּן מִשְׁתַּכְּחֵי תָּדִיר לְגַבֵּיהּ דְּבַר נָשׁ, כְּמָה דְאַתְּ אָמֵר, (דברים ו) בְּכָל לְבָבְךָ וְאוּקְמוּהָ.</p>\n<p>בְּסוֹד יְשָׁרִים (ועדה), אִלֵּין אִינוּן יִשְׂרָאֵל דְּכָל דַּרְגִּין בְּהוּ מִתְעַטְּרָן כַּהֲנֵי וְלֵיוָאֵי, צַדִּיקֵי וַחֲסִידֵי, יְשָׁרִים. וְעֵדָה, כְּמָה דְאַתְּ אָמֵר (תהילים פ״ב:א׳) נִצָּב בַּעֲדַת אֵל. וְאִינוּן רָזָא דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְעַטַּר בְּהוּ.</p>\n<p>וּבְגִין כָּךְ בָּעֵי בַר נָשׁ לְשַׁבְּחָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא תָּדִיר, בְּגִין דְּאִיהוּ אִתְרָעֵי בְּשִׁירִין וְתוּשְׁבְּחָן, וּמַאן דְּיָדַע לְשַׁבְּחָא לֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא כְּדְקָא יְאוּת, קוּדְשָׁא בְּרִיךְ הוּא קַבִּיל צְלוֹתֵיהּ וְשֵׁזִיב לֵיהּ. הֲדָא הוּא דִכְתִיב (תהילים צ״א:י״ד) אֲשַׂגְּבֵהוּ כִּי יָדַע שְׁמִי וְגו' אֹרֶךְ יָמִים וְגו'.</p>"],[9520011370,"<p>פָּתַח רַבִּי יוֹסֵי וְאָמַר, (תהילים ל״ב:ז׳) אַתָּה סֵתֶר לִי מִצַּר תִּצְרֵנִי רָנִי פַלֵּט תְּסוֹבְבֵנִי סֶלָּה. אַתָּה סֵתֶר לִי, דָא קוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ סִתְרָא וּמָגֵן לְבַר נָשׁ דְּאָזִיל בְּאָרְחֵי דְאוֹרַיְיתָא, וְאִיהוּ אִסְתַּתַּר בְּצִלָּא דְגַדְפוֹי דְּלָא יָכְלִין לְאַבְאָשָׁא לֵיהּ. מִצַּר תִּצְרֵנִי, מֵעֵילָא וּמִתַּתָּא, לְעֵילָא אִית לֵיהּ לְבַר נָשׁ מָארֵי דְבָבוּ, לְתַתָּא אוּף הָכִי נָמֵי. וּמַאן אִיהוּ, דָּא יֵצֶר הָרָע, <Nonei></i>דְאִיהוּ צַר לְעֵילָא וְצַר לְתַתָּא. וְאִלְמָלֵא יֵצֶר הָרָע, לָא אִשְׁתַּכַּח מָארֵי דְּבָבוּ לְבַר נָשׁ בְּעַלְמָא. בְּגִין כָּךְ מִצַּר תִּצְרֵנִי.</p>\n<p>רָנֵי פַלֵּט תְּסוֹבְבֵנִי סֶלָה, יְסוֹבְבֵנִי סֶלָה מִבָּעֵי לֵיהּ, מַאי תְּסוֹבְבֵנִי. אִלֵּין אִינוּן שִׁירִין דְּאִית בְּהוּ דַּרְגִּין לְהַצָּלָה, תְּסוֹבְבֵנִי בְּהוּ לְשֵׁזָבָא לִי בְּאָרְחָא. וְהַאי קְרָא אִיהוּ כְּסִדְרָא וְאִיהוּ לְמַפְרֵעַ, מֵהַאי גִיסָא וּמֵהַאי גִיסָא.</p>\n<p>תָּא חֲזֵי, בְּאִלֵּין שִׁירִין וְתוּשְׁבְּחָן דְּקָאֲמַר דָּוִד אִית בְּהוֹן רָזִין וּמִלִּין עִלָּאִין בְּרָזֵי דְחָכְמְתָא, בְּגִין דְּכֻלְּהוּ בְּרוּחַ קוּדְשָׁא אִתְאֲמָרוּ. דְּהֲוָה שָׁרַא רוּחַ קוּדְשָׁא עֲלֵיהּ דְּדָוִד, וְהֲוָה אָמַר שִׁירָתָא. וּבְגִין כָּךְ כֻּלְּהוּ בְּרָזֵי דְחָכְמְתָא אִתְאֲמָרוּ.</p>\n<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (תהילים קי״ח:י״ג) דָּחֹה דְחִיתַנִי לִנְפֹּל וַיְיָ עֲזָרָנִי, דָּחֹה דְחִיתַנִי, דָּחֹה דָחוּנִי מִבָּעֵי לֵיהּ, מַאי דָּחֹה דְחִיתַנִי. אֶלָּא דָּא סִטְרָא אָחֳרָא דְּדַחְיָיא לֵיהּ לְבַר נָשׁ תָּדִיר, וּבָעֵי לְדַחְיָיא לֵיהּ וּלְאַסְטָאָה לֵיהּ מֵעִם קוּדְשָׁא בְּרִיךְ הוּא. וְדָא הוּא יֵצֶר הָרָע דְּאִשְׁתַּכַּח לְגַבֵּיהּ דְבַּר נָשׁ תָּדִיר. וּלְקֳבְלֵיהּ אַהֲדַר דָּוִד וְאָמַר דָּחֹה דְחִיתַנִי לִנְפּוֹל. בְּגִין דְּאִיהוּ הֲוָה אִשְׁתַּדַּל לְגַבֵּיהּ בְּכָל אִינוּן עַקְתִין לְאַסְטָאָה לֵיהּ מֵעִם קוּדְשָׁא בְּרִיךְ הוּא. וְעֲלֵיהּ אָמַר דָּוִד דָּחֹה דְחִיתַנִי לִנְפּוֹל בַּגֵּיהִנָּם. וַיְיָ עֲזָרָנִי דְּלָא אִתְמַסַּרְנָא בִּידָךְ. וְעַל דָּא אִית לֵיהּ לְבַר נָשׁ לְאִזְדַּהֲרָא מִנֵּיהּ, בְּגִין דְּלָא יִשְׁלוֹט עֲלֵיהּ. וְקוּדְשָׁא בְּרִיךְ הוּא כְּדֵין נָטִיר לֵיהּ בְּכָל אָרְחוֹי. דִּכְתִיב, (משלי ג׳:כ״ג) אָז תֵּלֵךְ לָבֶטַח דַרְכֶּךָ וְרַגְלֶךָ לא תִגּוֹף (משלי ד׳:י״ב) בְּלֶכְתְּךָ לֹא יֵצַר צַעֲדֶךָ וְאִם תָּרוּץ לא תִכָּשֵׁל. וּכְתִיב, (משלי ד׳:י״ח) וְאֹרַח צַדִּיקִים כְּאוֹר נֹגַהּ הוֹלֵךְ וְאוֹר עַד נְכוֹן הַיּוֹם.</p>\n<p>אָמַר רַבִּי יְהוּדָה זַכָּאִין אִינוּן יִשְׂרָאֵל דְּקוּדְשָׁא בְּרִיךְ הוּא נָטִיר לוֹן בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי. דִּכְתִיב, (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים לְעוֹלָם יִרְשׁוּ אָרֶץ. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן. (ע\"כ פרשת וישלח)</p>"],[9520011371,"<p>וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו בְּאֶרֶץ כְּנָעַן. רִבִּי חִיָּיא פָּתַח וְאָמַר, (תהלים לה) רַבּוֹת רָעוֹת צַדִּיק וּמִכֻּלָּם יַצִּילֶנוּ יְיָ. תָּא חֲזֵי, כַּמָּה מְקַטְרְגִין אִית לֵיהּ לְבַר נָשׁ מִיּוֹמָא דְּקוּדְשָׁא בְּרִיךְ הוּא יָהַב בֵּיהּ נִשְׁמָתָא (ד\"א ל\"ג לבר נש) (לאתקיימא) בְּהַאי עַלְמָא. דְּכֵיוָן דְּנָפִיק בַר נָשׁ לַאֲוִירָא דְעַלְמָא, מִיָּד אִזְדַּמַּן לְאִשְׁתַּתְּפָא בַּהֲדֵיהּ יֵצֶר הָרָע כְּמָה דְאִתְּמָר. דִּכְתִיב, (בראשית ד׳:ז׳) לַפֶּתַח חַטָּאת רוֹבֵץ וְגו'. וּכְדֵין אִשְׁתַּתַּף בַּהֲדֵיהּ יֵצֶר הָרָע.</p>\n<p>וְתָּא חֲזֵי, דְּהָכִי הוּא, דְּהָא בְּעִירֵי מִיּוֹמָא דְּאִתְיַלִּידוּ, כֻּלְּהוּ נָטְרֵי גַרְמַיְיהוּ, וְעָרְקִין מִן גּוֹ נוּרָא, וּמִן כָּל אַתְרִין בִּישִׁין. וּבַר נָשׁ, מִיָּד אָתֵי לַאֲרָמָא גַּרְמֵיהּ גּוֹ נוּרָא, בְּגִין דְּיֵצֶר הָרָע שָׁארֵי בְּגַוִּיהּ, וּמִיָּד אַסְטֵי לֵיהּ לְאָרְחָא בִישָׁא.</p>\n<p>וְאוֹקִימְנָא דִּכְתִיב, (קהלת ד׳:י״ג) טוֹב יֶלֶד מִסְכֵּן וְחָכָם מִמֶּלֶךְ זָקֵן וּכְסִיל אֲשֶׁר לא יָדַע לְהִזָּהֵר עוֹד. טוֹב יֶלֶד, דָּא הוּא יֵצֶר טוֹב דְּהוּא יֶלֶד מִיּוֹמִין זְעִירִין עִמֵּיהּ דְּבַר נָשׁ, דְּהָא מִתְּלֵיסַר שְׁנִין וָאֵילָךְ (עמיה) כְּמָה דְאִתְּמָר.</p>\n<p>מִמֶּלֶךָ זָקֵן וּכְסִיל. מִמֶּלֶךְ, דָּא הוּא יֵצֶר הָרָע דְּאִיהוּ אִקְרֵי מֶלֶךְ וְשַׁלִּיט בְּעַלְמָא עַל בְּנֵי נָשָׁא. זָקֵן וּכְסִיל, דְּאִיהוּ זָקֵן וַדַּאי, כְּמָה דְאוּקְמוּהָ, דְּכַד אִתְיְלִיד בַר נָשׁ וְנָפִיק לַאֲוִירָא דְעַלְמָא אִיהוּ <Nonei></i>אִזְדַּמַּן עִמֵּיהּ דְּבַר נָשׁ. וְעַל דָּא אִיהוּ מֶלֶךְ זָקֵן וּכְסִיל.</p>\n<p>אֲשֶׁר לא יָדַע לְהִזָּהֵר עוֹד, לְהַזְהִיר לָא כְּתִיב, אֶלָּא לְהִזָּהֵר, בְּגִין דְּאִיהוּ כְסִיל. וְעֲלֵיהּ אָמַר שְׁלֹמֹה עָלָיו הַשָׁלוֹם (קהלת ב׳:י״ד) וְהַכְּסִיל בַּחשֶׁךְ הוֹלֵךְ. דְּהָא מֵסּוּסִיתָא דְּחשֶׁךְ קָא אַתְיָא וְלֵית לֵיהּ נְהוֹרָא לְעָלְמִין.</p>\n<p>רִבִּי שִׁמְעוֹן אָמַר, תָּא חֲזֵי, כְּתִיב טוֹב יֶלֶד מִסְכֵּן וְחָכָם. מַאן יֶלֶד מִסְכֵּן, הָא אוּקְמוּהָ וְאִתְּמָר דְּאִיהוּ יֵצֶר טוֹב. אֲבָל טוֹב יֶלֶד, הֲדָא הוּא דִכְתִיב, (תהילים ל״ז:כ״ה) נַעַר הָיִיתִי גַּם זָקַנְתִּי. וְדָא הוּא נַעַר דְּאִיהוּ יֶלֶד מִסְכֵּן דְּלֵית לֵיהּ מִגַּרְמֵיהּ כְּלוּם. וְאַמַּאי אִקְרֵי נַעַר, בְּגִין דְּאִית לֵיהּ חַדְתּוּ דְסִיהֲרָא דְּמִתְחַדְּשָׁא תָּדִיר, וְתָדִיר אִיהוּ יֶלֶד מִסְכֵּן כְּמָה דְּאֲמְרָן. וְחָכָם, בְּגִין דְּחָכְמָה שַׁרְיָא בֵּיהּ.</p>\n<p>מִמֶּלֶךָ זָקֵן, דָּא הוּא יֵצֶר הָרָע כְּמָה דְאִתְּמָר. דְּהָא מִן יוֹמָא דְּהֲוָה לָא נָפַק מִמְּסָאֲבוּתֵיהּ לְעָלְמִין, וְאִיהוּ כְסִיל. דְּכָל אָרְחוֹי אִינוּן לְאֹרַח בִּישָׁא, וְאָזִיל וְסָטֵי לִבְנִי נָשָׁא וְלָא יָדַע לְאִזְדַּהֲרָא. וְאִיהוּ אָתֵי עִם בַר נָשׁ בְּתִסְקוּפִין בְּגִין לְאַסְטָאָה לוֹן מֵאֹרַח טָבָא לְאֹרַח בִּישָׁא.</p>\n<p>תָּא חֲזֵי, עַל דָּא אַקְדִים עִם בַּר נָשׁ בְּיוֹמָא דְאִתְיְלִיד בְּגִין דִּיְהֵימִין לֵיהּ. דְּהָא כַּד אָתֵי יֵצֶר טוֹב לָא יָכִיל בַר נָשׁ לִמְהֵימְנָא לֵיהּ וְדָמֵי עֲלֵיהּ כְּמָטוּלָא. כְּגַוְונָא דָא תָּנִינָן, מַאן הוּא רָשָׁע עָרוּם, דָּא הוּא מַאן דְּאַקְדִּים לְאַטְעָנָא מִלּוֹי לְקַמֵּי דַיְינָא עַד לָא יֵיתֵי חַבְרֵיהּ מָארֵי דְדִינָא. כְּמָה דְאַתְּ אָמֵר, (משלי י״ח:י״ז) צַדִּיק הָרִאשׁוֹן בְּרִיבוֹ וְגו'.</p>\n<p>כְּגַוְונָא דָא (הוא נ\"א האי) רָשָׁע עָרוּם, כְּמָה דְאַתְּ אָמֵר, (בראשית ג׳:א׳) וְהַנָּחָשׁ הָיָה עָרוּם. וְהוּא אַקְדִּים וְשָׁרֵי עִמֵּיהּ דְּבַר נָשׁ עַד לָא יֵיתֵי חַבְרֵיהּ לְאַשְׁרָאָה עֲלֵיהּ. וּבְגִין דְּאִיהוּ אַקְדִּים וְהָא אַטְעִין טַעֲנָתֵיהּ עִמֵּיהּ, כַּד אָתֵי חַבְרֵיהּ דְּאִיהוּ יֵצֶר הַטּוֹב, אַבְאִישׁ לֵיהּ לְבַר נָשׁ בַּהֲדֵיהּ וְלָא יָכִיל לְזָקְפָא רֵישֵׁיהּ, כְּאִילּוּ אַטְעִין עַל כִּתְפֵיהּ כָּל מָטוֹלִין דְּעַלְמָא. בְּגִין הַהוּא רָשָׁע עָרוּם דְאַקְדִּים עִמֵּיהּ. וְעַל דָּא אָמַר שְׁלמֹה (קהלת ט׳:ט״ז) וְחָכְמַת הַמִּסְכֵּן בְּזוּיָה וּדְבָרָיו אֵינָם נִשְׁמָעִים, בְּגִין דְּהָא אַקְדִים אָחֳרָא.</p>\n<p>וְעַל דָּא כָּל דַיְינֵי דְּקַבִּיל מִבַּר נָשׁ מִלָּה עַד לָא יֵיתֵי חַבְרֵיהּ, כְּאִילּוּ מְקַבֵּל עֲלֵיהּ טַעֲוָוא אָחֳרָא לִמְהֵימְנוּתָא. אֶלָּא (משלי י״ח:י״ז) וּבָא רֵעֵהוּ וַחֲקָרוֹ, וְדָא הוּא אֹרַח דְּבַר נָשׁ זַכָּאָה, דְּהָא בַר נָשׁ זַכָּאָה דָּא הוּא, דְּלָא הֵימִין לְהַהוּא רָשָׁע עָרוּם דְּיֵצֶר הָרָע, עַד דְּיֵיתֵי חַבְרֵיהּ דְּאִיהוּ יֵצֶר טוֹב. וּבְגִין דָא בְּנֵי נָשָׁא אִינוּן כָּשְׁלִין לְעַלְמָא דְאָתֵי.</p>\n<p>אֲבָל הַהוּא זַכָּאָה דְּאִיהוּ דָּחִיל לְמָארֵיהּ, כַּמָּה בִּישִׁין סָבִיל בְּהַאי עַלְמָא בְּגִין דְּלָא יְהֵימִין וְלָא יִשְׁתַּתַּף בְּהַהוּא יֵצֶר הָרָע. וְקוּדְשָׁא בְּרִיךְ הוּא שֵׁזִיב לֵיהּ מִכֻּלְּהוּ, הֲדָא הוּא דִכְתִיב, (תהלים לה) רַבּוֹת רָעוֹת צַדִּיק וּמִכֻּלָּם יַצִּילֶנוּ יְיָ. רַבּוֹת רָעוֹת לַצַּדִּיק לָא כְּתִיב, אֶלָּא צַדִּיק. בְּגִין דְּקוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בֵּיהּ. וּבְגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא אִתְרָעֵי בְּהַהוּא בַר נָשׁ וְשֵׁזִיב לֵיהּ מִכֹּלָּא בְּהַאי עַלְמָא וּבְעַלְמָא דְאָתֵי, זַכָּאָה חוּלָקֵיהּ.</p>\n<p>תָּא חֲזֵי, כַּמָּה בִּישִׁין עָבְרוּ עֲלֵיהּ דְּיַעֲקֹב, בְּגִין דְּלָא יִתְדַּבַּק בְּהַהוּא יֵצֶר הָרָע וְיִתְרְחַק מֵחוּלָקֵיהּ. וּבְגִין כָּךְ סָבִיל כַּמָּה עוֹנְשִׁין כַּמָּה בִּישִׁין וְלָא שָׁקִיט. פָּתַח וְאָמַר, (איוב ג׳:כ״ו) לא שָׁלַוְתִּי וְלֹא שָׁקַטְתִּי וְלֹא נַחְתִּי וַיָּבֹא רֹגֶז. תָּא חֲזֵי, כַּמָּה בִּישִׁין סָבְלִין צַדִּיקַיָא בְּהַאי עַלְמָא. בִּישִׁין עַל בִּישִׁין, כְּאֵבִין עַל כְּאֵבִין. בְּגִין לְמִזְכֵּי לוֹן לְעַלְמָא דְאָתֵי.</p>\n<p>יַעֲקֹב כַּמָּה סָבִיל בִּישִׁין עַל בִּישִׁין תָּדִיר, כְּמָה דְאַתְּ אָמֵר לֹא שָׁלַוְתִּי, בְּבֵיתָא דְלָבָן, וְלָא יָכִילְנָא לְאִשְׁתְּזָבָא מִנֵּיהּ. וְלא שָׁקַטְתִּי, מֵעֵשָׂו. מֵהַהוּא צַעֲרָא דְּצִעֵר לִי הַהוּא מְמַנָּא דִילֵיהּ, וּלְבָתַר דְּחִילוּ דְעֵשָׂו. וְלֹא נַחְתִּי, מִן דִּינָה וּמִן שְׁכֶם.</p>\n<p>וַיָּבֹא רֹגֶז, דָּא רוּגְזָא וְעִרְבּוּבְיָא דְיוֹסֵף דְּאִיהוּ קַשְׁיָא מִכֻּלְּהוּ, מִגּוֹ רְחִימוּתָא דְיַעֲקֹב לְגַבֵּי דְיוֹסֵף דְּאִיהוּ רָזָא דִבְרִית, עָאל בְּמִצְרַיִם. בְּגִין דִּלְבָתַר כְּתִיב, (שמות ו׳:ה׳) וָאֶזְכֹּר אֶת בְּרִיתִי, לְאִשְׁתַּכָּחָא שְׁכִינְתָּא (נ\"א שמש) תַּמָּן בַּהֲדֵיהּ.</p>\n<p>וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו בְּאֶרֶץ כְּנָעַן, <Nonei></i>רִבִּי יוֹסֵי פָּתַח, (ישעיהו נ״ז:א׳) הַצַּדִּיק אָבַד וְאֵין אִישׁ שָׂם עַל לֵב וְאַנְשֵׁי חֶסֶד נְאֱסָפִים בְּאֵין מֵבִין כִּי מִפְּנֵי הָרָעָה נְאֱסַף הַצַּדִּיק. הַצַּדִּיק אָבַד, בְּזִמְנָא דְקוּדְשָׁא בְּרִיךְ הוּא אַשְׁגַּח בְּעַלְמָא וְלָא הֲוֵי עַלְמָא כְּדְקָא יְאוּת, וְאִזְדַּמַּן דִּינָא לְשַׁרְיָיא עַל עַלְמָא. כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא נָטִיל זַכָּאָה דְּאִשְׁתַּכַּח בֵּינַיְיהוּ, בְּגִין דְּיִשְׁרֵי דִּינָא עַל כֻּלְּהוּ אָחֳרָנִין, וְלָא יִשְׁתַּכַּח מַאן דְּיָגִין עֲלַיְיהוּ.</p>\n<p>דְּהָא כָּל זִמְנָא דְּזַכָּאָה שָׁארֵי בְּעַלְמָא, דִּינָא לָא יָכִיל לְשַׁלְטָאָה עַל עַלְמָא. מְנָלָן מִמּשֶׁה, דִּכְתִיב, (תהילים ק״ו:כ״ג) וַיֹּאמֶר לְהַשְׁמִידָם לוּלֵי משֶׁה בְחִירוֹ עָמַד בַּפֶּרֶץ לְפָנָיו וְגו'. וּבְגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא נָטִיל לְזַכָּאָה מִבֵּינַיְיהוּ וְסַלִּיק לֵיהּ מֵעַלְמָא, וּכְדֵין אִתְפְּרַע וְגָבֵי דִילֵיהּ. סוֹפֵיהּ דִּקְרָא, כִּי מִפְּנֵי הָרָעָה נְאֱסַף הַצַּדִּיק. עַד דְּלָא יֵיתֵי רָעָה לְשַׁלְטָאָה עַל עַלְמָא נֶאֱסַף הַצַּדִּיק. (ד\"א כי מפני הרעה נאסף עד לא ישלוט הרעה בעלמא) דָּבָר אַחֵר כִּי מִפְּנֵי הָרָעָה, דָּא יֵצֶר הָרָע.</p>\n<p>תָּא חֲזֵי, יַעֲקֹב שְׁלִימוּ דַאֲבָהָן הֲוָה וְאִיהוּ קָאִים לְקָיְימָא בְּגָלוּתָא. אֲבָל מִגּוֹ דְּאִיהוּ צַדִּיק אִתְעַכַּב דִּינָא דְּלָא שָׁלְטָא בְּעַלְמָא. דְּהָא כָּל יוֹמֵי דְיַעֲקֹב לָא שָׁרָא דִּינָא עַל עַלְמָא, וְכַפְנָא אִתְבַּטְלַת.</p>\n<p>וְאוּף הָכִי בְּיוֹמוֹי דְיוֹסֵף דְּאִיהוּ דִּיוּקְנָא דְּאֲבוֹי (כיון דאיהו מת מיד). לָא שְׁרָא גָלוּתָא (דינא על עלמא). בְּגִין דְּאִיהוּ אָגִין עֲלַיְיהוּ כָּל יוֹמוֹי, כֵּיוָן דְּאִיהוּ מֵת, מִיָּד שָׁרָא עֲלַיְיהוּ גָלוּתָא. כְּמָה דְאַתְּ אָמֵר (שמות א׳:י״ד) וַיָּמָת יוֹסֵף וְגו', וְסָמִיךְ לֵיהּ הָבָה נִתְחַכְּמָה לוֹ. וּכְתִיב וַיְמָרֲרוּ אֶת חַיֵּיהֶם בַּעֲבוֹדָה קָשָׁה בְּחֹמֶר וּבִלְבֵנִים וְגו'.</p>\n<p>כְּגַוְונָא דָא בְּכָל אֲתַר דְּשַׁרְיָא זַכָּאָה (על) בְּעַלְמָא בְּגִינֵיהּ קוּדְשָׁא בְּרִיךְ הוּא יָגִין עַל עַלְמָא, וְכָל זִמְנָא דְּאִיהוּ קַיָּים, דִּינָא לָא שָׁרְיָא עַל עַלְמָא וְהָא אִתְּמָר.</p>\n<p>תָּא חֲזֵי, וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו, מַאי מְגוּרֵי אָבִיו, כְּמָה דְאַתְּ אָמֵר, (ירמיהו ו׳:כ״ה) מָגוֹר מִסָבִיב, דְּכָל יוֹמוֹי הֲוָה דָחִיל וְהֲוָה בִּדְחִילוּ: וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו. רִבִּי אֶלְעָזָר אָמַר, דְאִתְקַשַּׁר וְיָתִיב בְּהַהוּא אֲתַר דְּאִתְאֲחִיד בַּחשֶׁךְ. אֶרֶץ מְגוּרֵי אָבִיו דַּיְיקָא, בְּאֶרֶץ כְּנָעַן, אִתְקַשַּׁר אַתְרָא בְּאַתְרֵיהּ. מְגוּרֵי אָבִיו, דָּא דִינָא קַשְׁיָא. בְּאֶרֶץ מְגוּרֵי אָבִיו, כְּמָה דְאִתְּמָר הַהוּא דִינָא רַפְיָא דְּאִיהִי אֶרֶץ, דְּאִתְאַחִיד מִן דִּינָא קַשְׁיָא וּבֵיהּ אִתְיַשֵּׁב יַעֲקֹב וְאִתְאַחִיד בֵּיהּ, (וההיא ארץ איהי אספקלריא דלא נהרא):</p>"],[9520011372,"<p>אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף וְגו', בָּתַר דְּאִתְיַשַּׁב יוֹסֵף בְּיַעֲקֹב וְאִזְדַּוַּוג שִׁמְשָׁא בְּסִיהֲרָא, כְּדֵין שָׁרָא לְמֶעְבַּד תּוֹלְדוֹת, וּמַאן אִיהוּ דְּעֲבִיד תּוֹלְדוֹת, אַהֲדַר וְאָמַר יוֹסֵף, דְּהָא הַהוּא נָהָר דְּנָגִיד וְנָפִיק אִיהוּ עָבִיד תּוֹלְדוֹת בְּגִין דְּלָא פָּסְקִין מֵימוֹי לְעָלְמִין, וְאִיהוּ עָבִיד תּוֹלְדוֹת בְּהַאי אֶרֶץ וּמִנֵּיהּ נָפְקִין תּוֹלְדוֹת לְעַלְמָא.</p>\n<p>דְּהָא שִׁמְשָׁא אַף עַל גַּב דְּאִתְקַרַב בְּסִיהֲרָא לָא עָבִיד אִיבִּין בַּר הַהוּא דַרְגָּא דְּאִקְרֵי צַדִּי\"ק, וְיוֹסֵף אִיהוּ דַרְגָּא דְיַעֲקֹב לְמֶעְבַּד אִיבִּין וְלְאֲפָקָא תּוֹלָדִין לְעַלְמָא, וּבְגִין כָּךְ כְּתִיב אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף.</p>\n<p>אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף, כָּל מַאן דְּהֲוָה מִסְתַּכֵּל בְּדִיוּקְנָא דְיוֹסֵף הֲוָה אָמַר דְּדָא הוּא דִיוּקְנָא דְיַעֲקֹב. תָּא חֲזֵי, דִּבְכֻלְּהוּ בְּנֵי יַעֲקֹב לָא כְּתִיב אֵלֶּה תּוֹלְדוֹת יַעֲקֹב רְאוּבֵן, בַּר יוֹסֵף, דְּדִיוּקְנִיהּ דָמֵי לְדִיוּקְנָא דְּאֲבוֹי.</p>\n<p>בֶּן שְׁבַע עֶשְׂרֵה שָׁנָה. אָמַר רִבִּי אַבָּא, רָמַז לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, דְּהָא כַּד אִתְאֲבִיד מִנֵּיהּ יוֹסֵף בֶּן שְׁבַע עֶשְׂרֵה שְׁנִין הֲוָה. וְכָל אִינוּן יוֹמִין דְּאִשְׁתָּאֲרוּ דְּלָא חָמָא לֵיהּ לְיוֹסֵף הֲוָה בָּכֵי עַל אִינוּן שְׁבַע עֶשְׂרֵה שְׁנִין. וּכְמָּה דְּהֲוָה בָּכֵי עֲלֵיהּ, קוּדְשָׁא בְּרִיךְ הוּא יָהַב לֵיהּ שְׁבַע עֶשְׂרֵה שְׁנִין אָחֳרָנִין דְּאִתְקַיֵּים בְּאַרְעָא דְמִצְרַיִם בְּחֵדוּ בִּיקָרָא וּבִשְׁלִימוּ דְּכֹלָּא. בְּרֵיהּ יוֹסֵף הֲוָה מַלְכָּא, וְכָל בְּנוֹי קַמֵּיהּ הֲווּ, אִינוּן שְׁבַע עֶשְׂרֵה שְׁנִין הֲווּ חַיִּין לְגַבֵּיהּ. וּבְגִין כָּךְ בֶּן שְׁבַע עֶשְׂרֵה שָׁנָה הֲוָה אִיהוּ, כַּד אִתְאֲבִיד מִנֵּיהּ.</p>"],[9520011373,"<p>רִבִּי חִיָּיא פָּתַח וְאָמַר, (איוב לה) לָכֵן אַנְשֵׁי לֵבָב שִׁמְעוּ לִי חָלִלָה לָאֵל מֵרְשַׁע וְשַׁדַּי מֵעָוֶל. כִּי פֹעַל <Nonei></i>אָדָם יְשַׁלֶּם לוֹ וּכְאֹרַח אִישׁ יַמְצִאֶנּוּ. תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, עֲבַד לֵיהּ עַל דִּינָא, וְעַל דִּינָא אִתְקַיַּים. וְכָל עוֹבָדִין דְּעַלְמָא אִינוּן קָיְימִין בְּדִינָא. בַּר דְּקוּדְשָׁא בְּרִיךְ הוּא בְּגִין לְקַיְימָא עַלְמָא וְלָא יִתְאֲבִיד, פָּרִישׂ עֲלֵיהּ רַחֲמֵי, וְאִינוּן רַחֲמֵי מְעַכְּבֵי לְדִינָא דְּלָא יִשְׁתְּצֵי עַלְמָא, וְעַל רַחֲמֵי אִתְנַהִיג עַלְמָא וְאִתְקְיַּים בְּגִינִיהּ.</p>\n<p>וְאִי תֵימָא דְּקוּדְשָׁא בְּרִיךְ הוּא עָבִיד דִּינָא בְּבַר נָשׁ בְּלָא דִינָא. הָא אִתְּמָר, דְּכַד דִּינָא שַׁרְיָא עֲלֵיהּ דְּבַר נָשׁ כַּד אִיהוּ זַכָּאָה. בְּגִין רְחִימוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא בֵּיהּ אִיהִי, כְּמָה דְאִתְּמָר. דְּהָא קוּדְשָׁא בְּרִיךְ הוּא רָחִים עֲלֵיהּ בִּרְחִימוּ לְקָרְבָא לֵיהּ לְגַבֵּיהּ, מְתַבַּר גּוּפָא בְּגִין לְשַׁלְטָאָה נִשְׁמָתָא, וּכְדֵין אִתְקְרִיב בַּר נָשׁ לְגַבֵּיהּ בִּרְחִימוּ כְּדְקָא יְאוּת. וְנִשְׁמָתָא שָׁלְטָא וְגוּפָא אִתְחַלָּשׁ.</p>\n<p>וּבַעְיָא גּוּפָא חוּלְשָׁא וְנַפְשָׁא תַּקִּיפָא דְּאִתְתַּקַּף בִּתְקִיפוּ, וּכְדֵין אִיהוּ רְחִימָא דְקוּדְשָׁא בְּרִיךְ הוּא. כְּמָה דַאֲמְרוּ חַבְרַיָיא, יָהַב קוּדְשָׁא בְּרִיךְ הוּא לַצַּדִּיק צַעֲרָא בְּעַלְמָא דֵין, בְּגִין לְמִזְכֵּי לֵיהּ לְעַלְמָא דְאָתֵי.</p>\n<p>וְכַד נִשְׁמָתָא חָלְשָׁא וְגוּפָא תַקִיפָא, אִיהוּ שָׂנְאֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא דְּלָא אִתְרָעֵי בֵּיהּ, לָא יָהִיב לֵיהּ צַעֲרָא בְּהַאי עַלְמָא אֶלָּא אוֹרְחוֹי מִתְתַּקְנָן וְהוּא בִּשְׁלִימוּ יַתִּיר. בְּגִין דְּאִי עָבַד צְדָקָה אוֹ טִיבוּ קוּדְשָׁא בְּרִיךְ הוּא מְשַׁלֵּם לֵיהּ אַגְרֵיהּ בְּהַאי עַלְמָא וְלָא יֶהֱוֵי לֵיהּ חוּלַק בְּהַהוּא עַלְמָא. וְדָא הוּא דְּתִרְגֵּם אוּנְקְלוּס (דברים ז׳:י׳) וּמְשַׁלֵּם לְשׂוֹנְאָיו וְגו', וּמְשַׁלֵּם לְשַׂנְאוֹהִי טַבְוָון דְּאִינוּן וְגו' (איהו). וּבְגִין כָּךְ הַהוּא זַכָּאָה דְּאִתְבַּר תָּדִיר אִיהוּ רְחִימָא דְקוּדְשָׁא בְּרִיךְ הוּא, וְהַנֵּי מִילֵי כַּד בָּדַק וְלָא אַשְׁכַּח חוֹבָא בִּידֵיהּ דְּאִתְעַנַּשׁ עֲלֵיהּ.</p>\n<p>הָכָא אִית לְאִסְתַּכָּלָא בְּכַמָּה סִטְרִין. חַד, דְּהָא חָמִינָן דִּשְׁכִינְתָּא לָא שַׁרְיָא בְּאֲתַר עֲצִיבוּ אֶלָּא בְּאֲתַר דְּאִית בֵּיהּ חֶדְוָה. אִי חֶדְוָה לֵית בֵּיהּ, לָא שַׁרְיָא שְׁכִינְתָּא בְּהַהוּא אֲתַר. כְּמָה דְאַתְּ אָמֵר, (מלכים ב ג׳:ט״ו) וְעַתָּה קְחוּ לִי מְנַגֵּן וְהָיָה כְנַגֵּן הַמְנַגֵּן וַתְּהִי עָלָיו (יד יי) רוּחַ אֱלהִים, דְּהָא שְׁכִינְתָּא וַדַּאי לָא שַׁרְיָא בְּאֲתַר עֲצִיבוּ. מְנָלָן מִיַּעֲקֹב. דִּבְגִין דְּהֲוָה עָצִיב עֲלֵיהּ דְּיוֹסֵף אִסְתַּלְקַת שְׁכִינְתָּא מִנֵּיהּ, כֵּיוָן דְּאָתָא לֵיהּ חֶדְוָה דִּבְשׂוֹרָה דְיוֹסֵף מִיָּד וַתְּחִי רוּחַ יַעֲקֹב אֲבִיהֶם. הָכָא בְּהַאי זַכָּאָה דְּאִתָּבַר כֵּיוָן דְּאִיהוּ חֲלָשָׁא וְאִתָּבַר בְּמַכְאוֹבִין, אָן הוּא חֶדְוָה דְּהָא אִיהוּ בַּעֲצִיבוּ וְלֵית עִמֵּיהּ חֶדְוָה כְּלָל.</p>\n<p>וְחַד דְּהָא חָמִינָן כַּמָּה רְחִימִין הֲווּ צַדִּיקַיָא קַמֵי קוּדְשָׁא בְּרִיךְ הוּא וְלָא אִתָּבְרוּ בְּמַרְעִין וְלָא בְּמַכְאוֹבִין וְלָא אִתְחַלַּשׁ גּוּפָא דִלְהוֹן לְעָלְמִין. אַמַּאי לָאו אִלֵּין כְּאִלֵּין, דְּאִלֵּין אִתָּבְרוּ וְאִלֵּין קָיְימֵי בְּגוּפַיְיהוּ כְּדְקָא יְאוּת.</p>\n<p>וְאִם תֹּאמַר דְּהָא אִלֵּין דְּקָיְימוּ בְּקִיּוּמָא כְּדְקָא יְאוּת, בְּגִין דְּאִינוּן צַדִּיקֵי בְּנֵי צַדִּיקֵי אִינְהוּ, כְּמָה דְאוּקְמוּהָ. וְאִלֵּין אָחֳרָנִין צַדִּיקֵי וְלָאו בְּנִי צַדִּיקֵי, הָא קָא חָמֵינָן צַדִּיקֵי בְּנֵי צַדִּיקֵי, דְּהָא אֲבוֹי דְּדֵין זַכָּאָה בַּר זַכָּאָה, וְאִיהוּ זַכָּאָה. אַמַּאי אִתָּבַר גּוּפֵיהּ בְּמַכְאוֹבִין וְכָל יוֹמוֹי בְּצַעֲרָא.</p>\n<p>אֶלָּא הָכָא רָזָא אִיהוּ, דְּהָא כָּל עוֹבָדוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא בִּקְשׁוֹט וּזְכוּ (איוב לה) כִּי פֹעַל אָדָם יְשַׁלֶּם לוֹ וּכְאֹרַח אִישׁ יַמְצִיאֶנּוּ. אַשְׁכַּחְנָא בְּסִפְרֵי קַדְמָאֵי רָזָא חָדָא, וּלְגַבֵּיהּ רָזָא אָחֳרָא חַד דְּאִיהוּ תְּרֵין, דְּהָא אִית זִמְנִין דְּסִיהֲרָא אִיהִי בִּפְגִימוּ וְשַׁרְיָא בְּדִינָא וְשִׁמְשָׁא לָא אִשְׁתַּכַּח גַּבָּה. וּבְכָל זִמְנָא וּבְכָל שַׁעְתָּא אִית לָהּ לְאֲפָקָא נִשְׁמָתִין בִּבְנֵי נָשָׁא כְּמָה דְלָקְטָא בְּקַדְמִיתָא, וַאֲפִיקַת לוֹן הַשְׁתָּא בְּזִמְנָא דְאִיהִי קָיְימָא בְּדִינָא. הַאי מַאן דְּנָקִיט לָהּ בְּהַהוּא זִמְנָא לֶיהֱוֵי תָּדִיר בִּגְרִיעוּתָא, וּמִסְכֵּנוּתָא אָזְלָא לְגַבֵּיהּ, וְאִתָּבַר תָּדִיר בְּדִינָא כָּל יוֹמוֹי דְבַר נָשׁ בֵּין חַיָּיבָא בֵּין זַכָּאָה. בַּר דִּצְלוֹתָא בָּטִיל כָּל גִּזְרֵי דִינִין וְיָכִיל לְסַלְקָא בִּצְלוֹתָא.</p>\n<p>וְהַהוּא זִמְנָא דְּקָיְימָא הַהוּא דַרְגָּא בִּשְׁלִימוּ, וְהַהוּא נָהָר דְּנָגִיד וְנָפִיק אִשְׁתַּמַּשׁ בָּהּ, כְּדֵין הַהוּא נִשְׁמָתָא דְּנָפְקַת וְאִתְדַּבְּקַת בֵּיהּ בְּהַהוּא בַר נָשׁ, הַהוּא בַּר נָשׁ אִשְׁתַּלִּים בְּכֹלָּא בְּעוּתְרָא בִּבְנִין בִּשְׁלִימוּ דְּגוּפָא.</p>\n<p>וְכֹלָּא בְּגִין <Nonei></i>הַהוּא מַזָּלָא דְּנָגִיד וְנָפִיק וְאִתְחַבַּר בְּהַהוּא דַרְגָּא לְאִשְׁתַּלְּמָא בֵּיהּ וּלְאִתְבָּרְכָא מִנֵּיהּ, וְעַל דָּא כֹּלָּא בְּמַזָּלָא תַּלְיָא מִלְּתָא. וְעַל דָּא תָּנִינָן, בָּנִי חַיֵּי וּמְזוֹנֵי לָאו בִּזְכוּתָא תַּלְיָא מִלְּתָא אֶלָּא בְּמַזָּלָא תַּלְיָא מִלְּתָא. דְּהָא בִּזְכוּתָא לָאו אִיהוּ אֶלָּא עַד דְּאִתְמַלְּיָא וְאִתְנְהִיר מִן מַזָּלָא.</p>\n<p>וּבְגִין כָּךְ כָּל אִינוּן דְּאִתָּבְרוּ בְּהַאי עַלְמָא וְאִינוּן זַכָּאי קְשׁוֹט, כֻּלְּהוּ אִתָּבְרוּ בְּהַאי עַלְמָא וְאִתְדָּנוּ בְּדִינָא. מַאי טַעְמָא, בְּגִין דְּהַהִיא נַפְשָׁא גָּרְמָא לְהוּ, וְעַל דָּא חָיִיס עֲלַיְיהוּ קוּדְשָׁא בְּרִיךְ הוּא לְעַלְמָא דְאָתֵי.</p>\n<p>רִבִּי אֶלְעָזָר אָמַר, כָּל מַה דְּעָבִיד קוּדְשָׁא בְּרִיךְ הוּא בְּדִינָא אִיהוּ, בְּגִין לְדַּכָּאָה לְהַהִיא נַפְשָׁא לְאַיְיתָאָה לָהּ לְעַלְמָא דְאָתֵי. (ובגין כך קודשא בריך הוא כל עובדוי) (נ\"א בגין דכל עובדוי דקודשא בריך הוא) אִינוּן בְּדִינָא וּקְשׁוֹט. וּבְגִין לְאַעֲבָרָא מִנֵּיהּ הַהוּא זוּהֲמָא דְּקַבִּילַת בְּהַאי עַלְמָא וְעַל דָּא אִתָּבַר הַהוּא גּוּפָא וְאִתְדְּכִיאַת נַפְשָׁא. וּבְגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא עָבִיד לְהַהוּא זַכָּאָה דְּיִסְבּוֹל יִסּוּרִין וּמַכְאוֹבִין בְּהַאי עַלְמָא וְיִתְנְקֵי מִכֹּלָּא וְיִזְכֶּה לְחַיֵּי עָלְמָא. וְעַל דָּא כְּתִיב (תהילים י״א:ה׳) יְיָ צַדִּיק יִבְחָן. וַדַּאי, וְהָא אִתְּמָר.</p>"],[9520011374,"<p>רִבִּי שִׁמְעוֹן פָּתַח, (ויקרא כ״א:כ״ג) אַךְ אֶל הַפָּרֹכֶת לֹא יָבֹא וְאֶל הַמִּזְבֵּחַ לא יִגָּשׁ כִּי מוּם בּוֹ וְלֹא יְחַלֵּל אֶת מִקְדָּשַׁי כִּי אֲנִי יְיָ מְקַדְּשׁוֹ. אַךְ אֶל הַפָּרֹכֶת לא יָבֹא. תָּא חֲזֵי, בְּהַהִיא שַׁעְתָּא דְּהַהוּא נָהָר דְּנָגִיד וְנָפִיק אַפִּיק כָּל אִינוּן נִשְׁמָתִין וְאִתְעֲבָרַת נוּקְבָא, כֻּלְּהוּ קָיְימִין לְגוֹ בְּקוּרְטָא דִלְגוֹ בְּסִיטוֹ קוּרְטָא.</p>\n<p>וְכַד סִיהֲרָא אִתְפְּגִים בְּהַהוּא סִטְרָא דְּחִוְיָא בִישָׁא, כְּדֵין כָּל אִינוּן נִשְׁמָתִין דְּנָפְקִין, אַף עַל גַּב דְּכֻלְּהוּ דַּכְיָין וְכֻלְּהוּ קַדִּישִׁין, הוֹאִיל וְנָפְלוּ בִּפְגִימוּ. בְּכָל אִינוּן אַתְרֵי דְמָטוּ אִינוּן נִשְׁמָתִין כֻּלְּהוּ אִתָּבְרוּ וְאִתְפְּגִימוּ בְּכַמָּה צַעֲרִין בְּכַמָּה כְּאֵבִין, וְאִילֵּין אִינוּן (נשמתין ואתרין) (נ\"א נשמתין דאתרין דפגימו) דְּאִתְרְעֵי בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא לְבָתַר דְּאִתָּבְרוּ, וְאַף עַל גַּב דְּנִשְׁמָתִין בַּעֲצִיבוּ וְלָא בְּחֶדְוָון.</p>\n<p>רָזָא דְמִלָּה שַׁרְיָין כְּגַוְונָא דִלְעֵילָא גּוּפָא אִתְפְּגִים, וְנִשְׁמָתָא לְגוֹ כְּגַוְונָא דִלְעֵילָא, וַדַּאי כְּגַוְונָא דְּדָא, וּבְגִין כָּךְ אִלֵּין אִינוּן דְּבַעְיָין לְחַדְתוּתֵי בְּחַדְתוּתָא דְסִיהֲרָא, וְעַל אִלֵּין כְּתִיב, (ישעיהו ס״ו:כ״ג) וְהָיָה מִדֵּי חֹדֶשׁ בְּחָדְשׁוֹ וּמִדֵּי שַׁבָּת בְּשַׁבַּתּוֹ יָבֹא כָל בָּשָׂר לְהִשְׁתַּחֲוֹת לְפָנַי אָמַר יְיָ. כָּל בָּשָׂר וַדַּאי, דְּאִלֵּין יִתְחַדְתוּן בְּכֹלָּא. וּבָעְיָין לְחַדְתוּתֵי בְּחַדְתוּתָא דְסִיהֲרָא.</p>\n<p>וְאִלֵּין אִינוּן בְּשׁוּתָּפוּתָא חָדָא בְּסִיהֲרָא פְּגִימִין בְּהַהוּא פְּגִימוּ דִילָהּ, וּבְגִין כָּךְ אִיהִי שַׁרְיָא בְּגַוַּויְיהוּ תָּדִיר דְּלָא שָׁבְקָא לוֹן כְּמָה דְאַתְּ אָמֵר, (ישעיהו נ״ז:ט״ו) וְאֶת דַּכָּא וּשְׁפַל רוּחַ. וּכְתִיב, (תהלים לה) קָרוֹב יְיָ לְנִשְׁבְּרֵי לֵב, לְאִינוּן דְּסָבְלֵי עִם סִיהֲרָא הַהוּא פְּגִימוּ, אִינוּן קְרֵיבִין לָהּ תָּדִיר. וְעַל דָּא לְהַחֲיוֹת לֵב נִדְכָּאִים, בְּאִינוּן חַיִּים דְּאַתְיָין לָהּ לְאִתְחַדְתָא יְהֵא לוֹן חוּלְקֵהוֹן, אִינוּן דְּסָבְלֵי עִמָּהּ יִתְחַדְתוּן עִמָּהּ.</p>\n<p>וְאִלֵּין אִקְרוּן יִסּוּרִין שֶׁל אַהֲבָה, שֶׁל אַהֲבָה אִינוּן וְלָא מִנֵּיהּ דְּהַהוּא בַר נָשׁ. שֶׁל אַהֲבָה, אִינוּן דְּאִתְפַּגִּים נְהוֹרָא שֶׁל אַהֲבָה זוּטָא דְּאִתְדַּחְיָיא מֵאַהֲבָה רַבָּה. בְּגִין כָּךְ אִלֵּין אִינוּן חֲבֵרִים מְשׁוּתָּפִים בַּהֲדָהּ. זַכָּאָה חוּלַקְהוֹן בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי, דְּאִינוּן זָכוּ לְהַאי לְמֶהוֵי חֲבֵרִים בַּהֲדָהּ, עֲלַיְיהוּ כְּתִיב, (תהילים קכ״ב:ח׳) לְמַעַן אַחַי וְרֵעָי וְגו'.</p>"],[9520011375,"<p>פָּתַח וְאָמַר, (ישעיהו נ״ב:י״ג) הִנֵּה יַשְׂכִּיל עַבְדִּי יָרוּם וְנִשָּׂא וְגָבַהּ מְאֹד. זַכָּאָה חוּלַקְהוֹן דְּצַדִּיקַיָיא דְּקוּדְשָׁא בְּרִיךְ הוּא גָּלֵי לוֹן אָרְחֵי דְאוֹרַיְיתָא לְמֵהַךְ בְּהוּ. תָּא חֲזֵי, הַאי קְרָא רָזָא עִלָּאָה אִיהוּ, הִנֵּה יַשְׂכִּיל עַבְדִּי וְאוּקְמוּהָ. אֲבָל תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, עֲבַד לָהּ לְסִיהֲרָא וְאַזְעַר לָהּ נְהוֹרָהָא דְּהָא לֵית לָהּ מִגַרְמָהּ כְּלוּם. וּבְגִין דְּאַזְעִירַת גַּרְמָהּ, אִתְנַהֲרָא בְּגִין שִׁמְשָׁא, וּבְתוּקְפָא דִּנְהוֹרִין עִלָּאִין.</p>\n<p>וּבְזִמְנָא דְּהֲוָה בֵּי מַקְדְּשָׁא קַיָּים, יִשְׂרָאֵל הֲווּ מִשְׁתַּדְּלִין בְּקוּרְבָּנִין וְעִלָּוָון וּפוּלְחָנִין, דְּהֲווּ עָבְדִין כַּהֲנִי וְלֵיוָאֵי וְיִשְׂרְאֵלֵי בְּגִין לְקָשְׁרָא קִשְׁרִין וּלְאַנְהָרָא נְהוֹרִין.</p>\n<p>וּלְבָתַר דְּאִתְחָרַב בֵּי מַקְדְּשָׁא אִתְחַשַּׁךְ נְהוֹרָא, וְסִיהֲרָא לָא אִתְנְהִירַת מִן שִׁמְשָׁא, וְשִׁמְשָׁא <Nonei></i>אִסְתַּלַּק מִנָּהּ וְלָא אִתְנְהָרָא, וְלֵית לָךְ יוֹמָא דְּלָא שָׁלְטָא בֵּיהּ לְוָוטִין וְצַעֲרִין וּכְאֵבִין כְּמָה דְאִתְּמָר.</p>\n<p>וּבְהַהוּא זִמְנָא דְּמְטֵי זִמְנָא דְּסִיהֲרָא לְאִתְנַהֲרָא, מַה כְּתִיב הִנִּה יַשְׂכִּיל עַבְדִּי, עֲלֵיהּ דְּסִיהֲרָא אִתְּמָר הִנֵּה יַשְׂכִּיל עַבְדִּי דָּא הוּא רָזָא דִמְהֵימְנוּתָא. הִנֵּה יַשְׂכִּיל, דְּאִתְעַר אִתְעֲרוּתָא לְעֵילָא כְּמַאן דְאָרַח רֵיחָא וְאָתֵי לְאִתְעָרָא וּלְאִסְתַּכָּלָא. יָרוּם, מִסִּטְרָא דִנְהוֹרָא עִלָּאָה דְּכָל נְהוֹרִין.</p>\n<p>יָרוּם, כְּמָה דְאַתְּ אָמֵר, (ישעיהו ל׳:י״ח) וְלָכֵן יָרוּם לְרַחֶמְכֶם. וְנִשָּׂא, מִסִּטְרָא דְאַבְרָהָם. וְגָבַהּ, מִסִּטְרָא דְיִצְחָק. מְאֹד, מִסִּטְרָא דְיַעֲקֹב. וְאַף עַל גַּב דְּאוּקְמוּהָ, וְכֹלָּא חַד בְּרָזָא דְחָכְמְתָא.</p>\n<p>וּבְהַהוּא זִמְנָא יִתְעַר קוּדְשָׁא בְּרִיךְ הוּא אִתְעֲרוּתָא עִלָּאָה לְאַנְהָרָא לָהּ לְסִיהֲרָא כְּדְקָא יְאוּת כְּמָה דְאַתְּ אָמֵר, (ישעיהו ל׳:כ״ו) וְהָיָה אוֹר הַלְּבָנָה כְּאוֹר הַחַמָּה וְאוֹר הַחַמָּה יִהְיֶה שִׁבְעָתַיִם כְּאוֹר שִׁבְעַת הַיָּמִים. וּבְגִין כָּךְ יִתּוֹסַף בָּהּ רוּחַ עִלָּאָה, וּבְגִין כָּךְ יִתְעָרוּן כְּדֵין כָּל אִינוּן מֵיתַיָא דְּאִינוּן גּוֹ עַפְרָא.</p>\n<p>וְדָא הוּא עַבְדִּי, רָזָא דְמַפְתְּחָן דְּמָארֵיהּ בִּידֵיהּ. כְּמָה דְאַתְּ אָמֵר, (אל עבדו זקן ביתו וכמה דאת אמר), (בראשית כ״ד:ב׳) וַיֹּאמֶר אַבְרָהָם אֶל עַבְדוֹ, דָּא סִיהֲרָא כְּמָה דְאִתְּמָר, מטטרו\"ן דְּאִיהוּ עֶבֶד שְׁלִיחָא דְּמָארֵיהּ.</p>\n<p>זְקַן בֵּיתוֹ כְּמָה דְאַתְּ אָמֵר, (תהילים ל״ז:כ״ה) נַעַר הָיִיתִי גַּם זָקַנְתִּי. הַמּוֹשֵׁל בְּכָל אֲשֶׁר לוֹ, בְּגִין דְּכָל גְּוָונִין אִתְחֲזוּן בֵּיהּ יָרוֹ\"ק וְחִוָּו\"ר וְסוּמָ\"ק.</p>\n<p>שִׂים נָא יָדְךָ תַּחַת יְרֵכִי, דָּא הוּא צַדִּיק רָזָא דְמִלָּה, קִיּוּמָא דְעַלְמָא. דְּהָא כְּדֵין הַאי עֶבֶד מְמַנָּא בְּרָזָא עִלָּאָה לַאֲחָיָיא לוֹן לְדַיְירֵי עַפְרָא וְיִתְעֲבִיד שְׁלִיחָא בְּרוּחָא דִלְעֵילָא וְלְאֲתָבָא רוּחִין וְנִשְׁמָתִין לְאַתְרַיְיהוּ לְאִינוּן גּוּפֵי (ס\"א דאתאכלו) דְּאִתְבָּלוּ וְאִתְרְקָבוּ תְּחוֹת עַפְרָא.</p>\n<p>וְאַשְׁבִּיעֲךָ בַּיְיָ אֱלהֵי הַשָּׁמַיִם. וְאַשְׁבִּיעֲךָ, מַאי וְאַשְׁבִּיעֲךָ. לְאִתְלַבְּשָׁא בְּרָזָא דִּשְׁבַע נְהוֹרִין עִלָּאִין דְּאִינוּן רָזָא דִשְׁלִימוּ עִלָּאָה. אֲשֶׁר לֹא תִקַּח אִשָּׁה, דָּא הוּא גוּפָא דִּתְחוֹת עַפְרָא דְּאִית לֵיהּ קִיּוּמָא לַאֲקָמָא מֵעַפְרָא. דְּכָל אִינוּן דְּאִתְקְבָרוּ בָהּ וְזָכוּ לְאִתְקְבָרָא בְּאַרְעָא דְיִשְׂרָאֵל אִינוּן יִתְעָרוּן בְּקַדְמִיתָא, כְּמָה דְאוֹקִימְנָא. דִּכְתִיב, (ישעיהו כ״ו:י״ט) יִחְיוּ מֵתֶיךָ, בְּקַדְמִיתָא אִלֵּין מֵתִין דְאַרְעָא דְיִשְׂרָאֵל. נְבֵלָתִי יְקוּמוּן, אִינוּן מֵתִין דִּשְׁאָר אַרְעָאן. וְעַל דָּא לְאִינוּן גּוּפֵיהוֹן דְּיִשְׂרָאֵל דְּאִתְקְבָרוּ תַּמָּן, וְלָא לְגוּפֵי דִּשְׁאָר עַמִין עוֹבְדֵי עֲבוֹדָה זָּרָה דְּאִסְתָּאֲבָא אַרְעָא מִינַיְיהוּ.</p>\n<p>וְעַל דָּא אֲשֶׁר לא תִקַּח אִשָּׁה לִבְנִי. מַאי לִבְנִי. דְּכָל נִשְׁמָתִין דְּעַלְמָא דְּנָפְקֵי מֵהַהוּא נָהָר דְּנָגִיד וְנָפִיק, אִינוּן בְּנִין לְקוּדְשָׁא בְּרִיךְ הוּא. וְעַל דָּא אֲשֶׁר לֹא תִקַּח אִשָּׁה, דָּא גוּפָא. לִבְנִי, דָּא נִשְׁמָתָא. מִבְּנוֹת הַכְּנַעֲנִי, אִלֵּין גּוּפִין דְּעַמִּין עוֹבְדֵי עֲבוֹדָה זָּרָה, דְּזָמִּין קוּדְשָׁא בְּרִיךְ הוּא לְנַעֲרָא לוֹן מֵאַרְעָא קַדִּישָׁא. כְּמָה דְאַתְּ אָמֵר, (איוב ל״ח:י״ג) וְיִנָּעֲרוּ רְשָׁעִים מִמֶּנָּהּ. כְּמַאן דִּמְנַעֵר טַלִּיתָא מִזּוּהֲמָא דִילָהּ.</p>\n<p>כִּי אֶל אַרְצִי וְאֶל מוֹלַדְתִּי תֵּלֵךְ. אַרְצִי, דָּא הִיא אַרְעָא קַדִּישָׁא דְּאִיהוּ קַדְמָאָה לְכָל שְׁאָר אַרְעִין כְּמָה דְאִתְּמָר. (ועל דא כי אל ארצי דא ארעא קדישא דאיהו דיליה בין כל שאר ארעין דפליג לון לממנן אחרנין) וְעַל דָּא כִּי אֶל אַרְצִי, וְאֶל מוֹלַדְתִּי. כֵּיוָן דְּאָמַר אֶל אַרְצִי מַהוּ וְאֶל מוֹלַדְתִּי. אֶלָּא אֶל אַרְצִי כְּמָה דְאִתְּמָר, (מהו) וְאֶל מוֹלַדְתִּי אִלֵּין אִינוּן יִשְׂרָאֵל.</p>\n<p>תָּא חֲזֵי, מַה כְּתִיב, וַיִּקַּח הָעֶבֶד כְּמָה דְאִתְּמָר. עֲשָׂרָה גְמַלִּים, אִלֵּין אִינוּן עֲשָׂרָה דַרְגִּין דְּהַאי עֶבֶד שָׁלְטָא עֲלַיְיהוּ, כְּגַוְונָא דִלְעֵילָא. מִגְּמַלֵּי אֲדֹנָיו, דְּאִינוּן כְּהַהוּא גַוְונָא מַמָּשׁ כְּמָה דְאִתְּמָר, וְהַאי עֶבֶד שָׁלְטָא וְאִתְתַּקַּן בְּהוּ.</p>\n<p>וְכָל טוּב אֲדֹנָיו בְּיָדוֹ, כָּל הַהוּא טִיבוּ רֵיחִין עִלָּאִין דְּנָפְקֵי מִגּוֹ אִינוּן נְהוֹרִין וּבוֹצִינִין עִלָּאִין. וְכָל טוּב אֲדוֹנָיו, הַהוּא שִׁמּוּשָׁא דְּשִׁמְשָׁא דְּאִתְמַשְּׁכָא בָּהּ בְּסִיהֲרָא.</p>\n<p>וַיָּקָם וַיֵּלֶךְ אֶל אֲרַם נַהֲרַיִם, דָּא אֲתַר דְּאַרְעָא קַדִּישָׁא דְּבָכַת תַּמָּן רָחֵל כַּד חָרִיב בֵּי מַקְדְּשָׁא. וַיַּבְרֵךְ הַגְּמַלִּים מִחוּץ לָעִיר אֶל בְּאֵר הַמָּיִם, לְאִתְתַּקְפָא חֵילָהָא בְּתוּקְפָהָא כְּדְקָא יְאוּת עַד לָא תִיעוּל לַאֲקָמָא לוֹן לְאִינוּן גּופִין.</p>\n<p>לְעֵת עֶרֶב, מַאי לְעֵת עֶרֶב. דָּא עֶרֶב שַׁבָּת <Nonei></i>דְּאִיהוּ זִמְנָא דְאֶלֶף שְׁתִיתָאָה. לְעֵת עֶרֶב כְּמָה דְאַתְּ אָמֵר (תהילים ק״ד:כ״ג) וְלַעֲבוֹדָתוֹ עֲדֵי עָרֶב וּכְתִיב, (ירמיהו ו׳:ד׳) כִּי יִנָּטוּ צִלְּלֵי עָרֶב.</p>\n<p>לְעֵת צֵאת הַשּׁוֹאֲבוֹת, דְּהַהוּא זִמְנָא זְמִינִין לְמֵיקַם וְלַאֲחָיָיא בְּקַדְמִיתָא מִכָּל שְׁאָר בְּנֵי עַלְמָא, אִינוּן דְּשָׁאֲבֵי מֵימוֹי דְאוֹרַיְיתָא (ושאבין), בְּגִין דְּאִתְעַסְּקוּ לְשָׁאֲבָא מִמֵּימֵי דְאוֹרַיְיתָא, וְאִתְתַּקָּפוּ בְּאִילָנָא דְחַיֵּי, וְאִינוּן יִפְקוּן בְּקַדְמִיתָא, דְּאִילָנָא דְחַיֵּי גָּרְמָא לוֹן דִּיקוּמוּן בְּקַדְמִיתָא כְּמָא דְאִתְּמָר.</p>\n<p>וּבְנוֹת אַנְשֵׁי הָעִיר יוֹצְאוֹת. מַאי יוֹצְאוֹת, כְּמָה דְאַתְּ אָמֵר (ישעיהו כ״ו:י״ט) וְאֶרֶץ רְפָאִים תַּפִּיל, דְּזַמִּינָא אַרְעָא לְמִפְלַט מִנָּהּ כָּל רוּחִין דְּאִינוּן בְּגַוָּוהּ, וְעַל דָּא כְּתִיב יוֹצְאוֹת. לִשְׁאוֹב מַיִם, לְנַטְלָא נִשְׁמָתָא וּלְקַבְּלָא לָהּ כְּדְקָא יְאוּת מְתַקְנָא מֵאַתְרָהּ כְּדְקָא חָזֵי.</p>\n<p>וְהָיָה הַנַּעֲרָה אֲשֶׁר אֹמַר אֵלֶיהָ הַטִּי נָא כַדֵּךְ וְאֶשְׁתֶּה, בְּגִין דְּהָא אִתְּמָר, דְּכָל אִינוּן נִשְׁמָתִין דְּעַלְמָא דְּאִתְקָיְימוּ בְּהַאי עַלְמָא וְאִשְׁתַּדְּלוּ לְמִנְדַע לְמָארֵיהוֹן בְּרָזָא דְחָכְמְתָא עִלָּאָה. אִיהִי סָלְקַת וְאִתְקָיְימַת בְּדַרְגָּא עִלָּאָה עַל כָּל אִינוּן דְּלָא אִתְדַּבְּקוּ וְלָא יָדְעוּ, וְאִינוּן אִתְקָיְימוּן בְּקַדְמִיתָא. וְדָא הוּא שְׁאֵלְתָּא דְּקָאִים הַהוּא עֶבֶד לְמִנְדַע וּלְמִשְׁאַל, בְּמָּה אִתְעַסְּקַת הַהִיא נִשְׁמָתָא בְּהַאי עָלְמָא.</p>\n<p>וְאָמְרָה אֵלַי גַּם אַתָּה שְׁתֵה, אַנְתְּ בָּעֵי לְמִשְׁתֵּי וּלְאִתְשַׁקְיָא בְּקַדְמִיתָא, וּבַתְרָךְ וְגַם לִגְמַלֶּיךָ אַשְׁקֶה. בְּגִין דְּכָל אִינוּן שְׁאָר רְתִיכִין אַף עַל גַּב דְּאִתְשַׁקְיָין מֵהַאי דַרְגָּא, כֻּלְּהוּ אִתְשַׁקְיָין מִפּוּלְחָנָא דְצַדִּיקַיָיא דְּיָדְעֵי פּוּלְחָנָא דְמָארֵיהוֹן כְּדְקָא יְאוּת. דְּצַדִּיקַיָיא יָדְעֵי לְסַפְּקָא לְכָל דַּרְגָּא וְדַרְגָּא כְּדְקָא יְאוּת. וְעַל דָּא וְגַם לִגְמַלֶּיךָ אַשְׁקֶה. וַדַּאי הִיא הָאִשָּׁה אֲשֶׁר הֹכִיחַ יְיָ לְבֶן אֲדֹנִי. וַדַּאי הַהִיא (ס\"א באתערותא דצלותא דילי) אִיהוּ גוּפָא דְּאִזְדַּמַּן לְהַהִיא נִשְׁמָתָא עִלָּאָה.</p>\n<p>תָּא חֲזֵי, דְּהָא אִתְּמָר דְּתִיאוּבְתָּא דִדְכוּרָא לְגַבֵּי נוּקְבָא עָבִיד נִשְׁמָתָא. וְתִיאוּבְתָּא דְנוּקְבָא לְגַבֵּי דְכוּרָא סָלְקָא וְאִתְעָרַב בַּהֲדָהּ דִּלְעֵילָא וְאִתְכְּלִיל דָּא בְּדָא וְעָבִיד נִשְׁמָתָא. וּבְגִין כָּךְ הִיא הָאִשָּׁה. דָּא הוּא גוּפָא וַדַּאי דְּאִיהוּ זְמִינָא לְהַהוּא רְעוּתָא דְנִשְׁמָתָא דְּנָפְקָא מִן דְּכוּרָא.</p>\n<p>וְאִינוּן גּוּפִין זְמִינִין לְאַתְעָרָא בְּקַדְמִיתָא כִּדְאֲמָרָן. וּלְבָתַר דְּאִלֵּין יְקוּמוּן, יְקוּמוּן כָּל אָחֳרָנִין דְּבִשְׁאָר אַרְעָאן, וְיִתְקַיְימוּן בְּקִיּוּמָא שְׁלִים, וְיִתְחַדְתּוּן בְּחַדְתוּתָא דְּסִיהֲרָא, וְיִתְחַדֵּשׁ עַלְמָא כְּמִלְקַדְּמִין. וּכְדֵין כְּתִיב בְּהַהוּא זִמְנָא (תהילים ק״ד:ל״א) יִשְׂמַח יְיָ בְּמַעֲשָׂיו.</p>\n<p>וּבְגִין כָּךְ (ישעיהו נ״ב:י״ג) הִנֵּה יַשְׂכִּיל עַבְדִּי, לְאַהֲדָרָא נִשְׁמָתִין כָּל חַד וְחַד לְאַתְרֵיהּ. יָרוּם וְנִשָּׂא וְגָבַהּ מְאֹד, מִסִּטְרָא דְּכָל אִינוּן דַּרְגִּין עִלָּאִין כִּדְקָאֲמָרָן.</p>\n<p>(ישעיהו נ״ב:י״ד) כַּאֲשֶׁר שָׁמְמוּ עָלֶיךָ רַבִּים כֵּן מִשְׁחַת מֵאִישׁ מַרְאֵהוּ וְתֹאֲרוֹ מִבְּנֵי אָדָם. תָּא חֲזֵי, דְּהָא אִתְּמָר דְּכַד אִתְחָרַב בֵּי מַקְדְּשָׁא, וּשְׁכִינְתָּא (אתגלי) בְּגוֹ אַרְעָן נוּכְרָאִין בֵּינַיְיהוּ. מַה כְּתִיב, (ישעיהו ל״ג:ז׳) הֵן אֶרְאֱלָם צָעֲקוּ חֻצָה מַלְאֲכֵי שָׁלוֹם מַר יִבְכָּיוּן. כֻּלְּהוּ בָּכוּ עַל דָּא, וּקְשִׁירוּ בְּכִיָה וְאֶבְלָא. וְכָל דָּא עֲלָה דִּשְׁכִינְתָּא דְּאִתְגַּלְּיָיא מֵאַתְרָהּ, וְכַמָּה דְאִיהִי מִשְׁתַּנֵּית מִכְּמָה דְּהֲוַת. אוּף הָכִי בַּעֲלָהּ לָא נָהִיר נְהוֹרֵיהּ וְאִשְׁתַּנֵּי מִכְּמָה דְּהֲוָה, דִּכְתִיב, (ישעיהו י״ג:י׳) חָשַׁךְ הַשֶּׁמֶשׁ בְּצֵאתוֹ. וְעַל דָּא כְּתִיב כֵּן מִשְׁחַת מֵאִישׁ מַרְאֵהוּ.</p>\n<p>דָּבָר אַחֵר כֵּן מִשְׁחַת מֵאִישׁ מַרְאֵהוּ, מֵהַאי עֶבֶד דְּאִשְׁתַּנִּי דִיוּקְנֵיהּ וּגְוָונֵיהּ מִכְּמָה דְּהֲוָה. דָּבָר אַחֵר כֵּן מִשְׁחַת מֵאִישׁ מַרְאֵהוּ, כְּמָה דְאַתְּ אָמֵר, (ישעיהו נ׳:ג׳) אַלְבִּישׁ שָׁמַיִם קַדְרוּת וְשַׂק אָשִׂים כְּסוּתָם. דְּהָא מִיּוֹמָא דְּאִתְחָרַב בֵּי מַקְדְּשָׁא לָא קָיְימוּ שָׁמַיִם בִּנְהוֹרָא דִלְהוֹן, וְרָזָא דְמִלָּה בִּרְכָאן לָא שָׁרְיָין אֶלָּא בְּאֲתַר דְּאִשְׁתַּכָּחוּ דְּכַר וְנוּקְבָא, וְאוּקְמוּהָ. כְּמָה דְאַתְּ אָמֵר, (בראשית ב) זָכָר וּנְקֵבָה בְּרָאָם וַיְבָרֶךְ אֹתָם. וּבְגִין כָּךְ מִשְׁחַת מֵאִישׁ מַרְאֵהוּ.</p>\n<p>וְדָא הוּא כְּמָה דִכְתִיב, (ישעיהו נ״ז:א׳) הַצַּדִּיק אָבַד, אָבוּד אוֹ נֶאֱבַד לֹא נֶאֱמַר, אֶלָּא אָבַד, דְּלָא שַׁרְיָין בִּרְכָאן אֶלָּא בְּאֲתַר דְּאִשְׁתַּכָּחוּ דְּכַר וְנוּקְבָא כְּחֲדָא כְּמָה דְּאִתְּמָר.</p>\n<p>בְּגִין דָּא בְּהַהוּא זִמְנָא דְּלָא אִשְׁתַּכַּח <Nonei></i>דְּכוּרָא בַּהֲדָהּ, וּכְדֵין כָּל אִינוּן נִשְׁמָתִין דְּנָפְקֵי כֻּלְּהוּ הֲוֵי לְהוּ שִׁנּוּיָא מִכְּמָה דְּהֲווּ בְּזִמְנָא דְּשִׁמְשָׁא אִתְחַבַּר בְּסִיהֲרָא כְּמָה דְּאִתְּמָר. וְעַל דָּא אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף וְגו' וְאִתְּמָר.</p>\n<p>וְהוּא נַעַר, בְּגִין דְּלָא מִתְפָּרְשִׁין לְעָלְמִין, צַדִּי\"ק וְצֶדֶ\"ק כְּחֲדָא אִינוּן, כְּמָה דְּאִיהִי אִתְקְרִיאַת בִּשְׁמָא דִדְכוּרָא, הָכִי נָמֵי אִתְקְרֵי אִיהוּ בִּשְׁמָא דִילָהּ דִּכְתִיב וְהוּא נַעַר.</p>\n<p>אֶת בְּנֵי בִּלְהָה וְאֶת בְּנִי זִלְפָּה, בְּכֻלְּהוּ קָיְימָא לְחַדְתָּא לוֹן כְּדְקָא יְאוּת וּלְאִשְׁתַּעְשְׁעָא לוֹן בְּחֶדְוָה דִילֵיהּ. דְּכֻלְּהוּ עַנְפִין וְכֻלְּהוּ עָלִין, כֻּלְּהוּ אִתְבָּרְכִין בְּחֶדְוָה דִילֵיהּ.</p>\n<p>אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף, כְּמָה דְאִתְּמָר דְּכָל דִּיוּקְנָא דְיַעֲקֹב הֲוָה בֵּיהּ בְּיוֹסֵף, וְכָל מַה דְּאֵירַע לְהַאי אֵירַע לְהַאי, וְתַרְוַויְיהוּ כְּחֲדָא אָזְלֵי. וְדָא הוּא רָזָא דְּאָת ו\"ו דְּאָזְלֵי תַּרְוַויְיהוּ כְּחֲדָא, בְּגִין דְּאִינוּן רָזָא חָדָא וְדִיוּקְנָא חָדָא:</p>\n<p>וַיָּבֵא יוֹסֵף אֶת דִּבָּתָם רָעָה, הָא אוּקְמוּהָ דְּהֲוָה אָמַר לְאֲבוֹי עֲלַיְיהוּ דְּהֲווּ אָכְלֵי שַׁיְיפָא מִבַּעֲלֵי חַיִּין כַּד אִינוּן חַיִּין. וַיָּבֵא יוֹסֵף אֶת דִּבָּתָם רָעָה, וְכִי הָא בְּמִנְיָינָא הֲווּ אִינוּן בְּנֵי שְׁפָחוֹת, הֵיךְ הֲווּ מְזַלְזְלִין בְּהוֹן בְּנֵי לֵאָה, וְהֵיךְ הֲווּ אָכְלִין אֵבָר מִן הַחַי וְהֲווּ עָבְרִין עַל פִּקּוּדָא דְמָארֵיהוֹן. דְּהָא פַּקִּיד עַל בְּנֵי נֹחַ פִּקּוּדָא דָא. כְּמָה דְאַתְּ אָמֵר, (בראשית ט׳:ד׳) אַךְ בָּשָׂר בְּנַפְשׁוֹ דָּמוֹ לא תֹאכֵלוּ, וְאִינוּן הֲווּ אָכְלֵי לֵיהּ וְעָבְרִין עַל פִּקּוּדָא דְמָארֵיהוֹן. אֶלָּא יוֹסֵף הֲוָה קָאֲמַר, וְעַל דָּא אִתְעַנַּשׁ.</p>\n<p>רִבִּי יְהוּדָה אָמַר, אֶת דִּבָּתָם רָעָה, כְּמָה דְאוּקְמוּהָ דְּיַהֲבֵי עֵינַיְיהוּ בִּבְנוֹת אַרְעָא, וְדָא הוּא דִּבָּתָם רָעָה. לְיַנְקָא לְכָל אִינוּן דַּרְגִּין דְּלָא קַדִּישִׁין (ד\"א ל\"ג אף על גב) דְּאַתְיָין מִסִּטְרָא מְסָאֲבָא:</p>"],[9520011376,"<p>וְיִשְׂרָאֵל אָהַב אֶת יוֹסֵף מִכָּל בָּנָיו כִּי בֶן זְקֻנִים הוּא לוֹ וְעָשָׂה לוֹ כְּתֹנֶת פַּסִּים. רִבִּי אֶלְעָזָר פָּתַח וְאֲמַר, (ישעיהו כ״ו:כ׳) לֵךְ עַמִּי בֹּא בַחֲדָרֶיךָ וּסְגֹר דְּלָתְךָ בַּעֲדֶךָ חֲבִי כִמְעַט רֶגַע עַד יַעֲבָר זַעַם. לֵךְ עַמִּי בֹּא בַחֲדָרֶיךָ. תָּא חֲזֵי, כַּמָּה קוּדְשָׁא בְּרִיךְ הוּא רָחִים לוֹן לְיִשְׂרָאֵל. וּבְגִין רְחִימוּתָא דִלְהוֹן דְּרָחִים לוֹן עַל כָּל עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, אַזְהַר לוֹן, וּבָעֵי לְנַטְרָא לוֹן בְּכָל מַה דְּאִינוּן עָבְדִין.</p>\n<p>תָּא חֲזֵי, תְּלַת זִמְנִין אִית בְּיוֹמָא דְּדִינָא שַׁרְיָא בְּעַלְמָא, וְכַד אָתֵי הַהוּא זִמְנָא, מִבָּעֵי לֵיהּ לְבַר נָשׁ לְאִזְדַּהֲרָא וּלְאִסְתַּמְרָא דְּלָא יִפְגַע בֵּיהּ הַהוּא דִינָא, וְאִינוּן זִמְנִין יְדִיעָן וְהָא אוּקְמוּהָ.</p>\n<p>בְּגִין דְּהָא כַּד סָלִיק צַפְרָא, אַבְרָהָם אִתְעַר בְּעַלְמָא, וְאָחִיד לֵיהּ לְדִינָא לְקָשְׁרָא לֵיהּ בַּהֲדֵיהּ. וּבְשֵׁירוּתָא דִּתְלַת שָׁעֵי קַמַּיְיתָא נָטִיל דִּינָא מֵאַתְרִיהּ לְאַתְעָרָא בֵּיהּ בְּיַעֲקֹב, עַד דְּאִתְעַר צְלוֹתָא דְמִנְחָה דְּאַהֲדַר דִּינָא לְאַתְרֵיהּ, וְאִתְעַר דִּינָא דִלְתַתָּא לְאִתְקַשְּׁרָא בְּדִינָא דִלְעֵילָא. דְּהָא כְּדֵין אִתְקַשַּׁר דִּינָא בְּדִינָא וּבָעֵי לְאִזְדַּהֲרָא.</p>\n<p>(לעיל סח ב) תוּ כַּד דִּינָא אִתְעַר בְּעַלְמָא וּמוֹתָא אִשְׁתַּכַּח בְּמָתָא, לָא לִיבָּעֵי לֵיהּ לְבַר נָשׁ לְמֵיהַךְ יְחִידָאי בְּשׁוּקָא וְהָא אוֹקִימְנָא מִלֵּי. אֶלָּא בָּעֵי לְאַסְגָּרָא גַּרְמֵיהּ דְּלָא יִפּוּק לְבַר, כְּמָה דְאוּקְמוּהָ בְּנֹחַ דְּאַסְגַּר גַּרְמֵיהּ בְּתֵיבוּתָא דְּלָא יִשְׁתַּכַּח קַמֵי מְחַבְּלָא.</p>\n<p>וְעַל דָּא לֵךְ עַמִּי בֹּא בַחֲדָרֶיךָ, אַסְגַּר גַּרְמָךְ. וּסְגוֹר דְּלָתְךָ בַּעֲדֶךָ, דְּלָא יִתְחֲזֵי קַמֵּיהּ דִּמְחַבְּלָא. חֲבִי כִּמְעַט רֶגַע עַד יַעֲבוֹר זַעַם, דְּבָתַר דְּאַעֲבַר דִּינָא לֵית לֵיהּ רְשׁוּ לִמְחַבְּלָא לְחַבָּלָא.</p>\n<p>תָּא חֲזֵי, דְּקוּדְשָׁא בְּרִיךְ הוּא, בְּגִין רְחִימוּתָא דְּאִיהוּ רָחִים לוֹן לְיִשְׂרָאֵל וְקָרִיב לוֹן לְגַבֵּיהּ, כָּל שְׁאָר עַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת שָׂנְאִין לוֹן לְיִשְׂרָאֵל. בְּגִין דְּאִינוּן מִתְרַחֲקִין וְיִשְׂרָאֵל קְרֵיבִין.</p>\n<p>וְתָּא חֲזֵי, בְּגִין רְחִימוּתָא דְּרָחִים יַעֲקֹב לְיוֹסֵף יַתִּיר מֵאֲחוֹי, אַף עַל גַּב דְּכֻלְּהוּ הֲווּ לֵיהּ אַחִין, מַה כְּתִיב וַיִּתְנַכְּלוּ אוֹתוֹ לַהֲמִיתוֹ, כָּל שֶׁכֵּן עַמִּין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת לְיִשְׂרָאֵל.</p>\n<p>תָּא חֲזֵי, כַּמָּה גָּרִים לֵיהּ הַהוּא רְחִימוּתָא דְּרָחִים לֵיהּ יַתִּיר, דְּגָרַם לֵיהּ דְּאִתְגְּלֵי מֵאֲבוֹי, וְאִתְגְּלִי אֲבוֹי בַּהֲדֵיהּ, וְגָרַם לְהוּ גָלוּתָא <Nonei></i>וְלִשְׁכִינְתָּא דְאִתְגַּלְּיָא בֵּינַיְיהוּ. וְאַף עַל גַּב דְּאִתְגְּזִירַת גְּזֵרָה, וְאוּקְמוּהָ דִּבְגִין כְּתֹנֶת פַּסִּים דְּעֲבַד לֵיהּ יַתִּיר, מַה כְּתִיב וַיִּרְאוּ אֶחָיו:</p>"],[9520011377,"<p>וַיַּחֲלֹם יוֹסֵף חֲלוֹם וְגו', רִבִּי חִיָּיא פָּתַח וְאֲמַר, (במדבר י״ב:ו׳) וַיֹּאמֶר שִׁמְעוּ נָא דְּבָרָי אִם יִהְיֶה נְבִיאֲכֶם יְיָ בַּמַּרְאָה אֵלָיו אֶתְוַדָּע בַּחֲלוֹם אֲדַבֶּר בּוֹ. תָּא חֲזֵי, כַּמָּה דַרְגִּין לְדַרְגִין עֲבַד קוּדְשָׁא בְּרִיךְ הוּא, וְכֻלְּהוּ קָיְימֵי דָא עַל דָּא. דַּרְגָּא עַל דַּרְגָּא, דָּא לְעֵיל מִן דָּא, וְכֻלְּהוּ יָנְקִין אִלֵּין מִן אִלֵּין כְּדְקָא חָזֵי לוֹן, אִלֵּין מִימִינָא וְאִלֵּין מִשְּׂמָאלָא, וְכֻלְּהוּ אִתְמַנָּן אִלֵּין עַל אִלֵּין, כֹּלָּא כְּדְקָא יְאוּת.</p>\n<p>תָּא חֲזֵי, כָּל נְבִיאֵי דְעַלְמָא כֻּלְּהוּ יָנְקֵי מִסִּטְרָא חָדָא, מִגּוֹ תְּרִין דַּרְגִּין יְדִיעָן, וְאִינוּן דַּרְגִּין הֲווּ אִתְחַזְּיָין בְּגוֹ אַסְפַּקְלַרְיָאה דְּלָא נָהֲרָא, דִּכְתִיב בַּמַּרְאָה אֵלָיו אֶתְוַדָּע, מַאי הוּא מַרְאָה, כְּמָה דְאִתְּמָר (ד\"א ל\"ג דמראה) חֵיזוּ דְּכָל גְּוָונִן אִתְחַזְּיָין בְּגַוָּוהּ, וְדָא הִיא אַסְפַּקְלַרְיָא דְּלָא נָהֲרָא. בַּחֲלוֹם אֲדַבֶּר בּוֹ, דָּא הוּא חַד מִשִּׁתִּין בִּנְבוּאָה כְּמָה דְאוּקְמוּהָ. וְאִיהוּ דַּרְגָּא שְׁתִיתָאָה מֵהַהוּא דַרְגָּא דִּנְבוּאָה וְאִיהוּ (קצו א) דַּרְגָּא דְגַבְרִיאֵל דִמְמַנָּא עַל חֶלְמָא וְהָא אִתְּמָר.</p>\n<p>תָּא חֲזֵי, כָּל חֶלְמָא דְּאִיהוּ כְּדְקָא יְאוּת מֵהַאי דַרְגָּא קָא אַתְיָא, וְעַל דָּא לֵית לָךְ חֶלְמָא דְּלָא יִתְעָרְבוּן עִמֵּיהּ מִלִּין כְּדִיבִין, כְּמָה דְאוֹקִימְנָא, וּבְגִין כָּךְ מִנַּיְיהוּ קְשׁוֹט וּמִנַּיְיהוּ כְּדִיבָן, וְלֵית לָךְ חֶלְמָא דְּלָא אִית בֵּיהּ מֵהַאי גִיסָא וּמֵהַאי גִיסָא.</p>\n<p>וּבְגִין דְּאִית בֵּיהּ בְּחֶלְמָא כֹּלָּא כִּדְאֲמָרָן, כָּל חֶלְמִין דְּעַלְמָא אָזְלִין בָּתַר פִּשְׁרָא דְפוּמָא, וְאוּקְמוּהָ. דִּכְתִיב, (בראשית מ״א:י״ג) וַיְהִי כַּאֲשֶׁר פָּתַר לָנוּ כֵּן הָיָה. מַאי טַעְמָא, בְּגִין דְּאִית בֵּיהּ בְּחֶלְמָא כְּדִיבוּ וּקְשׁוֹט, וּמִלָּה שָׁלְטָא עַל כֹּלָּא, וּבְגִין כָּךְ בָּעֵי חֶלְמָא פִּשְׁרָא טָבָא. רִבִּי יְהוּדָה אָמַר, בְּגִין דְּכָל חֶלְמָא מִדַּרְגָּא דִלְתַתָּא אִיהוּ, וְדִבּוּר שָׁלְטָא עֲלֵיהּ. וּבְגִין כָּךְ כָּל חֶלְמָא אָזְלָא בָּתַר פִּשְׁרָא.</p>\n<p>פָּתַח וְאֲמַר, (איוב ל״ג:ט״ו-ט״ז) בַּחֲלוֹם חֶזְיוֹן לַיְלָה בִּנְפֹל תַּרְדֵּמָה עַל אֲנָשִׁים בִּתְנוּמוֹת עֲלֵי מִשְׁכָּב אָז יִגְלֶה אֹזֶן אֲנָשִׁים וּבְמֹסָרָם יַחְתֹּם. תָּא חֲזֵי, כַּד סָלִיק בַּר נָשׁ לְעַרְסֵיהּ, מִבָּעֵי לֵיהּ לְאַמְלָכָא עֲלֵיהּ מַלְכוּתָא דִשְׁמַיָא בְּקַדְמִיתָא, וּלְבָתַר יֵימָא חַד פְּסוּקָא דְרַחֲמֵי וְאוּקְמוּהָ חַבְרַיָיא. בְּגִין דְּהָא כַּד בַּר נָשׁ נָאִים עַל עַרְסֵיהּ, הָא נִשְׁמָתֵיהּ נַפְקָא מִנִּיהּ וְאָזְלָא וְשָׁטְיָא לְעֵילָא, כָּל חַד וְחַד כְּפוּם אָרְחֵיהּ וְהָכִי סְלִיקַת כְּמָה דְאִתְּמָר.</p>\n<p>מַה כְּתִיב, בַּחֲלוֹם חֶזְיוֹן לַיְלָה. כַּד בְּנֵי נָשָׁא שָׁכְבֵי בְּעַרְסַיְיהוּ נָיְימִין וְנִשְׁמָתָא נָפְקַת מִנַּיְיהוּ. הֲדָא הוּא דִכְתִיב, בִּתְנוּמוֹת עֲלֵי מִשְׁכָּב אָז יִגְלֶה אֹזֶן אֲנָשִׁים. וּכְדֵין קוּדְשָׁא בְּרִיךְ הוּא אוֹדַע לָהּ לְנִשְׁמָתָא בְּהַהוּא דַרְגָּא דְּקָיְימָא עַל חֶלְמָא, אִינוּן מִלִּין דִּזְמִינִין לְמֵיתֵי עַל עַלְמָא אוֹ אִינוּן מִלִּין כְּפוּם אִינוּן הִרְהוּרִין דְּלִבֵּיהּ. בְּגִין דְּבַר נָשׁ נָטִיל אָרְחָא דְּתוֹכָחֵי דְעָלְמָא.</p>\n<p>בְּגִין דְּהָא לָא מוֹדָעִין לֵיהּ לְבַר נָשׁ בְּעוֹד דְּאִיהוּ קָאִים בְּתוּקְפָא דְגוּפָא (נ\"א דרוחא) כִּדְקָאֲמָרָן, אֶלָּא מַלְאָכָא אוֹדַע לְנִשְׁמָתָא וְנִשְׁמָתָא לְבַר נָשׁ. וְהַהוּא חֶלְמָא אִיהוּ מִלְּעֵילָא, כַּד נִשְׁמָתִין נָפְקִין מִגּוּפֵי וְסָלְקִין כָּל חַד וְחַד כְּפוּם אָרְחֵיהּ.</p>\n<p>וְכַמָּה דַּרְגִּין עַל דַּרְגִּין, בְּרָזָא דְחֶלְמָא כֻּלְּהוּ בְּרָזָא דְחָכְמְתָא. וְתָּא חֲזֵי, חֲלוֹם דַּרְגָּא חָדָא, מַרְאָה דַּרְגָּא חָדָא, נְבוּאָה דַּרְגָּא חָדָא, וְכֻלְּהוּ דַּרְגִּין לְדַרְגִּין אִלֵּין עַל אִלֵּין.</p>\n<p>וַיַּחֲלֹם יוֹסֵף חֲלוֹם וַיַּגֵּד לְאֶחָיו וַיּוֹסִפוּ עוֹד שְׂנֹא אֹתוֹ עַל חֲלוֹמוֹתָיו. מֵהָכָא דְּלָא מִבָּעֵי לֵיהּ לְבַר נָשׁ לְמֵימַר חֶלְמֵיהּ בַּר לְהַהוּא בַּר נָשׁ דְּרָחִים לֵיהּ, וְאִי לָאו, אִיהוּ גָּרִים לֵיהּ. דְּאִי הַהוּא חֶלְמָא מִתְהַפֵּךְ לְגַוְונָא אָחֳרָא, אִיהוּ גָּרִים לְסַלְּקָא.</p>\n<p>תָּא חֲזֵי, דְּיוֹסֵף אִיהוּ אָמַר חֶלְמָא לַאֲחוּהִי, וְעַל דָּא גָּרְמוּ לֵיהּ לְסַלָּקָא חֶלְמֵיהּ תְּרֵין וְעֶשְׂרִין שְׁנִין דְּאִתְעַכַּב. רִבִּי יוֹסֵי אָמַר, מְנָלָן, דִּכְתִיב וַיּוֹסִיפוּ עוֹד שְׂנֹא אוֹתוֹ. מַאי שְׂנֹא אוֹתוֹ, דְּגָרְמוּ לֵיהּ קִטְרוּגִין בְּדָא.</p>\n<p>מַה כְּתִיב, וַיֹּאמֶר אֲלֵיהֶם שִׁמְעוּ נָא הַחֲלוֹם הַזֶּה <Nonei></i>אֲשֶׁר חָלָמְתִּי, דְּבָעָא מִנַיְיהוּ דְּיִשְׁמְעוּן לֵיהּ. וְאִיהוּ אוֹדַע לְהוּ הַהוּא חֶלְמָא, דְּאִלְמָלֵא אִינוּן דְּאַהֲפָכוּ לֵיהּ לְגַוְונָא אָחֳרָא, הָכִי אִתְקְיַּים. וְאִינוּן אֲתִיבוּ וְאָמְרוּ הֲמָלֹךְ תִּמְלךְ עָלֵינוּ אִם מָשׁוֹל תִּמְשֹׁל בָּנוּ. מִיָּד אָמְרוּ לֵיהּ פִּשְׁרָא דְחָלְמָא וְגָזְרוּ גְּזֵרָה, וּבְגִין כָּךְ וַיּוֹסִיפוּ עוֹד שְׂנֹא אוֹתוֹ.</p>\n<p>רִבִּי חִיָּיא וְרִבִּי יוֹסֵי הֲווּ שְׁכִיחֵי קַמֵיהּ דְּרִבִּי שִׁמְעוֹן, אָמַר רִבִּי חִיָּיא, הָא תָּנִינָן חֶלְמָא דְלָא אִתְפַּשַּׁר, כְּאִגַּרְתָּא דְלָא מִתְקַרְיָא. אִי בְּגִין דְּאִתְקְיַּים וְאִיהוּ לָא יָדַע, אוֹ דְּלָא אִתְקְיַּים כְּלָל. אָמַר לֵיהּ, אִתְקְיַּים וְלָא אִתְיְידַע, דְּהָא הַהוּא חֶלְמָא חֵילָא תַּלְיָא עֲלֵיהּ, וְאִיהוּ לָא אִתְיְדַע וְלָא יְדִיעַ, אִי אִתְקְיַּים אִי לָא אִתְקְיַּים.</p>\n<p>וְלֵית לָךְ מִלָּה בְּעַלְמָא דְּעַד לָא יֵיתֵי לְעַלְמָא, דְּלָאו אִיהִי תַּלְיָיא בְּחֶלְמָא אוֹ עַל יְדָא דְּכָרוֹזָא. דְּהָא אִתְּמָר דְּכָל מִלָּה וּמִלָּה עַד לָא יֵיתֵי לְעַלְמָא, מַכְרְזֵי עֲלֵיהּ בָּרָקִיעַ. וּמִתַּמָּן אִתְפַּשַּׁט בְּעַלְמָא וְאִתְיְהִיב עַל יְדָא דְּכָרוֹזָא. וְכֹלָּא בְּגִין דִּכְתִיב, (עמוס ג׳:ז׳) כִּי לא יַעֲשֶׂה יְיָ אֱלהִים דָּבָר כִּי אִם גָּלָה סוֹדוֹ אֶל עֲבָדָיו הַנְּבִיאִים, בְּזִמְנָא דִנְבִיאִים אִשְׁתַּכָּחוּ בְּעַלְמָא. וְאִי לָאו, אַף עַל גַּב דִּנְבוּאָה לָא שַׁרְיָא, חַכִּימֵי עֲדִיפֵי מִנְּבִיאִים. וְאִי לָא, אִתְיְהִיב בְּחֶלְמָא. וְאִי לָאו, בְּצִפֳּרֵי שְׁמַיָא מִשְׁתַּכְּחֵי מִלָּה וְהָא אוּקְמוּהָ:</p>"],[9520011378,"<p>וַיֵּלְכוּ אֶחָיו לִרְעוֹת אֶת צֹאן אֲבִיהֶם בִּשְׁכֶם. רִבִּי שִׁמְעוֹן אָמַר, לִרְעוֹת צֹאן אֲבִיהֶם מִבָּעֵי לֵיהּ, מַאי אֶ\"ת נָקוּד מִלְּעֵילָא, לְאַסְגָּאָה עִמְהוֹן שְׁכִינְתָּא, דְּאִיהִי עִמְּהוֹן שַׁרְיָיא. בְּגִין דְּאִינוּן הֲווּ עֲשָׂרָה, דְּהָא יוֹסֵף לָא הֲוָה עִמְּהוֹן, וּבִנְיָמִין אִיהוּ זְעִיר בְּבֵיתָא. וּבְגִין כָּךְ אִינוּן הֲווּ עֲשָׂרָה. וְכַד אָזְלוּ הֲוַת שְׁכִינְתָּא בֵּינַיְיהוּ, וְעַל דָּא נָקוּד מִלְּעֵילָא.</p>\n<p>וּבְגִין כָּךְ בְּזִמְנָא דְּזַבִּינוּ לֵיהּ לְיוֹסֵף אִשְׁתַּתָּפוּ כֻּלְּהוּ בַּהֲדֵי שְׁכִינְתָּא וְאַשְׁתִּיפוּ לָהּ בַּהֲדַיְיהוּ כַּד עֲבִידוּ אוֹמָאָה. וְעַד דְּאִתְגַּלְּיָיא מִלָּה דְיוֹסֵף, לָא שַׁרְיָא שְׁכִינְתָּא עֲלֵיהּ דְּיַעֲקֹב.</p>\n<p>וְאִי תֵימָא דִּשְׁכִינְתָּא לָא אִשְׁתַּכְּחַת עִמְּהוֹן. תָּא חֲזֵי, דִּכְתִיב (תהילים קכ״ב:ד׳) שֶׁשָּׁם עָלוּ שְׁבָטִים שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל לְהוֹדוֹת לְשֵׁם יְיָ. כֻּלְּהוּ צַדִּיקֵי וַחֲסִידֵי קִיּוּמָא דְכָל עַלְמָא, קִיּוּמָא אִינוּן לְעֵילָא וְתַתָּא.</p>"],[9520011379,"<p>פָּתַח וְאָמַר, (תהילים קכ״ב:א׳) שָׂמַחְתִּי בְּאוֹמְרִים לִי בֵּית יְיָ נִלֵךְ. הַאי קְרָא אוּקְמוּהָ, דְּדָוִד הֲוָה עִם לִבֵּיהּ לְמִבְנֵי בֵּיתָא. כְּמָה דְאַתְּ אָמֵר, (מלכים א ח׳:י״ז) וַיְהִי עִם לְבַב דָּוִד אָבִי לִבְנוֹת בַּיִת לְשֵׁם יְיָ וְגו'. וּלְבָתַר מַה כְּתִיב רַק אַתָּה לא תִבְנֶה הַבַּיִת כִּי אִם בִּנְךָ הַיּוֹצֵא מֵחֲלָצֶיךָ הוּא יִבְנֶה הַבַּיִת לִשְׁמִי. וְכָל יִשְׂרָאֵל הֲווּ יָדְעֵי דָא, וְהֲווּ אָמְרוּ אֵימָתַי יָמוּת דָּוִד וְיָקוּם שְׁלֹמֹה בְּרֵיהּ וְיִבְנֶה בֵּיתָא. וּכְדֵין עוֹמְדוֹת הָיוּ רַגְלֵינוּ בִּשְׁעָרַיִךְ יְרוּשָׁלַיִם, כְּדֵין נִיסַק וְנַקְרִיב תַּמָּן קָרְבָּנִין.</p>\n<p>וְעִם כָּל דָּא, אַף עַל גַּב דְּהֲווּ אָמְרוּ אֵימָתַי יָמוּת סָבָא דָא, כְּדֵין שָׂמַחְתִּי. וְחֶדְוָה הֲוָה לִי בְּגִין בְּרִי, דְּהֲווּ אָמְרֵי דִבְרִי יָקוּם תְּחוֹתִי לְמִגְמַר פִּקוּדָא לְמִבְנִי בֵיתָא. כְּדֵין שָׁרֵי וְשַׁבַּח לָהּ וְאָמַר, יְרוּשָׁלַיִם הַבְּנוּיָה כְּעִיר שֶׁחֻבְּרָה לָהּ יַחְדָּו.</p>\n<p>תְּנַן עֲבַד קוּדְשָׁא בְּרִיךְ הוּא יְרוּשָׁלַיִם לְתַתָּא כְּגַוְונָא דִלְעֵילָא, וְדָא מִתְתַּקְּנָא (דא) לָקֳבֵל דָּא דִּכְתִיב, (שמות ט״ו:י״ז) מָכוֹן לְשִׁבְתְּךָ פָּעַלְתָּ יְיָ. הַבְּנוּיָה, דְּזַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְנַחֲתָא לָהּ יְרוּשָׁלַיִם דִּלְעֵילָא כְּדְקָא יָאוֹת, וּבְגִין כָּךְ הַבְּנוּיָה. שֶׁחֻבְּרָה לָהּ יַחְדָּו, וְהָא אוּקְמוּהָ שֶׁחֻבְּרָה שֶׁחִבְּרוּ מִבָּעֵי לֵיהּ. אֶלָּא דְּאִתְחַבָּרַת אִמָּא בִּבְרַתָּא וְהֲווּ כְּחֲדָא וְאוּקְמוּהָ.</p>\n<p>וְאִתְּמָר. שֶׁשָּׁם עָלוּ שְׁבָטִים אִלֵּין אִינוּן קִיּוּמָא דְעַלְמָא וְתִקּוּנָא דְעַלְמָא תַּתָּאָה, וְלָא תֵימָא דְּעַלְמָא תַּתָּאָה בִּלְחוֹדוֹי, אֶלָּא אֲפִילּוּ דְּעַלְמָא עִלָּאָה. דִּכְתִיב שִׁבְטֵי יָהּ עֵדוּת לְיִשְׂרָאֵל, לְיִשְׂרָאֵל דַּיְיקָא. בְּגִין דְּאִינוּן קִיּוּמָא לְתַתָּא, סַהֲדוּתָא אִינוּן לְעֵילָא. וְכֹלָּא לְהוֹדוֹת לְשֵׁם יְיָ, לְאוֹדָאָה שְׁמֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא לְכָל סִטְרִין, דִּכְתִיב לְהוֹדוֹת לְשֵׁם יְיָ:</p>"],[9520011380,"<p>וַיִּמְצָאֵהוּ אִישׁ וְהִנֵּה תֹעֶה בַּשָּׂדֶה וַיִּשְׁאָלֵהוּ הָאִישׁ לֵאמֹר מַה תְּבַקֵּשׁ. <Nonei></i>מַה כְּתִיב לְעֵילָא, וַיֹּאמֶר יִשְׂרָאֵל אֶל יוֹסֵף הֲלוֹא אַחֶיךָ רֹעִים בִּשְׁכֶם לְכָה וְאֶשְׁלָחֲךָ אֲלֵיהֶם. וְכִי יַעֲקֹב שְׁלֵימָא דְּהֲוָה רָחִים לֵיהּ לְיוֹסֵף מִכָּל בְּנוֹי, וְהֲוָה יָדַע דְּכָל אֲחוּי הֲווּ סָנְאִין לֵיהּ, אַמַּאי שַׁדַּר לֵיהּ לְגַבַּיְיהוּ. אֶלָּא אִיהוּ לָא חָשִׁיד עֲלַיְיהוּ, דְּהֲוָה יָדַע דְּכֻלְּהוּ הֲווּ זַכָּאִין, וְלָא חָשִׁיד לוֹן. אֶלָּא גָּרִים קוּדְשָׁא בְּרִיךְ הוּא כָּל דָּא, בְּגִין לְקַיְימָא גְּזֵרָה דְּגָזַר בֵּין הַבְּתָרִים.</p>\n<p>אַשְׁכַּחְנָא בְּסִפְרֵי קַדְמָאי, דְּבָעְיָין אִלֵּין בְּנֵי יַעֲקֹב לְשַׁלְּטָאָה עֲלוֹי עַד לָא יֵחוֹת לְמִצְרַיִם. דְּאִילּוּ הוּא יֵחוֹת לְמִצְרַיִם, וְאִינוּן לָא שָׁלְטוּ בֵּיהּ בְּקַדְמִיתָא. יָכְלֵי מִצְרָאִי לְשַׁלְּטָאָה לְעָלְמִין עֲלַיְיהוּ דְּיִשְׂרָאֵל, וְאִתְקַיְימָא בֵּיהּ בְּיוֹסֵף דְּאִזְדַּבַּן לְעַבְדָא וְאִינוּן שָׁלְטוּ עֲלוֹי. וְאַף עַל גַּב דְּיוֹסֵף הֲוָה מַלְכָּא לְבָתַר, וּמִצְרָאֵי הֲווּ עָבְדִין לֵיהּ, אִשְׁתַּכָּחוּ יִשְׂרָאֵל דְּשָׁלְטוּ עַל כֻּלְּהוּ.</p>\n<p>תָּא חֲזֵי, דְּיוֹסֵף דְּאִיהוּ בְּרִית עִלָאָה, כָּל זִמְנָא דְּאִתְקְיַּים בְּרִית, שְׁכִינְתָּא אִתְקְיַּים בַּהֲדַיְיהוּ דְיִשְׂרָאֵל בִּשְׁלָם כְּדְקָא יְאוּת, כֵּיוָן דְּאִסְתַּלַּק יוֹסֵף בְּרִית עִלָּאָה מֵעַלְמָא, כְּדֵין בְּרִית שְׁכִינְתָּא וְיִשְׂרָאֵל כֻּלְּהוּ בְּגָלוּתָא נָפְקוּ, וְהָא אוֹקִימְנָא דִּכְתִיב (שמות א׳:ח׳) וַיָּקָם מֶלֶךְ חָדָשׁ עַל מִצְרַיִם אֲשֶׁר לא יָדַע אֶת יוֹסֵף. וְכֹלָּא הֲוָה מֵעִם קוּדְשָׁא בְּרִיךְ הוּא כְּדְקָא יְאוּת.</p>\n<p>תָּא חֲזֵי, וַיִּמְצָאֵהוּ אִישׁ דָּא גַּבְרִיאֵ\"ל, וְאוּקְמוּהָ. כְּתִיב הָכָא וַיִּמְצָאֵהוּ אִישׁ, וּכְתִיב הָתָם (דניאל ט׳:כ״א) וְהָאִישׁ גַּבְרִיאֵל אֲשֶׁר רָאִיתִי בֶחָזוֹן בַּתְּחִלָּה. וְהִנֵּה תוֹעֶה, בְּכֹלָּא תּוֹעֶה, דְּאַבְטַח עַל אֲחוּי דְּהֲוָה מִתְבַּע אַחְוָה דִלְהוֹן וְלָא אַשְׁכַּח, וְתָבַע לְהוּ וְלָא אַשְׁכַּח. וְעַל דָּא תוֹעֶה בְּכֹלָּא, וְעַל דָּא וַיִּשְׁאָלֵהוּ הָאִישׁ לֵאמֹר מַה תְּבַקֵּשׁ:</p>"],[9520011381,"<p>וַיֹּאמֶר אֶת אַחַי אָנֹכִי מְבַקֵּשׁ וְגו'. וַיֹּאמֶר הָאִישׁ נָסְעוּ מִזֶּה וְגו', רִבִּי יְהוּדָה פָּתַח, (שיר השירים ח׳:א׳) מִי יִתֶּנְךָ כְּאָח לִי יוֹנֵק שְׁדֵי אִמִּי אֶמְצָאֲךָ בַחוּץ אֶשָׁקְךָ גַּם לֹא יָבוֹזוּ לִי. הַאי קְרָא אוּקְמוּהָ חַבְרַיָיא, אֲבָל הַאי קְרָא כְּנֶסֶת יִשְׂרָאֵל אֲמָרוֹ לְמַלְכָּא דִּשְׁלָמָא דִילֵיהּ. מִי יִתֶּנְךָ כְּאָח לִי, כְּיוֹסֵף עַל אֲחוּי, דְּאָמַר, (בראשית נ׳:כ״א) וְעַתָּה אַל תִּירָאוּ אָנֹכִי אֲכַלְכֵּל אֶתְכֶם וְאֶת טַפְּכֶם. יָהַב לוֹן מְזוֹנָא וְזָן לְהוּ בְּכַפְנָא. בְּגִין כָּךְ מִי יִתֶּנְךָ כְּאָח לִי.</p>\n<p>דָּבָר אַחֵר מִי יִתֶּנְךָ כְּאָח לִי, דָּא יוֹסֵף, לְגַבָּהּ דִּשְׁכִינְתָּא דְּאִתְאַחַד עִמָּהּ וְאִתְדָּבַּק בַּהֲדָהּ. יוֹנֵק שְׁדֵי אִמִּי, דְּהָא כְּדֵין אַחְוָה וּשְׁלִימוּ בַּהֲדַיְיהוּ. אֶמְצָאֲךָ בַּחוּץ, גּוֹ גָּלוּתָא, דְּאִיהוּ בְּאַרְעָא אָחֳרָא. אֶשָׁקְךָ, בְּגִין לְאִתְדַּבְּקָא רוּחָא בְּרוּחָא. גַּם לא יָבוֹזוּ לִי, אַף עַל גַּב דְּאֲנָא בְּאַרְעָא אָחֳרָא.</p>\n<p>תָּא חֲזֵי, דְּיוֹסֵף אַף עַל גַּב דְּאֲחוֹי לָא הֲווּ לֵיהּ כְּאַחִין כַּד נָפַל בִּידַיְיהוּ. אִיהוּ הֲוָה לוֹן כְּאַחָא כַּד נָפְלוּ בִּידֵיהּ, וְהָא אוּקְמוּהָ. דִּכְתִיב, (בראשית נ׳:כ״א) וַיְנַחֵם אוֹתָם וַיְדַבֵּר עַל לִבָּם, בְּכֹלָּא דִּבֶּר עַל לִבַּיְיהוּ.</p>"],[9520011382,"<p>וְתָא חֲזֵי, מַה כְּתִיב וַיֹּאמְרוּ אִישׁ אֶל אָחִיו, דָּא שִׁמְעוֹן וְלֵוִי דְּאִינוּן הֲווּ אַחִין וַדַּאי בְּכֹלָּא, בְּגִין דְּקָא אָתוּ מִסִּטְרָא דְדִינָא קַשְׁיָא. וּבְגִין כָּךְ רוּגְזָא דִלְהוֹן, אִיהוּ רוּגְזָא דִּקְטָלָא בְּעַלְמָא. כְּמָה דְאַתְּ אָמֵר (בראשית מ״ט:ז׳) אָרוּר אַפָּם כִּי עָז וְעֶבְרָתָם כִּי קָשָׁתָה.</p>\n<p>תָּא חֲזֵי, רָזָא דְמִלָּה, אִית רוּגְזָא וְאִית רוּגְזָא. אִית רוּגְזָא דְּאִיהוּ מְבָרְכָא מֵעֵילָא וּמִתַּתָּא, וְאִקְרֵי בָּרוּךְ, כְּמָה דְאִתְּמָר דִּכְתִיב (בראשית י״ד:י״ט) בָּרוּךְ אַבְרָם לְאֵל עֶלְיוֹן קוֹנִה שָׁמַיִם וָאָרֶץ וְהָא אוּקְמוּהָ. וְאִית רוּגְזָא דְּאִיהִי אִתְלַטְיָא לְעֵילָא וְתַתָּא, כְּמָה דְאִתְּמָר דְּאִקְרֵי אָרוּר. דִּכְתִיב, (בראשית ג׳:י״ד) אָרוּר אַתָּה מִכָּל הַבְּהֵמָה וּמִכָּל חַיַּת הַשָּׂדֶה. אָרוּר אַפָּם כִּי עָז.</p>\n<p>וְעַל רָזָא דָא אִית תְּרֵין טוּרִין דִּכְתִיב, (דברים י״א:כ״ט) וְנָתַתָּ אֶת הַבְּרָכָה עַל הַר גְּרִיזִים וְאֶת הַקְּלָלָה עַל הַר עֵיבָל, לָקֳבֵיל אִלֵּין תְּרֵין דַּרְגִּין. וְעַל דָּא, דָּא אִקְרֵי אָרוּר, וְדָא אִקְרֵי בָּרוּךְ. וְשִׁמְעוֹן וְלֵוִי אִינוּן מִסִּטְרָא דְדִינָא קַשְׁיָא, וּמִן סִטְרָא דְדִינָא קַשְׁיָא תַּקִּיפָא, נָפְקַת רוּגְזָא דְאִתְלַטְיָא.</p>\n<p>וְתָּא חֲזֵי, מִסִּטְרָא דְדִינָא קַשְׁיָא נָפְקֵי רוּגְזָא לִתְרֵי סִטְרִין, חַד דְּאִתְבָּרַךְ, וְחַד דְּאִתְלַטְיָא. <Nonei></i>חַד בָּרוּךְ וְחַד אָרוּר. כְּגַוְונָא דָא מִסִּטְרָא דְיִצְחָק נָפְקוּ תְּרֵין בְּנִין, חַד מְבוֹרָךְ, וְחַד דְּאִתְלַטְיָא לְעֵילָא וְתַתָּא. דָּא אִתְפָּרַשׁ לְסִטְרֵיהּ, וְדָא אִתְפָּרַשׁ לְסִטְרֵיהּ. דָּא דִּיּוּרֵיהּ בְּאַרְעָא קַדִּישָׁא, וְדָא דִּיּוּרֵיהּ בְּטוּרָא דְשֵׂעִיר. דִּכְתִיב, (בראשית כ״ה:כ״ז) אִישׁ יוֹדֵעַ צַיִד אִישׁ שָׂדֶה. דָּא אַתְרֵיהּ בְּאֲתַר דְּמִדְבָּרָא וְחָרְבָא וּשְׁמָמָה, וְדָא יוֹשֵׁב אֹהָלִים. וְכֹלָּא כְּגַוְונָא דְאִצְטְרִיךְ.</p>\n<p>וּבְגִין כָּךְ תְּרֵין דַּרְגִּין אִינוּן, בָּרוּךְ וְאָרוּר, דָּא לְסִטְרֵיהּ וְדָא לְסִטְרֵיהּ. מֵהַאי נָפְקִין כָּל בִּרְכָאן דְּעָלְמִין לְעֵילָא וְתַתָּא וְכָל טִיבוּ וְכָל נְהִירוּ וְכָל פּוּרְקָן וְכָל שֵׁזָבוּתָא. וּמֵהַאי נָפְקִין כָּל לְוָוטִין וְכָל חַרְבָּא וְכָל דָּמָא וְכָל שְׁמָמָא וְכָל בִּישִׁין וְכָל מְסָאֲבוּ דְעָלְמָא.</p>\n<p>רִבִּי שִׁמְעוֹן פָּתַח וְאֲמַר, (תהילים כ״ו:ו׳) אֶרְחַץ בְּנִקָּיוֹן כַּפָּי וַאֲסוֹבְבָה אֶת מִזְבַּחֲךָ יְיָ, הַאי קְרָא אוּקְמוּהָ. אֲבָל תָּא חֲזֵי, רָזָא דְמִלָּה הָכָא, דְּהָא לֵית לָךְ בַּר נָשׁ בְּעַלְמָא דְּלָא טָעִים טַעְמָא דְמוֹתָא בְּלֵילְיָא, וְרוּחַ מְסָאֲבָא שַׁרְיָא עַל הַהוּא גוּפָא. מַאי טַעְמָא, בְּגִין דְּנִשְׁמָתָא קַדִּישָׁא אִסְתַּלְּקַת מִנֵּיהּ דְּבַר נָשׁ, וְנָפְקַת מִנֵּיהּ. וְעַל דְּנִשְׁמָתָא קַדִּישָׁא נָפְקַת וְאִסְתַּלְּקַת מִנִּיהּ, שַׁרְיָא רוּחָא מְסָאֲבָא עַל הַהוּא גוּפָא וְאִסְתָּאַב.</p>\n<p>וְכַד נִשְׁמָתָא אִתְהַדְּרַת לְגוּפָא, אִתְעֲבַר הַהוּא זוּהֲמָא. וְהָא אִתְּמָר דִּידוֹי דְּבַר נָשׁ זוּהֲמָא דִמְסָאֲבוּ אִשְׁתָּאַר בְּהוּ. וְעַל דָּא לָא יַעֲבָר יְדוֹי עַל עֵינוֹי, בְּגִין דְּהַהוּא רוּחַ מְסָאֲבָא שַׁרְיא עֲלוֹי, עַד דְּנָטִיל לוֹן. וְכַד נָטִיל יְדוֹי כְּדְקָא חָזֵי, כְּדֵין אִתְק3ַדּשׁ וְאִקְרֵי קָדוֹשׁ.</p>\n<p>וְהֵיךָ בָּעֵי לְאִתְקַדְּשָׁא. בָּעֵי חַד כְּלִי לְתַתָּא וְחַד כְּלִי מִלְּעֵילָא, בְּגִין דְּיִתְקַדַּשׁ מֵהַהוּא דִלְעֵילָא. וְהַהוּא דִלְתַתָּא דְּיָתִיב בְּזוּהֲמָא דִּמְסָאֲבוּ בֵּיהּ. וְדָא כְּלִי לְקַבְּלָא מְסָאֲבוּ, וְדָא לְאִתְקַדְּשָׁא מִנֵּיהּ, דָּא בָּרוּךְ וְדָא אָרוּר. וְלָא בָּעְיָין אִינוּן מַיִין דְּזוּהֲמָא לְאוֹשְׁדָא לוֹן בְּבֵיתָא, דְּלָא יִקְרַב בְּהוּ בַּר נָשׁ. דְּהָא בְּהוּ מִתְכַּנְּשֵׁי סִטְרָא דִלְהוֹן, יָכִיל לְקַבְּלָא נִזְקָא מֵאִינוּן מַיִין מְסָאֲבִין.</p>\n<p>וְעַד דְּיִתְעֲבַר זוּהֲמָא מִן יְדוֹי לָא יְבָרֵךְ, וְאוֹקִימְנָא. וּבְגִין כָּךְ, בַּר נָשׁ עַד לָא יְקַדֵּשׁ יְדוֹי בְּצַפְרָא, אִקְרֵי טָמֵא. כֵּיוָן דְּאִתְקַדַּשׁ אִקְרֵי טָהוֹר. וּבְגִין כָּךְ לָא יִטּוֹל אֶלָּא מִן יְדָא דְּאִדְכֵּי בְּקַדְמִיתָא. דִּכְתִיב, (במדבר י״ט:י״ט) וְהִזָּה הַטָּהוֹר עַל הַטָּמֵא. דָּא אִקְרֵי טָהוֹר, וְדָא אִקְרֵי טָמֵא.</p>\n<p>בְּגִין כָּךְ חַד כְּלִי לְעֵילָא וְחַד כְּלִי לְתַתָּא, דָּא קַדִּישָׁא וְדָא מְסָאֲבָא. וּמֵאִינוּן מַיִין אָסִיר לְמֶעְבַּד בְּהוּ מִידִי, אֶלָּא בָּעֵי לְאוֹשְׁדָא לוֹן בְּאֲתַר דִּבְנֵי נָשָׁא לָא עָבְרִין עֲלַיְיהוּ, וְלָא יָבִית לוֹן בְּבֵיתָא. דְּהָא כֵּיוָן דְּאִתּוֹשְׁדָן בְּאַרְעָא, רוּחָא מְסָאֲבָא אִשְׁתַּכַּח תַּמָּן וְיָכִיל לְנַזְקָא. וְאִי חָפַר לוֹן מִדְרוֹן תְּחוֹת אַרְעָא דְּלָא יִתְחֲזוּן שַׁפִּיר.</p>\n<p>וְלָא יָהִיב לוֹן לִנְשֵׁי חֳרָשַׁיָא דְּיִכְלוּן לְאַבְאָשָׁא בְּהוּ לִבְנִי נָשָׁא. בְּגִין דְּאִינוּן מַיִין דְּאִתְלַטְיָין, וְקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי לְדַכָּאָה לוֹן לְיִשְׂרָאֵל וּלְמֶהֱוֵי קַדִּישִׁין. דִּכְתִיב, (יחזקאל ל״ו:כ״ה) וְזָרַקְתִּי עֲלֵיכֶם מַיִם טְהוֹרִים וּטְהַרְתֶּם מִכֹּל טֻמְאוֹתֵיכֶם וּמִכָּל גִּלּוּלֵיכֶם אֲטַהֵר אֶתְכֶם:</p>"],[9520011383,"<p>וַיִּקָּחֻהוּ וַיַּשְׁלִכוּ אֹתוֹ הַבֹּרָה וְהַבּוֹר רֵק אֵין בּוֹ מָיִם. רִבִּי יְהוּדָה פָּתַח וְאֲמַר, (תהילים י״ט:ח׳) תּוֹרַת יְיָ תְּמִימָה מְשִׁיבַת נָפֶשׁ (מאן דבטיל מילי דאורייתא כאילו חריב עלמא שלים). כַּמָּה אִית לוֹן לִבְנֵי נָשָׁא לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, דְּכָל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא לֶהוֵי לֵיהּ חַיִּים בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי, וְזָכֵי בִּתְרֵין עָלְמִין. וְאֲפִילּוּ מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא וְלָא יִשְׁתַּדַּל בָּהּ לִשְׁמָהּ כְּדְקָא יָאוֹת, זָכֵי לְאֲגַר טַב בְּעַלְמָא דֵין, וְלָא דָיְינִין לֵיהּ בְּהַהוּא עַלְמָא.</p>\n<p>וְתָּא חֲזֵי, כְּתִיב, (משלי ג׳:ט״ז) אֹרֶךְ יָמִים בִּימִינָהּ בִּשְׂמֹאלָהּ עשֶׁר וְכָבוֹד. אֹרֶךְ יָמִים בְּהַהוּא דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא לִשְׁמָהּ, דְּאִית לֵיהּ אֹרֶךְ יָמִים בְּהַהוּא עַלְמָא דְּבֵיהּ אוֹרְכָא דְיוֹמִין. וְאִינוּן יוֹמִין אִינוּן יוֹמִין וַדַּאי, תַּמָּן אִיהוּ רָחֲצָנוּ דִקְדוּשָׁא דִלְעֵילָא דְּאִתְרְחִיץ בַּר נָשׁ בְּהַאי עַלְמָא לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, לְאִתְתַּקְּפָא בְּהַהוּא עַלְמָא <Nonei></i>בִּשְׂמֹאלָהּ עוֹשֶׁר וְכָבוֹד, אֲגַר טַב וְשַׁלְוָה אִית לֵיהּ בְּהַאי עַלְמָא.</p>\n<p>וְכָל מַאן דְּיִשְׁתַּדַּל בְּאוֹרַיְיתָא לִשְׁמָהּ, כַּד נָפִיק מֵהַאי עַלְמָא, אוֹרַיְיתָא אָזְלָא קַמֵּיהּ וְאַכְרָזַת קַמֵּיהּ וְאֲגִינַת עֲלֵיהּ, דְּלָא יִקְרְבוּן בַּהֲדֵיהּ מָארֵיהוֹן דְּדִינָא. כַּד שָׁכִיב גּוּפָא בְּקִבְרָא, הִיא נָטְרַת לֵיהּ. כַּד נִשְׁמָתָא אָזְלָא לְאִסְתַּלְּקָא לְמֵיתַב לְאַתְרָהּ, אִיהִי אָזְלָא קַמָּהּ דְּהַהִיא נִשְׁמָתָא. וְכַמָּה תַּרְעִין אִתָּבְרוּ מִקַּמָּהּ דְּאוֹרַיְיתָא עַד דְּעָאלַת לְדוּכְתָּהּ. וְקָיְימָא עֲלֵיהּ דְּבַר נָשׁ עַד דְּיִתְעַר בְּזִמְנָא דִּיקוּמוּן מֵתַיָיא דְעַלְמָא, וְאִיהִי מַלְפָא סַנֵּיגוֹרָא עֲלֵיהּ.</p>\n<p>הֲדָא הוּא דִכְתִיב, (משלי ו׳:כ״ב) בְּהִתְהַלֶּכְךָ תַּנְחֶה אֹתָךְ בְּשָׁכְבְּךָ תִּשְׁמֹר עָלֶיךָ וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךָ. בְּהִתְהַלֶּכְךָ תַּנְחֶה אֹתָךְ, כְּמָה דְאִתְּמָר. בְּשָׁכְבְּךָ תִּשְׁמֹר עָלֶיךָ, בְּשַׁעְתָּא דְּשָׁכִיב גּוּפָא בְּקִבְרָא, דְּהָא כְּדֵין בְּהַהוּא זִמְנָא אִתְדָּן גּוּפָא בְּקִבְרָא וּכְדֵין אוֹרַיְיתָא אֲגִינַת עֲלֵיהּ. וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךָ כְּמָא דְאִתְּמָר בְּזִמְנָא דְּיִתְעָרוּן מֵתֵי עַלְמָא מִן עַפְרָא. הִיא תְשִׂיחֶךָ לְמֶהֱוֵי סַנֵּיגוֹרְיָא עֲלָךְ.</p>\n<p>רִבִּי אֶלְעָזָר אָמַר, הִיא תְשִׂיחֶךָ. מַאי הִיא תְשִׂיחֶךָ. בְּגִין דְּאַף עַל גַּב דְּהַשְׁתָּא יְקוּמוּן מֵעַפְרָא, אוֹרַיְיתָא לָא יִתְנְשֵׁי מִנְּהוֹן. דְּהָא כְּדֵין יִנְדְּעוּן כָּל הַהִיא אוֹרַיְיתָא דְּשָׁבְקוּ כַּד אִסְתַּלְקוּ מֵהַאי עַלְמָא, הַהִיא אוֹרַיְיתָא נְטִירָא מֵהַהוּא זִמְנָא וְתִיעוּל בְּמֵעַיְיהוּ כְּמִלְּקַדְּמִין וְאִיהִי תְּמַלֵּל בְּמֵעַיְיהוּ.</p>\n<p>וְכָל מִלִּין מִתְתַּקְּנָן יַתִּיר מִכְּמָה דְּהֲווּ בְּקַדְמִיתָא, דְּהָא כָּל אִינוּן מִלִּין דְּאִיהוּ לָא יָכִיל לְאַדְבָּקָא לוֹ כְּדְקָא יָאוֹת וְאִיהוּ אִשְׁתַּדַּל בְּהוּ וְלָא אִתְדָּבַּק בְּהוּ. כֻּלְּהוּ עָאלִין בְּמֵעוֹי מִתְתַּקְנָן, וְאוֹרַיְיתָא תְּמַלֵּל בֵּיהּ. הֲדָא הוּא דִכְתִיב וַהֲקִיצוֹתָ הִיא תְשִׂיחֶךָ. רִבִּי יְהוּדָה אָמַר, כְּגַוְונָא דָא כָּל מַאן דְּאִשְׁתַּדַּל בְּאוֹרַיְיתָא בְּהַאי עַלְמָא, זָכֵי לְאִשְׁתַּדְּלָא בָּהּ לְעַלְמָא דְאָתֵי וְהָא אִתְּמָר.</p>\n<p>תָּא חֲזֵי, הַהוּא בַר נָשׁ דְּלָא זָכֵי לְאִשְׁתַּדְּלָא בְּהַאי עַלְמָא בְּאוֹרַיְיתָא, וְאִיהוּ אָזִיל בְּחֲשׁוֹכָא, כַּד נָפִיק מֵהַאי עַלְמָא, נָטְלִין לֵיהּ וְעָאלִין לֵיהּ לַגֵּיהִנֹּם, אֲתַר תַּתָּאָה דְּלָא יְהֵא מְרַחֵם עֲלֵיהּ, דְּאִקְרֵי בּוֹר שָׁאוֹן טִיט הַיָּוֵן. כְּמָה דְאַתְּ אָמֵר, (תהילים מ׳:ג׳) וַיַּעֲלֵנִי מִבּוֹר שָׁאוֹן מִטִּיט הַיָּוֵן וַיָּקֶם עַל סֶלַע רַגְלָי כּוֹנֵן אֲשׁוּרָי.</p>\n<p>וּבְּגִין כָּךְ הַהוּא דְּלָא אִשְׁתַּדַּל בְּאוֹרַיְיתָא בְּהַאי עַלְמָא וְאִתְטַנַּף בְּטִנּוּפֵי עַלְמָא, מַה כְּתִיב וַיִּקָּחֻהוּ וַיַּשְׁלִיכוּ אֹתוֹ הַבּוֹרָה. דָּא הוּא גֵּיהִנֹּם, אֲתַר דְּדַיְינִין לְהוּ לְאִינוּן דְּלָא אִשְׁתַּדְּלוּ בְּאוֹרַיְיתָא. וְהַבּוֹר רֵק, כְּמָה דְאִיהוּ הֲוָה רֵק. מַאי טַעְמָא בְּגִין דְּלָא הֲוָה בֵּיהּ מַיִם.</p>\n<p>וְתָא חֲזֵי, כַּמָּה הוּא עוֹנְשָׁא דְּאוֹרַיְיתָא, דְּהָא לָא אִתְגָּלוּ יִשְׂרָאֵל מֵאַרְעָא קַדִּישָׁא, אֶלָּא בְּגִין דְּאִסְתַּלָּקוּ מֵאוֹרַיְיתָא, וְאִשְׁתְּבָקוּ מִינָהּ. הֲדָא הוּא דִכְתִיב, (ירמיהו ט׳:י״א) מִי הָאִישׁ הֶחָכָם וְיָבֵן אֶת זֹאת וְגו' עַל מַה אָבְדָה הָאָרֶץ וְגו'. וַיֹּאמֶר יְיָ עַל עָזְבָם אֶת תּוֹרָתִי וְגו'. רִבִּי יוֹסֵי אָמַר, מֵהָכָא, (ישעיהו ה׳:י״ג) לָכֵן גָּלָה עַמִּי מִבְּלִי דָעַת.</p>\n<p>בְּגִין כָּךְ כֹּלָּא קָיְימָא עַל קִיּוּמָא דְאוֹרַיְיתָא, וְעַלְמָא לָא אִתְקְיַּים בְּקִיּוּמֵיהּ אֶלָּא בְּאוֹרַיְיתָא, דְּאִיהוּ קִיּוּמָא דְעָלְמִין עֵילָא וְתַתָּא דִּכְתִיב, (ירמיהו ל״ג:כ״ה) אִם לא בְרִיתִי יוֹמָם וָלַיְלָה חֻקּוֹת שָׁמַיִם וָאָרֶץ לא שָׂמְתִּי:</p>\n<p>וַיִּקָּחֻהוּ וַיַּשְׁלִיכוּ אוֹתוֹ הַבּוֹרָה, רָמַז עַל דְּאַרְמִיאוּ לֵיהּ לְגוֹ מִצְרָאֵי אֲתַר דְּלָא אִשְׁתַּכַּח רָזָא דִמְהֵימְנוּתָא כְּלָל. רִבִּי יִצְחָק אָמַר, אִי נְחָשִׁין וְעַקְרַבִּין הֲווּ בֵּיהּ, אַמַּאי כְּתִיב בִּרְאוּבֵן לְמַעַן הַצִּיל אוֹתוֹ מִיָּדָם לַהֲשִׁיבוֹ אֶל אָבִיו. וְכִי לָא חַיִּישׁ רְאוּבֵן לְהַאי. דְּהָא אִינוּן נְחָשִׁין וְעַקְרַבִּין יְנַזְקוּן לֵיהּ, וְאֵיךְ אָמַר לַהֲשִׁיבוֹ אֶל אָבִיו, וּכְתִיב לְמַעַן הַצִּיל אוֹתוֹ.</p>\n<p>אֶלָּא חָמָא רְאוּבֵן דְּנִזְקָא אִשְׁתַּכַּח בִּידַיְיהוּ דְּאֲחוֹי, בְּגִין דְּיָדַע כַּמָּה שָׂנְאִין לֵיהּ וּרְעוּתָא דִלְהוֹן לְקָטְלָא לֵיהּ. אָמַר רְאוּבֵן, טַב לְמִנְפַּל לֵיהּ לְגוֹ גּוֹבָא דִּנְחָשִׁין וְעַקְרַבִּין, וְלָא יִתְמְסַר בִּידָא דְּשַׂנְאוֹי דְּלָא מְרַחֲמֵי עֲלֵיהּ. מִכָּאן אָמְרוּ יַפִּיל בַר נָשׁ גַּרְמֵיהּ לְאֶשָׁא אוֹ לְגוּבָא דִּנְחָשִׁין וְעַקְרַבִּין, וְלָא יִתְמַסַּר בִּידָא דְּשַׂנְאוֹי (דזעירין אינון דיכלי לאשתזבא. ובגין כך אמר למען הציל אותו מידם).</p>\n<p><Nonei></i>בְּגִין דְּהָכָא אֲתַר דִּנְחָשִׁים וְעַקְרַבִּים. אִי אִיהוּ צַדִּיקָא, קוּדְשָׁא בְּרִיךְ הוּא יַרְחִישׁ לֵיהּ נִיסָא. וּלְזִמְנִין דִּזְכוּ דְּאֲבָהָן מְסַיְיעִין לֵיהּ לְבַר נָשׁ וְיִשְׁתְּזִיב מִנַּיְיהוּ. אֲבָל כֵּיוָן דְּיִתְמַסַּר בִּידָא דְּשַׂנְאוֹי, זְעִירִין אִינוּן דְּיָכְלִין לְאִשְׁתְּזָבָא.</p>\n<p>וּבְגִין כָּךְ אָמַר, לְמַעַן הַצִּיל אוֹתוֹ מִיָּדָם. מִיָּדָם דַּיְיקָא, וְלָא כְּתִיב לְמַעַן הַצִּיל אוֹתוֹ וְתוּ לָא. אֶלָּא אָמַר רְאוּבֵן, יִשְׁתְּזִיב מִן יְדַיְיהוּ, וְאִי יְמוּת בְּגוּבָא יְמוּת. וּבְגִין כָּךְ כְּתִיב וַיִּשְׁמַע רְאוּבֵן וַיַּצִּילֵהוּ מִיָּדָם.</p>\n<p>תָּא חֲזֵי, כַּמָּה חֲסִידוּתֵיהּ דִּרְאוּבֵן, דִּבְגִין דְּיָדַע דְּשִׁמְעוֹן וְלֵוִי שׁוּתְּפוּתָא וַחֲכִימוּתָא וְחַבְרוּתָא דִּלְהוֹן, קַשְׁיָא אִינוּן. דְּכַד אִתְחַבָּרוּ בִּשְׁכֶם, קָטְלוּ כָּל דְּכוּרָא (ס\"א ל\"ג והא דקטלו כל דכורא) לָא דַי לוֹן. אֶלָּא דְּנָטְלִין נָשִׁין וָטַף וְכַסְפָּא וְדַהֲבָא וְכָל בְּעִירֵי וְכָל מָאנֵי דִיקָר וְכָל מַאן דְּאִשְׁתַּכַּח בְּקַרְתָּא. וְלָא דַי כָּל דָא, אֶלָּא דְּאָפִילּוּ כָּל מַה דִּבְחַקְלָא נָטְלוּ. דִּכְתִיב, (בראשית לה) וְאֶת אֲשֶׁר בָּעִיר וְאֶת אֲשֶׁר בַּשָּׂדֶה לָקָחוּ.</p>\n<p>אָמַר, וּמַה קַּרְתָּא רַבָּתָא כִּי הַאי לָא אִשְׁתְּזִיב מִנְּהוֹן, אִלְמָלֵא רַבְיָא דָא יִפּוֹל בִּידַיְיהוּ, לָא יַשְׁאֲרוּן מִנֵּיהּ אוּמְצָא בְּעַלְמָא. וְעַל דָּא אָמַר, טַב לְאִשְׁתְּזָבָא מִנַּיְיהוּ דְּלָא יַשְׁאֲרוּן מִנֵּיהּ אִשְׁתָּאֲרוּתָא בְּעַלְמָא, וְלָא יֶחמֵי אַבָּא מִנֵּיהּ כְּלוּם לְעָלְמִין.</p>\n<p>וְהָכָא אִי יְמוּת, לָא יָכְלִין לֵיהּ וְיִשְׁתָּאַר כָּל גּוּפֵיהּ שְׁלִים, וַאֲתִיב לֵיהּ לְאַבָּא שְׁלִים. וְעַל דָּא לְמַעַן הַצִּיל אוֹתוֹ מִיָּדָם לַהֲשִׁיבוֹ אֶל אָבִיו, אַף עַל גַּב דִּימוּת הָתָם. וּבְגִין כָּךְ אָמַר הַיֶּלֶד אֵינֶנּוּ. וְלָא אָמַר אֵינְנּוּ חַי, אֶלָּא אָמַר אֵינֶנּוּ, אֲפִילּוּ מֵת.</p>\n<p>תָּא חֲזֵי, מַאי דְּעֲבַד, דְּאִיהוּ בְּחָכְמְתָא הֲוָה שַׁתִּיף גַּרְמֵיהּ בַּהֲדַיְיהוּ, דִּכְתִיב לא נַכֶּנּוּ נָפֶשׁ, וְלָא כְּתִיב לָא תַכּוּהוּ. וְאִיהוּ לָא הֲוָה תַּמָּן כַּד אִזְדַּבַּן יוֹסֵף, דְּהָא כֻּלְּהוּ מְשַׁמְּשֵׁי לַאֲבוּהוֹן כָּל חַד וְחַד יוֹמָא חַד. וְהַהוּא יוֹמָא דִרְאוּבֵן הֲוָה. וְעַל דָּא בָּעָא דִּבְהַהוּא יוֹמָא דְּהֲוָה שִׁמּוּשָׁא דִילֵיהּ לָא יִתְאֲבִיד יוֹסֵף. וּבְגִין כָּךְ כְּתִיב וַיָּשָׁב רְאוּבֵן אֶל הַבּוֹר וְהִנֵּה אֵין יוֹסֵף בַּבּוֹר וַיִּקְרַע אֶת בְּגָדָיו. וְהִנֵה אֵין יוֹסֵף דַּיְיקָא. אֲפִילּוּ (חי או) מִית, מִיָּד וַיָּשָׁב אֶל אֶחָיו וַיֹּאמֶר הַיֶּלֶד אֵינֶנּוּ.</p>\n<p>וְאֲפִילּוּ רְאוּבֵן לָא יָדַע מֵהַהוּא זְבִינָא דְיוֹסֵף, וְהָא אוּקְמוּהָ דְּאִשְׁתַּתִּיף בְּהוּ שְׁכִינְתָּא, וְעַל דָּא לָא יָדַע רְאוּבֵן מֵהַהוּא זְבִינָא דְיוֹסֵף וְלָא אִתְגַלְיָיא לֵיהּ עַד הַהוּא זִמְנָא דְּאִתְגְּלֵי יוֹסֵף לַאֲחוֹהִי.</p>\n<p>תָּא חֲזֵי, כַּמָּה גָּרִים לֵיהּ לִרְאוּבֵן בְּגִין דְּאִיהוּ אִשְׁתַּדַּל לְאַחֲיָיא לֵיהּ לְיוֹסֵף, מַה כְּתִיב, (דברים ל״ג:ו׳) יְחִי רְאוּבֵן וְאַל יָמוֹת וְגו'. דְּהָא בְּגִין דָּא, אַף עַל גַּב דְּיָדַע דְּאִשְׁתְּקִיל בְּכֵירוּתֵיהּ מִנֵּיהּ וְאִתְיְהִיב לְיוֹסֵף, אִשְׁתַּדַּל לְאֲחַיָיא לֵיהּ, וְצַלֵּי משֶׁה וְאֲמַר יְחִי רְאוּבֵן וְאַל יָמוֹת, וְאִתְקְיַּים בְּעַלְמָא דֵין וְאִתְקְיַּים בְּעַלְמָא דְאָתֵי. מַאי טַעְמָא, בְּגִין דָּא, וּבְגִין דְּעֲבַד תְּשׁוּבָה מֵהַהוּא עוֹבָדָא. דְּכָל מַאן דְּעָבִיד תְּשׁוּבָה, קוּדְשָׁא בְּרִיךְ הוּא קַיַּים לֵיהּ בְּעַלְמָא דֵין וּבְעַלְמָא דְאָתֵי.</p>\n<p>תָּא חֲזֵי מַה כְּתִיב, וַיִּקְחוּ אֶת כְּתֹנֶת יוֹסֵף וְגו', הָא אוּקְמוּהָ דִּבְגִין דְּדָמָא דְּשָׂעִיר דַּמְיָא לְדָמָא דְבַר נָשׁ. אֲבָל תָּא חֲזֵי, אַף עַל גַּב דְּמִלָּה אַתְיָא כְּדְקָא חָזֵי, קוּדְשָׁא בְּרִיךְ הוּא מְדַקְדֵּק בְּהוּ בְּצַדִּיקַיָיא אֲפִילּוּ כְּחוּט הַשַּׂעֲרָה.</p>\n<p>יַעֲקֹב עָבַד עוֹבָדָא כְּדְקָא יָאוֹת. בְּמַאי, בְּגִין דְּאַקְרִיב לְגַבּוֹי אֲבוֹי שָׂעִיר, דְּאִיהוּ סִטְרָא דְּדִינָא קַשְׁיָא. וְעִם כָּל דָּא, בְּגִין דְּאִיהוּ אַקְרִיב שָׂעִיר וְאַכְּחִישׁ לֵיהּ לְאֲבוֹי דְּאִיהוּ סִטְרָא דִילֵיהּ, אִתְעֲנַשׁ בְּהַאי שָׂעִיר אָחֳרָא, דְּאַקְרִיבוּ לֵיהּ בְּנוֹי דָמָא דִילֵיהּ.</p>\n<p>בְּאִיהוּ כְּתִיב, (בראשית כ״ז:ט״ז) וְאֵת עוֹרוֹת גְּדָיֵי הָעִזִּים הִלְבִּישָׁה עַל יָדָיו וְעַל חֶלְקַת צַוָּארָיו, בְּגִין כָּךְ וַיִּטְבְּלוּ אֶת הַכֻּתֹּנֶת בַּדָּם, אַקְרִיבוּ לֵיהּ כֻּתּוֹנְתָּא לְאַכְּחָשָׁא לֵיהּ, וְכֹלָּא דָּא לָקֳבֵל דָּא, אִיהוּ גָּרִים דִּכְתִיב וַיֶּחרַד יִצְחָק חֲרָדָה גְדוֹלָה עַד מְאֹד, בְּגִין כָּךְ גָּרְמוּ לֵיהּ דְּחָרַד חֲרָדָה בְּהַהוּא זִמְנָא דִּכְתִיב הַכֶּר נָא הַכְּתֹנֶת בִּנְךָ הִיא אִם לֹא.</p>\n<p><Nonei></i>רִבִּי חִיָּיא אָמַר, בֵּיהּ כְּתִיב, (בראשית כ״ז:כ״א) הַאַתָּה זֶה בְּנִי עֵשָׂו אִם לֹא. לֵיהּ כְּתִיב, הַכְּתֹנֶת בִּנְךָ הִיא אִם לא. וּבְּגִין כָּךְ קוּדְשָׁא בְּרִיךְ הוּא מְדַקְדֵּק בְּהוּ בְּצַדִּיקַיָא בְּכָל מַה דְּאִינוּן עָבְדִין.</p>\n<p>רִבִּי אַבָּא אָמַר, (נ\"א אמרז רבי אבא) כֵּיוָן דְּחָמוּ כֻּלְּהוּ שִׁבְטִין הַהוּא צַעֲרָא דְּאֲבוּהוֹן, אִתְנֶחָמוּ וַודַּאי, וִיהִיבוּ גַּרְמַיְיהוּ עֲלֵיהּ דְּיוֹסֵף, דְּיִפְדוּן לֵיהּ אִלְמָלֵא יִשְׁכְּחוּן לֵיהּ. כֵּיוָן דְּחָמוּ דְּלָא יָכִילוּ, אַהֲדָרוּ לְגַבֵּיהּ דִּיהוּדָה וְאַעֲבָרוּ לֵיהּ מֵעֲלַיְיהוּ, בְּגִין דְּאִיהוּ הֲוָה מַלְכָּא עֲלַיְיהוּ. (וכדין ס\"א וכיון ד) אַעֲבָרוּהוּ מֵעֲלַיְיהוּ, מַה כְּתִיב, וַיְהִי בָּעֵת הַהִיא וַיֵּרֶד יְהוּדָה וְגו'.</p>"],[9520011384,"<p>רִבִּי יְהוּדָה פָּתַח וְאֲמַר, (תהילים י״ח:י״ד) וַיַּרְעֵם בַּשָּׁמַיִם יְיָ וְעֶלְיוֹן יִתֵּן קוֹלוֹ בָּרָד וְגַחֲלֵי אֵשׁ. תָּא חֲזֵי, כַּד בָּרָא קוּדְשָׁא בְּרִיךְ הוּא עַלְמָא, אַתְקִין לֵיהּ שִׁבְעָה סְמָכִין עַל מַה דְּקָיְימָא, וְכֻלְּהוּ סְמָכִין קָיְימֵי בְּחַד סָמְכָא יְחִידָאי, וְהָא אוּקְמוּהָ. דִּכְתִיב, (משלי ט׳:א׳) חַכְמוֹת נָשִׁים בָּנְתָה בֵיתָהּ חָצְבָה עַמּוּדֶיהָ שִׁבְעָה. וְאִלֵּין כֻּלְּהוּ אִינוּן קָיְימֵי בְּחַד דַּרְגָּא מִנַּיְיהוּ דְּאִקְרֵי (משלי י׳:כ״ה) צַדִּיק יְסוֹד עוֹלָם.</p>\n<p>וְעַלְמָא כַּד אִתְבְּרֵי, מֵהַהוּא אֲתַר אִתְבְּרֵי. דְּאִיהוּ שִׁכְלוּלָא דְּעַלְמָא, וְתִקּוּנוֹי. דְּאִיהוּ חַד נְקוּדָה דְעַלְמָא, וְאֶמְצָעִיתָא דְכֹלָּא. וּמַאן אִיהוּ, צִיּוֹן. דִּכְתִיב, (תהילים נ׳:א׳) מִזְמוֹר לְאָסָף אֵל אֱלֹהִים יְיָ דִּבֶּר וַיִּקְרָא אֶרֶץ מִמִּזְרַח שֶׁמֶשׁ עַד מְבוֹאוֹ. וּמֵאָן אֲתַר, מִצִּיּוֹן, דִּכְתִיב מִצִּיּוֹן מִכְלַל יוֹפִי אֱלֹהִים הוֹפִיעַ. מֵהַהוּא אֲתַר דְּאִיהוּ סִטְרָא דְּשִׁכְלוּלָא דִּמְהֵימְנוּתָא שְׁלֵימָתָא כְּדְקָא יְאוּת (והשתא (עי' קמא א כי שם מקומו) ישראל אתתקפו ביה ברזי דפקודי דאורייתא בגין דכל יומא ויומא אתתקף בר נש בציצית דאתעטף ביה). וְצִיּוֹן תַּקִּיפוּ וּנְקוּדָה דְּכָל עַלְמָא, וּמֵהַהוּא אֲתַר אִשְׁתַּכְלַל כָּל עַלְמָא וְאִתְעֲבִיד, וּמִגַּוֵּיהּ כָּל עַלְמָא אִתְּזָן.</p>\n<p>וְתָּא חֲזֵי, וַיַּרְעֵם בַּשָּׁמַיִם יְיָ וְעֶלְיוֹן יִתֵּן קוֹלוֹ וְגו', כֵּיוָן דְּאָמַר וַיַּרְעֵם בַּשָּׁמַיִם יְיָ, אַמַּאי כְּתִיב וְעֶלְיוֹן יִתֵּן קוֹלוֹ. הָא (ס\"א אלא) הָכָא רָזָא דִּמְהֵימְנוּתָא, (ועל מה ס\"א עלמא) דְּאֲמִינָא דְּצִיּוֹן אִיהוּ שִׁכְלוּלָא וְשַׁפִּירוּ דְּעַלְמָא, וְעַלְמָא מִנֵּיהּ אִתְּזָן. בְּגִין דִּתְרֵין דַּרְגִּין אִינוּן וְאִינוּן חַד, אִינוּן צִיּוֹן וִיְרוּשָׁלַם. דָּא דִינָא וְדָא רַחֲמֵי, וְתַרְוַיְיהוּ חַד, מֵהָכָא דִּינָא וּמֵהָכָא רַחֲמֵי.</p>\n<p>מֵעֵילָא לְעֵילָא נָפְקָא קוֹל דְּאִשְׁתְּמַע, לְבָתַר דְּהַהוּא קוֹל נָפְקָא וְאִשְׁתְּמַע נָפְקֵי דִינִין וְאָרְחֵי דְּדִינָא, וְרַחֲמֵי נָפְקִין וּמִתְפָּרְשָׁן מִתַּמָּן. וַיַּרְעֵם בַּשָּׁמַיִם יְיָ, דָּא בֵּי דִינָא בְּרַחֲמֵי. וְעֶלְיוֹן, אַף עַל גַּב דְּלָא אִשְׁתַּכַּח וְלָא אִתְיְידַע, כֵּיוָן דְּהַהוּא קוֹל נָפִיק כְּדֵין אִשְׁתַּכַּח כֹּלָּא, דִּינָא וְרַחֲמֵי. הֲדָא הוּא דִכְתִיב וְעֶלְיוֹן יִתֵּן קוֹלוֹ, כֵּיוָן דְּיִתֵּן קוֹלוֹ, כְּדֵין בָּרָד וְגַחֲלֵי אֵשׁ, מַיָא וְאֶשָׁא.</p>\n<p>תָּא חֲזֵי, בְּשַׁעְתָּא דְּאִתְיְלִיד יְהוּדָה מַה כְּתִיב, (בראשית כט) וַתַּעֲמֹד מִלֶּדֶת, בְּגִין דְּדָא הוּא יְסוֹדָא רְבִיעָאָה מֵאִינוּן אַרְבַּע דְּאִינוּן רְתִיכָא עִלָּאָה, סַמְכָא חַד מֵאִינוּן אַרְבַּע סַמְכִין. מַה כְּתִיב בֵּיהּ, וַיְהִי בָּעֵת הַהִיא וַיֵּרֶד יְהוּדָה מֵאֵת אֶחָיו, דְּהֲוָה מַלְכָּא עֲלַיְיהוּ. מַאי טַעְמָא, בְּגִין דְּיוֹסֵף נָחֲתוּ לֵיהּ לְמִצְרַיִם כִּדְקָאֲמָרָן:</p>"],[9520011385,"<p>וַיַּרְא שָׁם יְהוּדָה בַּת אִישׁ כְּנַעֲנִי. וְכִי כְּנַעֲנִי הֲוָה, אֶלָּא הָא אוּקְמוּהָ חַבְרַיָּיא. וַתַּהַר וַתֵּלֶד בֵּן וַיִּקְרָא אֶת שְׁמוֹ עֵר, תְּלַת בְּנִין הֲווּ לֵיהּ לִיהוּדָה, וְלָא אִשְׁתָּאֲרוּ מִנַּיְיהוּ בַּר חַד, וְדָא הוּא שֵׁלָה.</p>\n<p>רִבִּי אֶלְעָזָר וְרִבִּי יוֹסֵי וְרִבִּי חִיָּיא הֲווּ אָזְלֵי בְּאָרְחָא. אָמַר רִבִּי יוֹסֵי לְרִבִּי אֶלְעָזָר, אַמַּאי כְּתִיב בִּבְנוֹי דִּיהוּדָה, בְּקַדְמָאָה וַיִּקְרָא אֶת שְׁמוֹ עֵר, וּבִתְרֵין אָחֳרָנִין כְּתִיב וַתִּקְרָא אֶת שְׁמוֹ אוֹנָן, וַתִּקְרָא אֶת שְׁמוֹ שֵׁלָה.</p>\n<p>אָמַר לֵיהּ תָּא חֲזֵי, הַאי פָּרְשָׁתָא רָזָא עִלָּאָה אִיהוּ, וְכֹלָּא אִיהוּ כְּדְקָא חָזֵי. וַיֵּרֶד יְהוּדָה מֵאֵת אֶחָיו, דְּהָא אִתְכַּסְיָא סִיהֲרָא, וְנָחֲתַת מִדַּרְגָּא דְּתִקֻּנָּא לְגוֹ דַּרְגָּא אוֹחֲרָא, דְּאִתְחַבַּר בֵּיהּ חִוְּיָא, כְּמָה דְאַתְּ אָמֵר וַיֵּט עַד אִישׁ עֲדֻלָּמִי וּשְׁמוֹ חִירָה.</p>\n<p>וַתַּהַר וַתֵּלֶד בֵּן וַיִּקְרָא אֶת שְׁמוֹ עֵר, וְאִיהוּ רַע, וְכֹלָּא חַד, דְּאַתְיָא מִסִּטְרָא דְיֵצֶר הָרָע. וּבְגִין כָּךְ כְּתִיב וַיִּקְרָא אֶת שְׁמוֹ, וְלָא כְּתִיב וַיִּקְרָא שְׁמוֹ. <Nonei></i>בְּיַעֲקֹב כְּתִיב וַיִּקְרָא שְׁמוֹ, דְּקוּדְשָׁא בְּרִיךְ הוּא קָרָא לֵיהּ יַעֲקֹב. וְהָכָא אֶת לְאַסְגָּאָה דַּרְגָּא אָחֳרָא דְּזוּהֲמָא דִּמְסָאֲבָא אִתְיְלִיד, וְדָא הוּא עֵר רַע, וְכֹלָּא חַד.</p>\n<p>לְבָתַר לָא אִתְבַּסַּם אַתְרָא, עַד דְאֲתָא שֵׁלָה דְּהֲוָה עִקָּרָא דְּכֻלְּהוּ. מַה כְּתִיב וַיְהִי עֵר בְּכֹר יְהוּדָה רַע בְּעֵינִי יְיָ, כְּתִיב הָכָא רַע, וּכְתִיב הָתָם (בראשיתח) כִּי יֵצֶר לֵב הָאָדָם רַע מִנְעוּרָיו, רַע דְּאוֹשִׁיד דָּמִין, אוֹשִׁיד זַרְעָא עַל אַרְעָא. וּבְגִין כָּךְ וַיְמִיתֵהוּ יְיָ. מַה כְּתִיב בַּתְרֵיהּ, וַיֹּאמֶר יְהוּדָה לְאוֹנָן בֹּא אֶל אֵשֶׁת אָחִיךָ וְגו':</p>"]]});
